// Generated public reading views; canonical text and route IDs stay intact.
// care-item-presentation/7
const views = {"CH_KPR_ITDE:MRT2":[["Reconstruction requires CH_KPR_ITDE:A1–CH_KPR_ITDE:A4 to preserve the intuition/concept distinction.","Reconstruction requires axiom A1 in “I. TRANSCENDENTAL DOCTRINE OF ELEMENTS.”–axiom A4 in “I. TRANSCENDENTAL DOCTRINE OF ELEMENTS.” to preserve the intuition/concept distinction."]],"CH_KPR_ITDE:MRT3":[["Reconstruction requires CH_KPR_ITDE:A8–CH_KPR_ITDE:A13 to generate the matter/form and pure-intuition architecture.","Reconstruction requires axiom A8 in “I. TRANSCENDENTAL DOCTRINE OF ELEMENTS.”–axiom A13 in “I. TRANSCENDENTAL DOCTRINE OF ELEMENTS.” to generate the matter/form and pure-intuition architecture."]],"CH_KPR_ITDE:MRT4":[["Reconstruction requires CH_KPR_ITDE:A14–CH_KPR_ITDE:A20 to preserve the empirical-reality/transcendental-ideality closure.","Reconstruction requires axiom A14 in “I. TRANSCENDENTAL DOCTRINE OF ELEMENTS.”–axiom A20 in “I. TRANSCENDENTAL DOCTRINE OF ELEMENTS.” to preserve the empirical-reality/transcendental-ideality closure."]],"CH_KPR_TRANSCENDENTAL_LOGIC:MRT2":[["The decisive hinge is CH_KPR_TRANSCENDENTAL_LOGIC:A20: the identity between judgment-unity and synthetic unity of intuition.","The decisive hinge is this: the identity between judgment-unity and synthetic unity of intuition."]],"CH_KPR_COSMOS_SOLUTION:MRT2":[["The central dependency is CH_KPR_COSMOS_SOLUTION:A4; without transcendental ideality, the entire reconciliation collapses.","The central dependency is axiom A4 in “Cosmos Solution”; without transcendental ideality, the entire reconciliation collapses."]],"CL_KPR_01:GA-01":[["[Persistent] Human cognition begins with experience but cannot derive its necessity, strict universality, or objective validity from experience.","Human cognition begins with experience but cannot derive its necessity, strict universality, or objective validity from experience."]],"CL_KPR_01:GA-02":[["[Persistent] Cognition requires two irreducible sources: sensibility gives objects through intuition, and understanding thinks objects through concepts.","Cognition requires two irreducible sources: sensibility gives objects through intuition, and understanding thinks objects through concepts."]],"CL_KPR_01:GA-03":[["[Persistent] Neither intuition without concepts nor concepts without corresponding intuition constitutes cognition.","Neither intuition without concepts nor concepts without corresponding intuition constitutes cognition."]],"CL_KPR_01:GA-04":[["[Mutating] The a priori first appears as non-empirical validity, then becomes formal sensuous givenness in space and time, then becomes pure conceptual unity in the categories.","The a priori first appears as non-empirical validity, then becomes formal sensuous givenness in space and time, then becomes pure conceptual unity in the categories."]],"CL_KPR_01:GA-05":[["[Persistent] Necessity and strict universality function as diagnostic marks of a priori cognition and as exclusions of empirical derivation.","Necessity and strict universality function as diagnostic marks of a priori cognition and as exclusions of empirical derivation."]],"CL_KPR_01:GA-06":[["[Emergent] Synthetic a priori cognition requires a non-empirical synthesis grounded jointly in pure intuition and pure understanding, not in concepts alone.","Synthetic a priori cognition requires a non-empirical synthesis grounded jointly in pure intuition and pure understanding, not in concepts alone."]],"CL_KPR_01:GA-07":[["[Persistent] Space and time are pure a priori forms of sensibility: empirically real for possible experience and transcendentally ideal with respect to things in themselves.","Space and time are pure a priori forms of sensibility: empirically real for possible experience and transcendentally ideal with respect to things in themselves."]],"CL_KPR_01:GA-08":[["[Emergent] Objectivity is redefined as necessary validity for possible experience under subjective but universal conditions of givenness and synthesis.","Objectivity is redefined as necessary validity for possible experience under subjective but universal conditions of givenness and synthesis."]],"CL_KPR_01:GA-09":[["[Mutating] The subject mutates from empirical knower into the formal site of conditions under which objects can appear and be thought.","The subject mutates from empirical knower into the formal site of conditions under which objects can appear and be thought."]],"CL_KPR_01:GA-10":[["[Persistent] Things in themselves are thinkable as limiting correlates but not cognizable through human sensibility or pure understanding.","Things in themselves are thinkable as limiting correlates but not cognizable through human sensibility or pure understanding."]],"CL_KPR_01:GA-11":[["[Attractor] Possible experience is the governing boundary that simultaneously authorizes mathematics, natural-scientific objectivity, and the legitimate use of pure concepts while excluding transcendent speculation.","Possible experience is the governing boundary that simultaneously authorizes mathematics, natural-scientific objectivity, and the legitimate use of pure concepts while excluding transcendent speculation."]],"CL_KPR_01:GA-12":[["[Persistent] Metaphysics is unavoidable as a tendency of reason but illegitimate as dogmatic science unless subjected to critique of the sources, scope, and limits of a priori cognition.","Metaphysics is unavoidable as a tendency of reason but illegitimate as dogmatic science unless subjected to critique of the sources, scope, and limits of a priori cognition."]],"CL_KPR_01:GA-13":[["[Emergent] Critique operates by converting alleged objective determinations into conditions of cognition, then testing their domain of legitimate application.","Critique operates by converting alleged objective determinations into conditions of cognition, then testing their domain of legitimate application."]],"CL_KPR_01:GA-14":[["[Mutating] Logic shifts from formal correctness to transcendental object-relation: it is canon when restricted, dialectic when misused as organon.","Logic shifts from formal correctness to transcendental object-relation: it is canon when restricted, dialectic when misused as organon."]],"CL_KPR_01:GA-15":[["[Terminal] The cluster terminates in the necessity of transcendental deduction: categories must prove their right to apply to objects because their origin alone cannot justify objective validity.","The cluster terminates in the necessity of transcendental deduction: categories must prove their right to apply to objects because their origin alone cannot justify objective validity."]],"CL_KPR_01:CGD-01":[["Local to CH_KPR_INTRODUCTION is the analytic/synthetic taxonomic preparation; at cluster level it survives only as the mechanism that isolates necessary augmentation as the problem requiring intuition and synthesis.","Local to Introduction is the analytic/synthetic taxonomic preparation; at cluster level it survives only as the mechanism that isolates necessary augmentation as the problem requiring intuition and synthesis."]],"CL_KPR_01:CGD-02":[["Local to CH_KPR_ITDE are detailed expositions of space and time; at cluster level they scale upward as the sensuous half of the general account of synthetic a priori validity.","Local to I. TRANSCENDENTAL DOCTRINE OF ELEMENTS. are detailed expositions of space and time; at cluster level they scale upward as the sensuous half of the general account of synthetic a priori validity."]],"CL_KPR_01:CGD-03":[["Local to CH_KPR_TRANSCENDENTAL_LOGIC are the formal tables of judgment and categories; at cluster level they scale upward as the understanding-side answer to how the given manifold can be objectified.","Local to Transcendental Logic are the formal tables of judgment and categories; at cluster level they scale upward as the understanding-side answer to how the given manifold can be objectified."]],"CL_KPR_02:GA-01":[["[Attractor] Objective cognition requires the conjunction of intuition and concept; neither sensuous givenness nor pure thought alone constitutes an object for finite cognition.","Objective cognition requires the conjunction of intuition and concept; neither sensuous givenness nor pure thought alone constitutes an object for finite cognition."]],"CL_KPR_02:GA-02":[["[Persistent] The categories are pure functions of object-unification, not empirical abstractions, images, innate harmonies, or ontological predicates of things in themselves.","The categories are pure functions of object-unification, not empirical abstractions, images, innate harmonies, or ontological predicates of things in themselves."]],"CL_KPR_02:GA-03":[["[Persistent] Objectivity consists in necessary synthetic unity under apperception rather than in associative conjunction, logical consistency, or correspondence to things as they are in themselves.","Objectivity consists in necessary synthetic unity under apperception rather than in associative conjunction, logical consistency, or correspondence to things as they are in themselves."]],"CL_KPR_02:GA-04":[["[Mutating] The understanding first appears as faculty of synthesis, then as faculty of rules requiring judgment, and finally as a finite faculty whose empirical use must be distinguished from its void transcendental use.","The understanding first appears as faculty of synthesis, then as faculty of rules requiring judgment, and finally as a finite faculty whose empirical use must be distinguished from its void transcendental use."]],"CL_KPR_02:GA-05":[["[Emergent] Application is not secured by the category alone: between pure concept and sensible object a mediating temporal condition is required.","Application is not secured by the category alone: between pure concept and sensible object a mediating temporal condition is required."]],"CL_KPR_02:GA-06":[["[Persistent] Possible experience is the validating medium for synthetic a priori cognition and the boundary beyond which pure concepts lose objective reality.","Possible experience is the validating medium for synthetic a priori cognition and the boundary beyond which pure concepts lose objective reality."]],"CL_KPR_02:GA-07":[["[Mutating] Sensibility is not a passive defect but a positive transcendental condition: it supplies the forms and field through which objects can be given and categories can acquire sense.","Sensibility is not a passive defect but a positive transcendental condition: it supplies the forms and field through which objects can be given and categories can acquire sense."]],"CL_KPR_02:GA-08":[["[Emergent] Time becomes the universal mediation-field in which categories are schematized and through which pure understanding becomes applicable to appearances.","Time becomes the universal mediation-field in which categories are schematized and through which pure understanding becomes applicable to appearances."]],"CL_KPR_02:GA-09":[["[Terminal] The categories legislate for nature only as formal law-governed appearance, never for things in themselves.","The categories legislate for nature only as formal law-governed appearance, never for things in themselves."]],"CL_KPR_02:GA-10":[["[Attractor] The thing in itself is structurally necessary as limit, ground, or correlate of appearance, but inadmissible as a determinate object of theoretical cognition.","The thing in itself is structurally necessary as limit, ground, or correlate of appearance, but inadmissible as a determinate object of theoretical cognition."]],"CL_KPR_02:GA-11":[["[Persistent] Human cognition is finite: it thinks but does not intuit intellectually, receives objects through sensibility, and can determine only what can be given under sensible conditions.","Human cognition is finite: it thinks but does not intuit intellectually, receives objects through sensibility, and can determine only what can be given under sensible conditions."]],"CL_KPR_02:GA-12":[["[Emergent] Critical method converts metaphysics from synthetic doctrine of being in general into an analytic, schematization, and boundary-diagnosis of possible experience.","Critical method converts metaphysics from synthetic doctrine of being in general into an analytic, schematization, and boundary-diagnosis of possible experience."]],"CL_KPR_02:RMD-01":[["The category recurs with altered function: in CH_KPR_CATAGORIES it is deduced as condition of object-unity; in CH_KPR_BOOK_TWO it is temporalized through schema; in CH_KPR_PHENOMENA_NOUMENA it is voided beyond sensibility.","The category recurs with altered function: in Catagories it is deduced as condition of object-unity; in Book Two it is temporalized through schema; in Phenomena Noumena it is voided beyond sensibility."]],"CL_KPR_02:XD-01":[["Because CH_KPR_CATAGORIES grounds objectivity in apperceptive synthesis and CH_KPR_BOOK_TWO requires schematized application, objective validity is incomplete without both unity-ground and temporal mediation.","Because Catagories grounds objectivity in apperceptive synthesis and Book Two requires schematized application, objective validity is incomplete without both unity-ground and temporal mediation."]],"CL_KPR_02:XD-02":[["Because CH_KPR_BOOK_TWO makes schematism the condition of category-application and CH_KPR_PHENOMENA_NOUMENA voids categories without sensibility, the schema is not an optional bridge but the decisive boundary between cognition and empty thought.","Because Book Two makes schematism the condition of category-application and Phenomena Noumena voids categories without sensibility, the schema is not an optional bridge but the decisive boundary between cognition and empty thought."]],"CL_KPR_02:XD-03":[["Because CH_KPR_CATAGORIES validates categories only for possible experience and CH_KPR_PHENOMENA_NOUMENA converts noumenon into limit-concept, validation and anti-dogmatic limitation are one operation, not two results.","Because Catagories validates categories only for possible experience and Phenomena Noumena converts noumenon into limit-concept, validation and anti-dogmatic limitation are one operation, not two results."]],"CL_KPR_02:XD-04":[["Because CH_KPR_BOOK_TWO denies that general logic can govern application and CH_KPR_PHENOMENA_NOUMENA denies that logical comparison yields ontology, formal logic is globally demoted from ground of cognition to negative-control instrument.","Because Book Two denies that general logic can govern application and Phenomena Noumena denies that logical comparison yields ontology, formal logic is globally demoted from ground of cognition to negative-control instrument."]],"CL_KPR_02:XD-05":[["Because CH_KPR_CATAGORIES distinguishes self-consciousness from self-knowledge and CH_KPR_PHENOMENA_NOUMENA distinguishes thinking from cognizing noumenon, the cluster generalizes a rule: formal reference does not equal determinate cognition.","Because Catagories distinguishes self-consciousness from self-knowledge and Phenomena Noumena distinguishes thinking from cognizing noumenon, the cluster generalizes a rule: formal reference does not equal determinate cognition."]],"CL_KPR_02:XD-06":[["Because CH_KPR_BOOK_TWO temporalizes the categories and CH_KPR_PHENOMENA_NOUMENA restricts causality, substance, and modality to schematized sensibility, transcendental principles are universal only as time-bound principles of appearances.","Because Book Two temporalizes the categories and Phenomena Noumena restricts causality, substance, and modality to schematized sensibility, transcendental principles are universal only as time-bound principles of appearances."]],"CL_KPR_02:XD-07":[["Because CH_KPR_CATAGORIES makes nature law-governed through synthesis and CH_KPR_BOOK_TWO derives principles from schematized categories, nature is reconstructed as the rule-field of possible experience rather than as a directly copied independent order.","Because Catagories makes nature law-governed through synthesis and Book Two derives principles from schematized categories, nature is reconstructed as the rule-field of possible experience rather than as a directly copied independent order."]],"CL_KPR_02:XD-08":[["Because CH_KPR_PHENOMENA_NOUMENA requires a non-cognitive reference to things in themselves while CH_KPR_CATAGORIES and CH_KPR_BOOK_TWO deny category-use beyond experience, the cluster contains a productive tension between necessary limiting reference and forbidden determination.","Because Phenomena Noumena requires a non-cognitive reference to things in themselves while Catagories and Book Two deny category-use beyond experience, the cluster contains a productive tension between necessary limiting reference and forbidden determination."]],"CL_KPR_03:GA-01":[["[Persistent] Objective cognition is not received from perception but generated through rule-governed synthesis under conditions of possible experience.","Objective cognition is not received from perception but generated through rule-governed synthesis under conditions of possible experience."]],"CL_KPR_03:GA-02":[["[Persistent] Necessity is legitimate only where it functions as a condition of possible experience or as a regulative demand of reason, never as direct access to things in themselves.","Necessity is legitimate only where it functions as a condition of possible experience or as a regulative demand of reason, never as direct access to things in themselves."]],"CL_KPR_03:GA-03":[["[Persistent] Categories and pure principles possess objective validity only through their relation to intuition, synthesis, and possible experience.","Categories and pure principles possess objective validity only through their relation to intuition, synthesis, and possible experience."]],"CL_KPR_03:GA-04":[["[Mutating] Time is never directly given as an object; it must be determined through phenomenal relations, external permanence, and eventually through reason’s ascent beyond conditioned temporal series.","Time is never directly given as an object; it must be determined through phenomenal relations, external permanence, and eventually through reason’s ascent beyond conditioned temporal series."]],"CL_KPR_03:GA-05":[["[Persistent] Phenomenal nature is the lawful unity of appearances under rules of permanence, causality, community, continuity, and empirical connection.","Phenomenal nature is the lawful unity of appearances under rules of permanence, causality, community, continuity, and empirical connection."]],"CL_KPR_03:GA-06":[["[Mutating] The boundary of cognition shifts from temporal object-determination, to modal experiential restriction, to critique of reason’s transcendent illusion.","The boundary of cognition shifts from temporal object-determination, to modal experiential restriction, to critique of reason’s transcendent illusion."]],"CL_KPR_03:GA-07":[["[Emergent] The system preserves metaphysical concepts by converting their status: substance, causality, necessity, totality, soul, world, and God are not abolished but reassigned to restricted functions.","The system preserves metaphysical concepts by converting their status: substance, causality, necessity, totality, soul, world, and God are not abolished but reassigned to restricted functions."]],"CL_KPR_03:GA-08":[["[Attractor] The unconditioned is the absent attractor of the cluster: excluded as object of possible experience, yet required by reason’s drive toward systematic completion.","The unconditioned is the absent attractor of the cluster: excluded as object of possible experience, yet required by reason’s drive toward systematic completion."]],"CL_KPR_03:GA-09":[["[Persistent] Empirical reality requires sensation or lawful connection with sensation, but sensation alone never supplies objective order, necessity, or totality.","Empirical reality requires sensation or lawful connection with sensation, but sensation alone never supplies objective order, necessity, or totality."]],"CL_KPR_03:GA-10":[["[Mutating] The subject is progressively displaced from self-grounding source to formal unity, externally conditioned temporal consciousness, and finally problematic idea of reason.","The subject is progressively displaced from self-grounding source to formal unity, externally conditioned temporal consciousness, and finally problematic idea of reason."]],"CL_KPR_03:GA-11":[["[Emergent] Critique is the permanent discipline that assigns each faculty its lawful use and exposes the illusion produced when one faculty’s demand is mistaken for another’s object.","Critique is the permanent discipline that assigns each faculty its lawful use and exposes the illusion produced when one faculty’s demand is mistaken for another’s object."]],"CL_KPR_03:GA-12":[["[Terminal] All pure principles of understanding terminate in possible experience; anything beyond that termination can guide systematic unity but cannot constitute object-cognition.","All pure principles of understanding terminate in possible experience; anything beyond that termination can guide systematic unity but cannot constitute object-cognition."]],"CL_KPR_04:GA-01":[["[Persistent] Speculative cognition is objectively valid only where a concept can be related to intuition within possible experience.","Speculative cognition is objectively valid only where a concept can be related to intuition within possible experience."]],"CL_KPR_04:GA-02":[["[Persistent] Reason necessarily seeks the unconditioned for the conditioned, but this necessity of search does not itself supply an object.","Reason necessarily seeks the unconditioned for the conditioned, but this necessity of search does not itself supply an object."]],"CL_KPR_04:GA-03":[["[Mutating] The unconditioned mutates by domain: in rational psychology it becomes the self as absolute subject; in cosmology it becomes the totality of conditions for phenomena.","The unconditioned mutates by domain: in rational psychology it becomes the self as absolute subject; in cosmology it becomes the totality of conditions for phenomena."]],"CL_KPR_04:GA-04":[["[Persistent] Categories have objective validity only under the conditions of possible experience and become dialectical when applied beyond possible intuition.","Categories have objective validity only under the conditions of possible experience and become dialectical when applied beyond possible intuition."]],"CL_KPR_04:GA-05":[["[Persistent] Dialectical illusion is natural and unavoidable; critique can diagnose and restrain it but cannot abolish reason’s tendency to produce it.","Dialectical illusion is natural and unavoidable; critique can diagnose and restrain it but cannot abolish reason’s tendency to produce it."]],"CL_KPR_04:GA-06":[["[Mutating] Formal necessity becomes error when transferred into object-cognition: logical subjecthood becomes soul-substance, and regressive synthesis becomes world-totality.","Formal necessity becomes error when transferred into object-cognition: logical subjecthood becomes soul-substance, and regressive synthesis becomes world-totality."]],"CL_KPR_04:GA-07":[["[Emergent] Contradiction is a transcendental diagnostic when opposed claims arise from the same rational demand under illegitimate constitutive employment.","Contradiction is a transcendental diagnostic when opposed claims arise from the same rational demand under illegitimate constitutive employment."]],"CL_KPR_04:GA-08":[["[Persistent] Dogmatic affirmation and dogmatic negation of supersensible or trans-experiential objects are equally illegitimate.","Dogmatic affirmation and dogmatic negation of supersensible or trans-experiential objects are equally illegitimate."]],"CL_KPR_04:GA-09":[["[Attractor] Possible experience is the tribunal for speculative cognition, but not the measure of all rational interest.","Possible experience is the tribunal for speculative cognition, but not the measure of all rational interest."]],"CL_KPR_04:GA-10":[["[Emergent] The world-whole is not an empirical object hidden beyond inquiry but the idea-generated totality of possible empirical synthesis.","The world-whole is not an empirical object hidden beyond inquiry but the idea-generated totality of possible empirical synthesis."]],"CL_KPR_04:GA-11":[["[Terminal] Transcendental idealism is required to dissolve cosmological contradiction by denying that appearances constitute a completed thing in itself while preserving empirical reality.","Transcendental idealism is required to dissolve cosmological contradiction by denying that appearances constitute a completed thing in itself while preserving empirical reality."]],"CL_KPR_04:GA-12":[["[Attractor] The system preserves practical supersensible orientation precisely by refusing speculative proof of supersensible objects.","The system preserves practical supersensible orientation precisely by refusing speculative proof of supersensible objects."]],"CL_KPR_05:GA-01":[["[Persistent] Reason necessarily seeks the unconditioned completion of conditioned cognition, whether as complete regress, complete determination, or ultimate ground.","Reason necessarily seeks the unconditioned completion of conditioned cognition, whether as complete regress, complete determination, or ultimate ground."]],"CL_KPR_05:GA-02":[["[Persistent] A rational demand for completion does not entail that a completed object is given, cognizable, or existent.","A rational demand for completion does not entail that a completed object is given, cognizable, or existent."]],"CL_KPR_05:GA-03":[["[Persistent] Cognition of objects is restricted to possible experience, sensuous intuition, and empirical synthesis; pure reason alone cannot generate object-knowledge.","Cognition of objects is restricted to possible experience, sensuous intuition, and empirical synthesis; pure reason alone cannot generate object-knowledge."]],"CL_KPR_05:GA-04":[["[Mutating] Totality mutates from empirical series-totality, to predicate-totality, to theological ground-totality, while retaining the same illegitimate tendency toward objectification.","Totality mutates from empirical series-totality, to predicate-totality, to theological ground-totality, while retaining the same illegitimate tendency toward objectification."]],"CL_KPR_05:GA-05":[["[Persistent] Reason’s ideas are legitimate as regulative principles for extending, ordering, and unifying inquiry, but illegitimate as constitutive determinations of supersensible objects.","Reason’s ideas are legitimate as regulative principles for extending, ordering, and unifying inquiry, but illegitimate as constitutive determinations of supersensible objects."]],"CL_KPR_05:GA-06":[["[Emergent] Transcendental illusion is the structural conversion of conditions of inquiry or thought into supposed conditions of things in themselves.","Transcendental illusion is the structural conversion of conditions of inquiry or thought into supposed conditions of things in themselves."]],"CL_KPR_05:GA-07":[["[Persistent] The unconditioned cannot be encountered as an empirical member of the conditioned series.","The unconditioned cannot be encountered as an empirical member of the conditioned series."]],"CL_KPR_05:GA-08":[["[Mutating] The intelligible is thinkable as a limiting or grounding register only by remaining unavailable to theoretical cognition and empirical determination.","The intelligible is thinkable as a limiting or grounding register only by remaining unavailable to theoretical cognition and empirical determination."]],"CL_KPR_05:GA-09":[["[Persistent] Existence cannot be analytically derived from a concept, including the concept of the most real or absolutely necessary being.","Existence cannot be analytically derived from a concept, including the concept of the most real or absolutely necessary being."]],"CL_KPR_05:GA-10":[["[Emergent] Speculative theology is the terminal form of transcendental illusion because it attempts to turn rational completeness into objective divine existence.","Speculative theology is the terminal form of transcendental illusion because it attempts to turn rational completeness into objective divine existence."]],"CL_KPR_05:GA-11":[["[Persistent] Critical reason limits both dogmatic metaphysical assertion and dogmatic empirical denial of the supersensible.","Critical reason limits both dogmatic metaphysical assertion and dogmatic empirical denial of the supersensible."]],"CL_KPR_05:GA-12":[["[Mutating] The necessary being shifts from possible intelligible ground, to hypostatized ideal of total reality, to regulative theological idea stripped of speculative proof.","The necessary being shifts from possible intelligible ground, to hypostatized ideal of total reality, to regulative theological idea stripped of speculative proof."]],"CL_KPR_05:GA-13":[["[Attractor] The appearance/thing-in-itself distinction is the cluster’s silent stabilizer: without it, antinomy, ideal, and theology collapse into either dogmatism or scepticism.","The appearance/thing-in-itself distinction is the cluster’s silent stabilizer: without it, antinomy, ideal, and theology collapse into either dogmatism or scepticism."]],"CL_KPR_05:GA-14":[["[Terminal] All speculative proof-routes to God fail because they either exceed possible experience or require the impossible ontological transition from concept to existence.","All speculative proof-routes to God fail because they either exceed possible experience or require the impossible ontological transition from concept to existence."]],"CL_KPR_05:GA-15":[["[Emergent] Critical limitation preserves rational orientation by denying possession: reason may pursue, regulate, purify, and think what it may not cognize.","Critical limitation preserves rational orientation by denying possession: reason may pursue, regulate, purify, and think what it may not cognize."]],"CL_KPR_06:GA-01":[["[Persistent] Pure reason naturally tends to exceed possible experience; this excess is structural, not accidental.","Pure reason naturally tends to exceed possible experience; this excess is structural, not accidental."]],"CL_KPR_06:GA-02":[["[Persistent] Objective speculative cognition is legitimate only in relation to the conditions of possible experience.","Objective speculative cognition is legitimate only in relation to the conditions of possible experience."]],"CL_KPR_06:GA-03":[["[Mutating] Reason’s proper authority shifts from constituting objects to regulating, disciplining, and adjudicating the use of cognition.","Reason’s proper authority shifts from constituting objects to regulating, disciplining, and adjudicating the use of cognition."]],"CL_KPR_06:GA-04":[["[Persistent] Transcendental ideas are legitimate only when used regulatively, never as constitutive cognitions of supersensible objects.","Transcendental ideas are legitimate only when used regulatively, never as constitutive cognitions of supersensible objects."]],"CL_KPR_06:GA-05":[["[Emergent] Critique is the higher form of reason’s self-legislation: it preserves reason by restricting its speculative jurisdiction.","Critique is the higher form of reason’s self-legislation: it preserves reason by restricting its speculative jurisdiction."]],"CL_KPR_06:GA-06":[["[Persistent] Philosophy cannot imitate mathematics because philosophy proceeds through concepts and rules of possible experience, while mathematics constructs concepts in pure intuition.","Philosophy cannot imitate mathematics because philosophy proceeds through concepts and rules of possible experience, while mathematics constructs concepts in pure intuition."]],"CL_KPR_06:GA-07":[["[Mutating] Systematic unity is required by reason but cannot be possessed as a completed object.","Systematic unity is required by reason but cannot be possessed as a completed object."]],"CL_KPR_06:GA-08":[["[Emergent] Negative cognition is productive when it prevents transcendental misemployment and thereby secures lawful empirical inquiry.","Negative cognition is productive when it prevents transcendental misemployment and thereby secures lawful empirical inquiry."]],"CL_KPR_06:GA-09":[["[Persistent] Dogmatism and negative dogmatism are equally illegitimate where they assert either the existence or impossibility of supersensible objects as speculative knowledge.","Dogmatism and negative dogmatism are equally illegitimate where they assert either the existence or impossibility of supersensible objects as speculative knowledge."]],"CL_KPR_06:GA-10":[["[Emergent] Scepticism has disciplinary force only as a transition toward critique, not as a final determination of reason’s limits.","Scepticism has disciplinary force only as a transition toward critique, not as a final determination of reason’s limits."]],"CL_KPR_06:GA-11":[["[Attractor] The unavailable totality—systematic unity, world-whole, God, soul, complete metaphysics—organizes reason as a horizon while remaining forbidden as cognition.","The unavailable totality—systematic unity, world-whole, God, soul, complete metaphysics—organizes reason as a horizon while remaining forbidden as cognition."]],"CL_KPR_06:GA-12":[["[Terminal] Speculative reason’s highest achievement is not transcendent knowledge but disciplined self-knowledge of its limits, methods, and lawful regulative uses.","Speculative reason’s highest achievement is not transcendent knowledge but disciplined self-knowledge of its limits, methods, and lawful regulative uses."]],"CL_KPR_06:CGD-01":[["Local to CH_KPR_APPENDIX: the detailed triad of homogeneity, specification, and affinity remains a specific machinery of regulative natural inquiry; at cluster scale it serves the broader axiom that reason requires non-constitutive systematic unity.","Local to Appendix: the detailed triad of homogeneity, specification, and affinity remains a specific machinery of regulative natural inquiry; at cluster scale it serves the broader axiom that reason requires non-constitutive systematic unity."]],"CL_KPR_06:CGD-02":[["Local to CH_KPR_ITDM: the technical denial of definitions, axioms, and demonstrations in philosophy remains a method-specific filter; at cluster scale it supports the exclusion of mathematical dogmatism as a model for metaphysics.","Local to II. Transcendental Doctrine of Method: the technical denial of definitions, axioms, and demonstrations in philosophy remains a method-specific filter; at cluster scale it supports the exclusion of mathematical dogmatism as a model for metaphysics."]],"CL_KPR_06:CGD-03":[["Local to CH_KPR_DISCIPLINE: the rules for polemic and defensive hypotheses remain dispute-specific; at cluster scale they become one mode of reason’s general self-discipline.","Local to Discipline: the rules for polemic and defensive hypotheses remain dispute-specific; at cluster scale they become one mode of reason’s general self-discipline."]],"CL_KPR_07:GA-01":[["[Persistent] Pure reason is legitimate only when its claims are tested by the source, domain, limit, and use of the principles from which they arise.","Pure reason is legitimate only when its claims are tested by the source, domain, limit, and use of the principles from which they arise."]],"CL_KPR_07:GA-02":[["[Persistent] Speculative reason has no constitutive authority beyond possible experience, but this restriction does not annul reason’s authority as such.","Speculative reason has no constitutive authority beyond possible experience, but this restriction does not annul reason’s authority as such."]],"CL_KPR_07:GA-03":[["[Mutating] The failure of dogmatic metaphysics mutates from evidence against metaphysics into evidence for critique as metaphysics’ necessary internal discipline.","The failure of dogmatic metaphysics mutates from evidence against metaphysics into evidence for critique as metaphysics’ necessary internal discipline."]],"CL_KPR_07:GA-04":[["[Persistent] Legitimate cognition requires systematic unity under an a priori rule; unsystematic accumulation has no scientific or transcendental authority.","Legitimate cognition requires systematic unity under an a priori rule; unsystematic accumulation has no scientific or transcendental authority."]],"CL_KPR_07:GA-05":[["[Emergent] The discipline of proof and the architectonic of science are two forms of the same operation: reason legislates by excluding illegitimate transitions and assigning each cognition its rightful place.","The discipline of proof and the architectonic of science are two forms of the same operation: reason legislates by excluding illegitimate transitions and assigning each cognition its rightful place."]],"CL_KPR_07:GA-06":[["[Attractor] The ultimate ends of reason organize the whole system, converting theoretical limitation into practical and teleological orientation.","The ultimate ends of reason organize the whole system, converting theoretical limitation into practical and teleological orientation."]],"CL_KPR_07:GA-07":[["[Persistent] Moral law supplies the only positive canon of pure reason because speculative cognition cannot generate synthetic knowledge of supersensible objects.","Moral law supplies the only positive canon of pure reason because speculative cognition cannot generate synthetic knowledge of supersensible objects."]],"CL_KPR_07:GA-08":[["[Mutating] God, freedom, and future life shift from failed speculative objects into practical postulates and architectonic terminals of reason’s highest interest.","God, freedom, and future life shift from failed speculative objects into practical postulates and architectonic terminals of reason’s highest interest."]],"CL_KPR_07:GA-09":[["[Emergent] Metaphysics is rehabilitated only by being demoted: it ceases to extend knowledge and becomes censor, organizer, propedeutic, and systematic completion of reason.","Metaphysics is rehabilitated only by being demoted: it ceases to extend knowledge and becomes censor, organizer, propedeutic, and systematic completion of reason."]],"CL_KPR_07:GA-10":[["[Persistent] Philosophy is not possession of doctrine but autonomous rational production under an absent regulative archetype.","Philosophy is not possession of doctrine but autonomous rational production under an absent regulative archetype."]],"CL_KPR_07:GA-11":[["[Terminal] Rational belief occupies the terminal epistemic position required when practical necessity is unconditional but speculative proof is impossible.","Rational belief occupies the terminal epistemic position required when practical necessity is unconditional but speculative proof is impossible."]],"CL_KPR_07:GA-12":[["[Attractor] Reason’s unity is moral-teleological before it is doctrinal: all cognition is ultimately ranked by relation to humanity’s destination and the highest good.","Reason’s unity is moral-teleological before it is doctrinal: all cognition is ultimately ranked by relation to humanity’s destination and the highest good."]],"CL_KPR_07:GA-13":[["[Emergent] Critical reason preserves common moral orientation by denying speculative elites privileged access to humanity’s ultimate ends.","Critical reason preserves common moral orientation by denying speculative elites privileged access to humanity’s ultimate ends."]],"CL_KPR_07:GA-14":[["[Mutating] The supersensible persists by functional displacement: unknowable as object, indispensable as regulative horizon, practical postulate, and architectonic end.","The supersensible persists by functional displacement: unknowable as object, indispensable as regulative horizon, practical postulate, and architectonic end."]],"MC_KPR_L1_01:GA-01":[["[Persistent] Human cognition begins through sensuous affection, but necessity, strict universality, and objective validity cannot be derived from empirical occurrence.","Human cognition begins through sensuous affection, but necessity, strict universality, and objective validity cannot be derived from empirical occurrence."]],"MC_KPR_L1_01:GA-02":[["[Persistent] Finite cognition requires the irreducible conjunction of intuition and concept; no object is cognized through sensibility alone, understanding alone, or reason alone.","Finite cognition requires the irreducible conjunction of intuition and concept; no object is cognized through sensibility alone, understanding alone, or reason alone."]],"MC_KPR_L1_01:GA-03":[["[Mutating] The a priori mutates from diagnostic non-empirical validity into pure forms of givenness, pure functions of unity, schematized temporal rules, and finally critical boundaries of use.","The a priori mutates from diagnostic non-empirical validity into pure forms of givenness, pure functions of unity, schematized temporal rules, and finally critical boundaries of use."]],"MC_KPR_L1_01:GA-04":[["[Persistent] Objectivity consists in necessary synthetic unity valid for possible experience, not correspondence to things as they are in themselves.","Objectivity consists in necessary synthetic unity valid for possible experience, not correspondence to things as they are in themselves."]],"MC_KPR_L1_01:GA-05":[["[Attractor] Possible experience is the validating medium and limiting tribunal of all speculative object-cognition.","Possible experience is the validating medium and limiting tribunal of all speculative object-cognition."]],"MC_KPR_L1_01:GA-06":[["[Persistent] Space and time are pure forms of finite sensibility: empirically real for appearances, transcendentally ideal with respect to things in themselves.","Space and time are pure forms of finite sensibility: empirically real for appearances, transcendentally ideal with respect to things in themselves."]],"MC_KPR_L1_01:GA-07":[["[Emergent] Time becomes the universal finite mediation-field: it grounds inner and outer determination, schematizes categories, structures natural necessity, and prevents completed empirical totality from becoming an object.","Time becomes the universal finite mediation-field: it grounds inner and outer determination, schematizes categories, structures natural necessity, and prevents completed empirical totality from becoming an object."]],"MC_KPR_L1_01:GA-08":[["[Persistent] Categories are pure functions of object-unification whose objective validity depends on synthesis, apperception, schematization, intuition, and possible experience.","Categories are pure functions of object-unification whose objective validity depends on synthesis, apperception, schematization, intuition, and possible experience."]],"MC_KPR_L1_01:GA-09":[["[Mutating] The subject mutates from empirical knower into formal condition-site, apperceptive unity, externally conditioned temporal consciousness, and finally problematic rational idea.","The subject mutates from empirical knower into formal condition-site, apperceptive unity, externally conditioned temporal consciousness, and finally problematic rational idea."]],"MC_KPR_L1_01:GA-10":[["[Persistent] Things in themselves and noumena are structurally necessary limit-correlates but never determinate objects of theoretical cognition.","Things in themselves and noumena are structurally necessary limit-correlates but never determinate objects of theoretical cognition."]],"MC_KPR_L1_01:GA-11":[["[Mutating] Limitation mutates from negative restraint into the positive condition of legitimate science, empirical realism, metaphysical critique, and practical protection.","Limitation mutates from negative restraint into the positive condition of legitimate science, empirical realism, metaphysical critique, and practical protection."]],"MC_KPR_L1_01:GA-12":[["[Emergent] Metaphysics is not abolished but redistributed: as analytic of conditions, critique of faculty-use, boundary-diagnosis, and regulative orientation.","Metaphysics is not abolished but redistributed: as analytic of conditions, critique of faculty-use, boundary-diagnosis, and regulative orientation."]],"MC_KPR_L1_01:GA-13":[["[Attractor] The unconditioned is reason’s necessary absent object: it generates systematicity, ideas, paralogism, antinomy, and practical orientation without supplying speculative cognition.","The unconditioned is reason’s necessary absent object: it generates systematicity, ideas, paralogism, antinomy, and practical orientation without supplying speculative cognition."]],"MC_KPR_L1_01:GA-14":[["[Emergent] Transcendental illusion is lawful, unavoidable, and internally generated by reason’s legitimate demand when transferred from regulative use into constitutive object-claim.","Transcendental illusion is lawful, unavoidable, and internally generated by reason’s legitimate demand when transferred from regulative use into constitutive object-claim."]],"MC_KPR_L1_01:GA-15":[["[Terminal] Transcendental idealism is required as the only architecture that secures empirical reality while denying that appearances, self, world, or noumenon are things in themselves available to speculative cognition.","Transcendental idealism is required as the only architecture that secures empirical reality while denying that appearances, self, world, or noumenon are things in themselves available to speculative cognition."]],"MC_KPR_L1_02:GA-01":[["[Persistent] Pure reason necessarily seeks unconditioned completion, systematic unity, and ultimate ends beyond any given empirical cognition.","Pure reason necessarily seeks unconditioned completion, systematic unity, and ultimate ends beyond any given empirical cognition."]],"MC_KPR_L1_02:GA-02":[["[Persistent] Theoretical object-cognition is legitimate only within possible experience; pure reason alone cannot constitute supersensible objects.","Theoretical object-cognition is legitimate only within possible experience; pure reason alone cannot constitute supersensible objects."]],"MC_KPR_L1_02:GA-03":[["[Mutating] Totality mutates from forbidden object of cognition into regulative horizon, disciplinary problem, and architectonic idea of systematic completion.","Totality mutates from forbidden object of cognition into regulative horizon, disciplinary problem, and architectonic idea of systematic completion."]],"MC_KPR_L1_02:GA-04":[["[Emergent] Critique is reason’s self-preserving transformation of its own failure: dialectical collapse becomes the condition for lawful use, not the abolition of reason.","Critique is reason’s self-preserving transformation of its own failure: dialectical collapse becomes the condition for lawful use, not the abolition of reason."]],"MC_KPR_L1_02:GA-05":[["[Persistent] Regulative ideas are necessary for inquiry and orientation but illegitimate when treated as constitutive determinations of objects.","Regulative ideas are necessary for inquiry and orientation but illegitimate when treated as constitutive determinations of objects."]],"MC_KPR_L1_02:GA-06":[["[Emergent] Negative legislation is productive: excluding speculative possession generates disciplined method, regulative inquiry, practical reserve, and architectonic order.","Negative legislation is productive: excluding speculative possession generates disciplined method, regulative inquiry, practical reserve, and architectonic order."]],"MC_KPR_L1_02:GA-07":[["[Attractor] The supersensible is the meta-cluster’s organizing absent object: unknowable theoretically, indispensable regulatively, defensible polemically, necessary practically, and terminal architectonically.","The supersensible is the meta-cluster’s organizing absent object: unknowable theoretically, indispensable regulatively, defensible polemically, necessary practically, and terminal architectonically."]],"MC_KPR_L1_02:GA-08":[["[Persistent] Dogmatism and scepticism are symmetrical failures when they either claim possession of the supersensible or infer its nullity from noncognition.","Dogmatism and scepticism are symmetrical failures when they either claim possession of the supersensible or infer its nullity from noncognition."]],"MC_KPR_L1_02:GA-09":[["[Mutating] Metaphysics survives only by abandoning supersensible object-science and becoming critique, discipline, censorial office, regulative system, and practical-architectonic orientation.","Metaphysics survives only by abandoning supersensible object-science and becoming critique, discipline, censorial office, regulative system, and practical-architectonic orientation."]],"MC_KPR_L1_02:GA-10":[["[Terminal] Speculative theology fails as proof but reappears under moral law as practical postulation and architectonic consequence, never as foundation.","Speculative theology fails as proof but reappears under moral law as practical postulation and architectonic consequence, never as foundation."]],"MC_KPR_L1_02:GA-11":[["[Emergent] Reason’s authority is jurisdictional: legitimacy depends on assigning each claim to the proper faculty, domain, method, use, and end.","Reason’s authority is jurisdictional: legitimacy depends on assigning each claim to the proper faculty, domain, method, use, and end."]],"MC_KPR_L1_02:GA-12":[["[Attractor] Completion remains necessary only as unavailable possession; reason requires wholeness as guide, not as achieved object or doctrine.","Completion remains necessary only as unavailable possession; reason requires wholeness as guide, not as achieved object or doctrine."]],"MC_KPR_L1_02:GA-13":[["[Mutating] The subject becomes finite knower, producer of illusion, self-legislating tribunal, and practical agent oriented by what it cannot know.","The subject becomes finite knower, producer of illusion, self-legislating tribunal, and practical agent oriented by what it cannot know."]],"MC_KPR_L1_02:GA-14":[["[Terminal] Moral reason supplies the final positive use of pure reason where speculative cognition fails: rational belief occupies the endpoint between knowledge and inadmissible opinion.","Moral reason supplies the final positive use of pure reason where speculative cognition fails: rational belief occupies the endpoint between knowledge and inadmissible opinion."]],"WB_KPR:GA-01":[["[Persistent] Human cognition is finite: it begins with sensible affection, requires discursive synthesis, and lacks intellectual intuition.","Human cognition is finite: it begins with sensible affection, requires discursive synthesis, and lacks intellectual intuition."]],"WB_KPR:GA-02":[["[Persistent] Necessary and universal cognition cannot be derived from empirical occurrence; it requires a priori conditions.","Necessary and universal cognition cannot be derived from empirical occurrence; it requires a priori conditions."]],"WB_KPR:GA-03":[["[Mutating] The a priori is not a single possession but a functional sequence: criterion, form, category, schema, principle, restriction, discipline, and architectonic order.","The a priori is not a single possession but a functional sequence: criterion, form, category, schema, principle, restriction, discipline, and architectonic order."]],"WB_KPR:GA-04":[["[Persistent] Cognition of objects requires the conjunction of intuition and concept; neither sensibility, understanding, nor reason alone can produce theoretical object-cognition.","Cognition of objects requires the conjunction of intuition and concept; neither sensibility, understanding, nor reason alone can produce theoretical object-cognition."]],"WB_KPR:GA-05":[["[Attractor] Possible experience is the sole validating field for theoretical object-cognition and the tribunal for speculative claims.","Possible experience is the sole validating field for theoretical object-cognition and the tribunal for speculative claims."]],"WB_KPR:GA-06":[["[Persistent] Objectivity means necessary validity for appearances under finite conditions, not cognition of things as they are in themselves.","Objectivity means necessary validity for appearances under finite conditions, not cognition of things as they are in themselves."]],"WB_KPR:GA-07":[["[Persistent] Space and time are pure forms of finite sensibility: empirically real for appearances and transcendentally ideal with respect to things in themselves.","Space and time are pure forms of finite sensibility: empirically real for appearances and transcendentally ideal with respect to things in themselves."]],"WB_KPR:GA-08":[["[Emergent] Time is the universal mediation-field of finite cognition: it structures intuition, schematizes categories, orders experience, limits self-knowledge, and prevents totality from becoming an empirical object.","Time is the universal mediation-field of finite cognition: it structures intuition, schematizes categories, orders experience, limits self-knowledge, and prevents totality from becoming an empirical object."]],"WB_KPR:GA-09":[["[Persistent] Categories possess objective validity only when synthesized, schematized, and applied within possible experience.","Categories possess objective validity only when synthesized, schematized, and applied within possible experience."]],"WB_KPR:GA-10":[["[Persistent] Things in themselves and noumena are necessary limit-correlates, not determinable objects of theoretical cognition.","Things in themselves and noumena are necessary limit-correlates, not determinable objects of theoretical cognition."]],"WB_KPR:GA-11":[["[Attractor] Reason necessarily seeks the unconditioned, completion, systematic unity, and ultimate ends beyond any given empirical cognition.","Reason necessarily seeks the unconditioned, completion, systematic unity, and ultimate ends beyond any given empirical cognition."]],"WB_KPR:GA-12":[["[Mutating] The unconditioned mutates from illicit speculative object into regulative horizon, practical postulate, and architectonic end.","The unconditioned mutates from illicit speculative object into regulative horizon, practical postulate, and architectonic end."]],"WB_KPR:GA-13":[["[Emergent] Transcendental illusion is lawful and unavoidable: it arises when reason’s legitimate demand for unity is transferred into constitutive object-claim.","Transcendental illusion is lawful and unavoidable: it arises when reason’s legitimate demand for unity is transferred into constitutive object-claim."]],"WB_KPR:GA-14":[["[Mutating] Limitation becomes productive: it grounds empirical science, blocks dogmatism, defeats scepticism, opens regulative inquiry, and protects practical reason.","Limitation becomes productive: it grounds empirical science, blocks dogmatism, defeats scepticism, opens regulative inquiry, and protects practical reason."]],"WB_KPR:GA-15":[["[Emergent] Metaphysics is transformed from supersensible doctrine into critique of reason’s powers, discipline of its use, and architectonic ordering of its interests.","Metaphysics is transformed from supersensible doctrine into critique of reason’s powers, discipline of its use, and architectonic ordering of its interests."]],"WB_KPR:GA-16":[["[Terminal] Moral reason supplies the final positive non-theoretical use of pure reason: belief is legitimate only where knowledge is barred, opinion is insufficient, and practical necessity governs.","Moral reason supplies the final positive non-theoretical use of pure reason: belief is legitimate only where knowledge is barred, opinion is insufficient, and practical necessity governs."]],"WB_KPR:GA-17":[["[Terminal] Transcendental idealism is the required architecture of the whole: it secures empirical reality, limits theoretical cognition, dissolves dialectic, and permits non-dogmatic orientation toward the supersensible.","Transcendental idealism is the required architecture of the whole: it secures empirical reality, limits theoretical cognition, dissolves dialectic, and permits non-dogmatic orientation toward the supersensible."]],"WB_KPR:XD-01":[["Because MC_KPR_L1_01 secures objectivity only through possible experience and MC_KPR_L1_02 preserves supersensible orientation only through non-possession, the whole book generates a dual settlement: knowledge is bounded, reason is not abolished.","Because Metacluster 1 secures objectivity only through possible experience and Metacluster 2 preserves supersensible orientation only through non-possession, the whole book generates a dual settlement: knowledge is bounded, reason is not abolished."]],"CH_THN_SIOO:D1":[["The perception field is organized by two intersecting distinctions: impression versus idea and simple versus complex. (from Axioms CH_THN_SIOO:A1 + CH_THN_SIOO:A4 + CH_THN_SIOO:A5 + CH_THN_SIOO:A6)","The perception field is organized by two intersecting distinctions: impression versus idea and simple versus complex."]],"CH_THN_SIOO:D2":[["Failure of exact complex correspondence does not defeat exact correspondence at the simple level. (from Axioms CH_THN_SIOO:A6 + CH_THN_SIOO:A7 + CH_THN_SIOO:A8)","Failure of exact complex correspondence does not defeat exact correspondence at the simple level."]],"CH_THN_SIOO:D3":[["Corresponding simple impressions and ideas form dependent rather than accidental pairs. (from Axioms CH_THN_SIOO:A7 + CH_THN_SIOO:A9)","Corresponding simple impressions and ideas form dependent rather than accidental pairs."]],"CH_THN_SIOO:D4":[["Impressions are causes and first ideas are effects. (from Axioms CH_THN_SIOO:A9 + CH_THN_SIOO:A10 + CH_THN_SIOO:A11)","Impressions are causes and first ideas are effects."]],"CH_THN_SIOO:D5":[["Normal acquisition of a simple idea requires operative access to its corresponding impression. (from Axioms CH_THN_SIOO:A12 + CH_THN_SIOO:A13)","Normal acquisition of a simple idea requires operative access to its corresponding impression."]],"CH_THN_SIOO:D6":[["Complex imagination may exceed experienced wholes without exceeding impression-derived simple content. (from Axioms CH_THN_SIOO:A6 + CH_THN_SIOO:A7 + CH_THN_SIOO:A8 + CH_THN_SIOO:A13)","Complex imagination may exceed experienced wholes without exceeding impression-derived simple content."]],"CH_THN_SIOO:D7":[["Ideas may generate further ideas without becoming the ultimate source of their simple content. (from Axioms CH_THN_SIOO:A13 + CH_THN_SIOO:A14)","Ideas may generate further ideas without becoming the ultimate source of their simple content."]],"CH_THN_SIOO:D8":[["The admitted missing-shade case converts the derivation principle logically into an exception-tolerant general maxim. (from Axioms CH_THN_SIOO:A13 + CH_THN_SIOO:A15 + CH_THN_SIOO:A16)","The admitted missing-shade case converts the derivation principle logically into an exception-tolerant general maxim."]],"CH_THN_SIOO:D9":[["The dispute over innate ideas is reconstructed as a question of whether ideas are preceded by livelier perceptions. (from Axioms CH_THN_SIOO:A2 + CH_THN_SIOO:A3 + CH_THN_SIOO:A11 + CH_THN_SIOO:A13)","The dispute over innate ideas is reconstructed as a question of whether ideas are preceded by livelier perceptions."]],"CH_THN_SIIM:D1":[["Memory and imagination differ by mode of recurrence rather than by the origin of their contents. (from Axioms CH_THN_SIIM:A1 + CH_THN_SIIM:A2 + CH_THN_SIIM:A3 + CH_THN_SIIM:A4)","Memory and imagination differ by mode of recurrence rather than by the origin of their contents."]],"CH_THN_SIIM:D2":[["Memory ideas are more forceful, lively, distinct, and stable than imagination ideas. (from Axioms CH_THN_SIIM:A3 + CH_THN_SIIM:A4)","Memory ideas are more forceful, lively, distinct, and stable than imagination ideas."]],"CH_THN_SIIM:D3":[["Memory’s characteristic work is preservation of relational order and position rather than preservation of simple contents as such. (from Axioms CH_THN_SIIM:A2 + CH_THN_SIIM:A5 + CH_THN_SIIM:A10)","Memory’s characteristic work is preservation of relational order and position rather than preservation of simple contents as such."]],"CH_THN_SIIM:D4":[["Deliberate narrative reordering remains compatible with memory when due positions are retained. (from Axioms CH_THN_SIIM:A5 + CH_THN_SIIM:A6)","Deliberate narrative reordering remains compatible with memory when due positions are retained."]],"CH_THN_SIIM:D5":[["Imagination can form unexperienced complexes by separating and rearranging impression-derived components. (from Axioms CH_THN_SIIM:A2 + CH_THN_SIIM:A7 + CH_THN_SIIM:A9 + CH_THN_SIIM:A10)","Imagination can form unexperienced complexes by separating and rearranging impression-derived components."]],"CH_THN_SIIM:D6":[["Perceived difference becomes compositional liberty because distinguishable components are separable rather than necessarily conjoined. (from Axioms CH_THN_SIIM:A7 + CH_THN_SIIM:A8 + CH_THN_SIIM:A9)","Perceived difference becomes compositional liberty because distinguishable components are separable rather than necessarily conjoined."]],"CH_THN_SVIE:MRT1":[["CH_THN_SVIE:A1 through CH_THN_SVIE:A9 are sufficient to reconstruct both the existence argument and its extension to external existence.","The chapter’s axioms are sufficient to reconstruct both the existence argument and its extension to external existence."]],"CH_THN_SVNI:D1":[["From CH_THN_SVNI:A2 + CH_THN_SVNI:A3 + CH_THN_SVNI:A6: bare conception, existential conception, and existential belief can preserve identical object-content.","Bare conception, existential conception, and existential belief can preserve identical object-content."]],"CH_THN_SVNI:D2":[["From CH_THN_SVNI:A4 + CH_THN_SVNI:A5 + CH_THN_SVNI:A6: factual assent cannot be identified by contradiction, intelligibility, or semantic content.","Factual assent cannot be identified by contradiction, intelligibility, or semantic content."]],"CH_THN_SVNI:D3":[["From CH_THN_SVNI:A7 + CH_THN_SVNI:A8 + CH_THN_SVNI:A11: the principle fixing opinion must operate through scalar intensification rather than representational modification.","The principle fixing opinion must operate through scalar intensification rather than representational modification."]],"CH_THN_SVNI:D4":[["From CH_THN_SVNI:A2 + CH_THN_SVNI:A16: existential judgments can contain only one object-idea, invalidating the universal model of judgment as the union of two ideas.","Existential judgments can contain only one object-idea, invalidating the universal model of judgment as the union of two ideas."]],"CH_THN_SVNI:D5":[["From CH_THN_SVNI:A13 + CH_THN_SVNI:A14 + CH_THN_SVNI:A16: causal inference can pass directly from a present perception to a correlative idea without an interposed third idea.","Causal inference can pass directly from a present perception to a correlative idea without an interposed third idea."]],"CH_THN_SVNI:D6":[["From CH_THN_SVNI:A12 + CH_THN_SVNI:A15: belief distinguishes experienced reality from fiction by cognitive weight and practical influence despite representational identity.","Belief distinguishes experienced reality from fiction by cognitive weight and practical influence despite representational identity."]],"CH_THN_SVNI:D7":[["From CH_THN_SVNI:A9 + CH_THN_SVNI:A11 + CH_THN_SVNI:A12: belief is not a third species of perception but an idea intensified toward the condition of an impression.","Belief is not a third species of perception but an idea intensified toward the condition of an impression."]],"CH_THN_SVNI:D8":[["From CH_THN_SVNI:A12 + CH_THN_SVNI:A17: force, vivacity, solidity, firmness, and steadiness are approximate names for one felt mode rather than separate constituents of belief.","Force, vivacity, solidity, firmness, and steadiness are approximate names for one felt mode rather than separate constituents of belief."]],"CH_THN_SVNI:MRT1":[["CH_THN_SVNI:A1–CH_THN_SVNI:A17 are sufficient to reconstruct the movement from representational invariance to the intensive definition of belief.","The chapter’s axioms are sufficient to reconstruct the movement from representational invariance to the intensive definition of belief."]],"CH_THN_SXUP:D1":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A7, the same remembered fact loses authority as its impression fades despite retaining the same propositional content.","The same remembered fact loses authority as its impression fades despite retaining the same propositional content."]],"CH_THN_SXUP:D2":[["From CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A5 + CH_THN_SXUP:A7 + CH_THN_SXUP:A14, recent observations receive disproportionate weight because both their impressions and their customary transitions remain intact.","Recent observations receive disproportionate weight because both their impressions and their customary transitions remain intact."]],"CH_THN_SXUP:D3":[["From CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A7, demonstratively connected reasoning can psychologically degenerate into probability when it requires many distinct transitions.","Demonstratively connected reasoning can psychologically degenerate into probability when it requires many distinct transitions."]],"CH_THN_SXUP:D4":[["From CH_THN_SXUP:A4 + CH_THN_SXUP:A8, historical evidence survives long transmission when repeated links are sufficiently homogeneous to be traversed as a compressed general sequence.","Historical evidence survives long transmission when repeated links are sufficiently homogeneous to be traversed as a compressed general sequence."]],"CH_THN_SXUP:D5":[["From CH_THN_SXUP:A7 + CH_THN_SXUP:A8, a chain composed of genuinely distinct probabilistic links would undergo repeated diminution, whereas homogeneous proof-preserving links need not.","A chain composed of genuinely distinct probabilistic links would undergo repeated diminution, whereas homogeneous proof-preserving links need not."]],"CH_THN_SXUP:D6":[["From CH_THN_SXUP:A5 + CH_THN_SXUP:A6 + CH_THN_SXUP:A10, prejudice is ordinary causal habit extended from conspicuous resemblance while material differences are neglected.","Prejudice is ordinary causal habit extended from conspicuous resemblance while material differences are neglected."]],"CH_THN_SXUP:D7":[["From CH_THN_SXUP:A10 + CH_THN_SXUP:A11 + CH_THN_SXUP:A12, philosophical correction occurs when a more general rule reclassifies a first-order customary inference as accidental.","Philosophical correction occurs when a more general rule reclassifies a first-order customary inference as accidental."]],"CH_THN_SXUP:D8":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A4 + CH_THN_SXUP:A12 + CH_THN_SXUP:A13 + CH_THN_SXUP:A14, convergence between judgment and a common sign produces stronger affect than an equally certain conclusion assembled from oblique signs.","Convergence between judgment and a common sign produces stronger affect than an equally certain conclusion assembled from oblique signs."]],"CH_THN_SXUP:D9":[["From CH_THN_SXUP:A11 + CH_THN_SXUP:A13 + CH_THN_SXUP:A14, social rules can make an originally stronger offense indirectly less painful by supplying a vivid adverse inference about the offender.","Social rules can make an originally stronger offense indirectly less painful by supplying a vivid adverse inference about the offender."]],"CH_THN_SXUP:D10":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A2 + CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A9, memory, proof, and probability form a descending continuum of vivacity rather than distinct species of belief.","Memory, proof, and probability form a descending continuum of vivacity rather than distinct species of belief."]],"CH_THN_SXUP:SD1":[["From CH_THN_SXUP:A5 + CH_THN_SXUP:A10 + CH_THN_SXUP:A11 + CH_THN_SXUP:A12, philosophical correction redirects custom from first-order resemblance toward more extensive regularity rather than opposing custom with an independent faculty.","Philosophical correction redirects custom from first-order resemblance toward more extensive regularity rather than opposing custom with an independent faculty."]],"CH_THN_SXUP:SD2":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A4 + CH_THN_SXUP:A7 + CH_THN_SXUP:A13, logical warrant and experienced conviction can vary independently because only the latter tracks the transmission of vivacity.","Logical warrant and experienced conviction can vary independently because only the latter tracks the transmission of vivacity."]],"CH_THN_SXUP:SD3":[["From CH_THN_SXUP:A7 + CH_THN_SXUP:A8 + CH_THN_SXUP:A13, effective inferential distance is determined by cognitive heterogeneity and labor rather than by the number of links alone.","Effective inferential distance is determined by cognitive heterogeneity and labor rather than by the number of links alone."]],"CH_THN_SXUP:SD4":[["From CH_THN_SXUP:A13 + CH_THN_SXUP:A14, modes of presentation can reorganize passion without altering the conclusion accepted by judgment.","Modes of presentation can reorganize passion without altering the conclusion accepted by judgment."]],"CH_THN_SXUP:SD5":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A2 + CH_THN_SXUP:A3 + CH_THN_SXUP:A9, proof and probability differ by the organization and intensity of one mechanism, not by possessing different psychological foundations.","Proof and probability differ by the organization and intensity of one mechanism, not by possessing different psychological foundations."]],"CH_THN_SXUP:SD6":[["From CH_THN_SXUP:A12 + CH_THN_SXUP:A15, philosophy remains disposition-sensitive because either the prejudicial rule or its corrective metarule may prevail in a particular mind.","Philosophy remains disposition-sensitive because either the prejudicial rule or its corrective metarule may prevail in a particular mind."]],"CH_THN_SVME:D1":[["(from CH_THN_SVME:A2 + CH_THN_SVME:A3 + CH_THN_SVME:A4) Comparison can change judgment while leaving representation unchanged because contrast alters the attendant emotion and custom attributes that alteration to the object.","Comparison can change judgment while leaving representation unchanged because contrast alters the attendant emotion and custom attributes that alteration to the object."]],"CH_THN_SVME:D2":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A5 + CH_THN_SVME:A6) Another’s misery elevates one’s apparent happiness and produces pleasure, while another’s happiness diminishes it and produces pain.","Another’s misery elevates one’s apparent happiness and produces pleasure, while another’s happiness diminishes it and produces pain."]],"CH_THN_SVME:D3":[["(from CH_THN_SVME:A6) The same misery can be painful under direct survey and pleasurable under comparative survey.","The same misery can be painful under direct survey and pleasurable under comparative survey."]],"CH_THN_SVME:D4":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A3 + CH_THN_SVME:A5) Past pain becomes agreeable when contrasted with present satisfaction, while past pleasure becomes painful when contrasted with present deficiency.","Past pain becomes agreeable when contrasted with present satisfaction, while past pleasure becomes painful when contrasted with present deficiency."]],"CH_THN_SVME:D5":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A3 + CH_THN_SVME:A12) Self-inflicted suffering can remove a contrast that would otherwise intensify predominant grief or the imagined punishment of remorse.","Self-inflicted suffering can remove a contrast that would otherwise intensify predominant grief or the imagined punishment of remorse."]],"CH_THN_SVME:D6":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A3 + CH_THN_SVME:A5 + CH_THN_SVME:A10) An inferior’s approach converts decreased comparative pleasure into positive pain by comparing the reduced advantage with its former degree.","An inferior’s approach converts decreased comparative pleasure into positive pain by comparing the reduced advantage with its former degree."]],"CH_THN_SVME:D7":[["(from CH_THN_SVME:A7 + CH_THN_SVME:A8 + CH_THN_SVME:A9 + CH_THN_SVME:A10) Nearby or resembling rivals provoke more envy than remote superiors because proximity sustains the transition required for comparison.","Nearby or resembling rivals provoke more envy than remote superiors because proximity sustains the transition required for comparison."]],"CH_THN_SVME:D8":[["(from CH_THN_SVME:A7 + CH_THN_SVME:A8 + CH_THN_SVME:A9) Separating related objects into distinct conceptual units prevents their attendant passions from influencing or contradicting one another.","Separating related objects into distinct conceptual units prevents their attendant passions from influencing or contradicting one another."]],"CH_THN_SVME:D9":[["(from CH_THN_SVME:A7 + CH_THN_SVME:A8 + CH_THN_SVME:A10) The mind seeks relief from related superiority either by breaking the association or by removing the superiority itself.","The mind seeks relief from related superiority either by breaking the association or by removing the superiority itself."]],"CH_THN_SVME:MRT1":[["CH_THN_SVME:A1–CH_THN_SVME:A12 are sufficient to reconstruct the perceptual mechanism, passion differentiation, and relational boundary.","The chapter’s axioms are sufficient to reconstruct the perceptual mechanism, passion differentiation, and relational boundary."]],"CH_THN_PIJI:MRT1":[["CH_THN_PIJI:A1–CH_THN_PIJI:A18 are sufficient to reconstruct the argument’s semantic, motivational, genealogical, institutional, and sentimental stages.","The chapter’s axioms are sufficient to reconstruct the argument’s semantic, motivational, genealogical, institutional, and sentimental stages."]],"CH_THN_SIRW:MRT1":[["CH_THN_SIRW:A1 through CH_THN_SIRW:A16 are sufficient to reconstruct the allocation problem, the dual explanatory mechanism, and the four established titles.","The chapter’s axioms are sufficient to reconstruct the allocation problem, the dual explanatory mechanism, and the four established titles."]],"CH_THN_SVSF:MRT1":[["CH_THN_SVSF:A1–CH_THN_SVSF:A17 are sufficient to reconstruct the chapter’s three proofs and final two-foundation model.","The chapter’s axioms are sufficient to reconstruct the chapter’s three proofs and final two-foundation model."]],"CH_THN_SIGB:MRT1":[["CH_THN_SIGB:A1–CH_THN_SIGB:A14 are sufficient to reconstruct the dual-source account of benevolent merit and its relational closure.","The chapter’s axioms are sufficient to reconstruct the dual-source account of benevolent merit and its relational closure."]],"CL_THN_01:GA-01":[["[Attractor] A secure science of human nature is the strategic center of scientific reconstruction because human faculties mediate every scientific judgment.","A secure science of human nature is the strategic center of scientific reconstruction because human faculties mediate every scientific judgment."]],"CL_THN_01:GA-02":[["[Persistent] Mental inquiry must proceed from experienced operations, effects, and relations rather than from speculative access to mental essence.","Mental inquiry must proceed from experienced operations, effects, and relations rather than from speculative access to mental essence."]],"CL_THN_01:GA-03":[["[Emergent] Empirical investigation of mind requires both a taxonomy of perceptions and a genealogy specifying their dependency and order.","Empirical investigation of mind requires both a taxonomy of perceptions and a genealogy specifying their dependency and order."]],"CL_THN_01:GA-04":[["[Persistent] Simple ideas generally derive on first appearance from corresponding prior simple impressions.","Simple ideas generally derive on first appearance from corresponding prior simple impressions."]],"CL_THN_01:GA-05":[["[Emergent] Restriction at the level of simple content permits recombination and recursive productivity at the level of complex ideas and later perceptions.","Restriction at the level of simple content permits recombination and recursive productivity at the level of complex ideas and later perceptions."]],"CL_THN_01:GA-06":[["[Mutating] Temporal priority establishes causal direction only within a specified dependency relation; it cannot assign one absolute order to impressions and ideas as total classes.","Temporal priority establishes causal direction only within a specified dependency relation; it cannot assign one absolute order to impressions and ideas as total classes."]],"CL_THN_01:GA-07":[["[Mutating] Ideas are derivative copies relative to sensation but productive mediators relative to impressions of reflection.","Ideas are derivative copies relative to sensation but productive mediators relative to impressions of reflection."]],"CL_THN_01:GA-08":[["[Emergent] Mental life forms an asymmetrically grounded recursive sequence: sensation → idea → reflection → idea → possible further perception.","Mental life forms an asymmetrically grounded recursive sequence: sensation → idea → reflection → idea → possible further perception."]],"CL_THN_01:GA-09":[["[Mutating] Proper methodological order follows the operative antecedents of the selected object, not necessarily the chronology of absolute origin.","Proper methodological order follows the operative antecedents of the selected object, not necessarily the chronology of absolute origin."]],"CL_THN_01:GA-10":[["[Terminal] The ultimate causes of sensation and the original qualities of human nature remain unavailable; legitimate explanation terminates at maximally general experienced relations.","The ultimate causes of sensation and the original qualities of human nature remain unavailable; legitimate explanation terminates at maximally general experienced relations."]],"CL_THN_01:GA-11":[["[Mutating] Scientific warrant at this level belongs to stable empirical generalization rather than exceptionless universality.","Scientific warrant at this level belongs to stable empirical generalization rather than exceptionless universality."]],"CL_THN_01:GA-12":[["[Attractor] The human subject functions as both the medium of inquiry and a relay within the perception-chain being investigated.","The human subject functions as both the medium of inquiry and a relay within the perception-chain being investigated."]],"CL_THN_01:CGD-01":[["[Local] The initial diagnosis of philosophical discredit and rhetorical controversy motivates the reconstruction but does not itself govern the later perceptual machinery.","The initial diagnosis of philosophical discredit and rhetorical controversy motivates the reconstruction but does not itself govern the later perceptual machinery."]],"CL_THN_01:CGD-02":[["[Local] Force and liveliness provide the initial impression–idea distinction, but exceptional states prevent them from functioning as the complete current-level criterion.","Force and liveliness provide the initial impression–idea distinction, but exceptional states prevent them from functioning as the complete current-level criterion."]],"CL_THN_01:CGD-03":[["[Local] The missing-shade case remains a concentrated anomaly rather than an alternative generative principle.","The missing-shade case remains a concentrated anomaly rather than an alternative generative principle."]],"CL_THN_01:CGD-04":[["[Scales upward] The prohibition on essence-first explanation becomes the common boundary governing both the science of human nature and the origin of perception.","The prohibition on essence-first explanation becomes the common boundary governing both the science of human nature and the origin of perception."]],"CL_THN_01:CGD-05":[["[Bridge] The simple–complex distinction links empirical restriction to imaginative productivity: primitive content is constrained while complex formation remains open.","The simple–complex distinction links empirical restriction to imaginative productivity: primitive content is constrained while complex formation remains open."]],"CL_THN_01:CGD-06":[["[Catalyst] Division of impressions into sensation and reflection converts the linear copy model into an asymmetrical recursive system.","Division of impressions into sensation and reflection converts the linear copy model into an asymmetrical recursive system."]],"CL_THN_01:CGD-07":[["[Superseded] Undifferentiated impressions-first method is recoded as a default valid only before object, scope, and internal dependency are specified.","Undifferentiated impressions-first method is recoded as a default valid only before object, scope, and internal dependency are specified."]],"CL_THN_01:CGD-08":[["[Scales upward] Disciplinary exclusion of sensory causes becomes a general methodological principle: proximate operations may be investigated securely without resolving absolute origins.","Disciplinary exclusion of sensory causes becomes a general methodological principle: proximate operations may be investigated securely without resolving absolute origins."]],"CL_THN_02:GA-01":[["[Persistent] Every legitimate idea must derive its elemental content from antecedent impression-material.","Every legitimate idea must derive its elemental content from antecedent impression-material."]],"CL_THN_02:GA-02":[["[Emergent] Elemental provenance and relational organization are distinct explanatory levels: identical copied materials can support preservation, recombination, association, or ordered appearance.","Elemental provenance and relational organization are distinct explanatory levels: identical copied materials can support preservation, recombination, association, or ordered appearance."]],"CL_THN_02:GA-03":[["[Attractor] Order is the common object of the cluster: memory conserves it, imagination alters it, association regenerates it, and space and time consist in its coexistent or successive forms.","Order is the common object of the cluster: memory conserves it, imagination alters it, association regenerates it, and space and time consist in its coexistent or successive forms."]],"CL_THN_02:GA-04":[["[Mutating] Difference licenses distinguishability and separability, but separation remains possible only where a positive component can be conceived apart.","Difference licenses distinguishability and separability, but separation remains possible only where a positive component can be conceived apart."]],"CL_THN_02:GA-05":[["[Persistent] Memory is recurrence under retained vivacity and fidelity to the experienced form, order, and position of its objects.","Memory is recurrence under retained vivacity and fidelity to the experienced form, order, and position of its objects."]],"CL_THN_02:GA-06":[["[Persistent] Imagination is dependent at the level of simple contents but free to separate, transpose, and recombine those contents at the level of arrangement.","Imagination is dependent at the level of simple contents but free to separate, transpose, and recombine those contents at the level of arrangement."]],"CL_THN_02:GA-07":[["[Emergent] Associative tendency mediates between compulsory connexion and random succession, producing regularity without abolishing imaginative liberty.","Associative tendency mediates between compulsory connexion and random succession, producing regularity without abolishing imaginative liberty."]],"CL_THN_02:GA-08":[["[Persistent] Resemblance, spatiotemporal contiguity, and cause and effect are the primary operators by which one idea introduces another.","Resemblance, spatiotemporal contiguity, and cause and effect are the primary operators by which one idea introduces another."]],"CL_THN_02:GA-09":[["[Mutating] Relational efficacy is graded: it propagates through intermediaries, weakens with distance, and expands causally from production to capacity and social influence.","Relational efficacy is graded: it propagates through intermediaries, weakens with distance, and expands causally from production to capacity and social influence."]],"CL_THN_02:GA-10":[["[Emergent] Space and time are ordered manners of appearance rather than independent impressions: extension is coexistent disposition, and duration is noncoexistent succession.","Space and time are ordered manners of appearance rather than independent impressions: extension is coexistent disposition, and duration is noncoexistent succession."]],"CL_THN_02:GA-11":[["[Mutating] Abstraction produces general representation by selectively regarding a determinate particular, not by generating a contentless universal.","Abstraction produces general representation by selectively regarding a determinate particular, not by generating a contentless universal."]],"CL_THN_02:GA-12":[["[Attractor] An idea’s genealogy limits its legitimate application: recombination may alter conjunctions, but predication cannot properly exceed the kind of content or order supplied by the originating impression.","An idea’s genealogy limits its legitimate application: recombination may alter conjunctions, but predication cannot properly exceed the kind of content or order supplied by the originating impression."]],"CL_THN_02:GA-13":[["[Terminal] Empirical explanation may stop at a recurrent principle established through its effects even when the ultimate cause of that principle remains inaccessible.","Empirical explanation may stop at a recurrent principle established through its effects even when the ultimate cause of that principle remains inaccessible."]],"CL_THN_02:GA-14":[["[Terminal] Conceptual decomposition cannot terminate in nonentity: spatial minima must retain sensible quality, and temporal minima must be filled by successive existence.","Conceptual decomposition cannot terminate in nonentity: spatial minima must retain sensible quality, and temporal minima must be filled by successive existence."]],"CL_THN_02:CGD-01":[["[Local] The precise degree of vivacity distinguishing memory from imagination remains a faculty-specific criterion and does not govern association or spatiotemporal conception.","The precise degree of vivacity distinguishing memory from imagination remains a faculty-specific criterion and does not govern association or spatiotemporal conception."]],"CL_THN_02:CGD-02":[["[Local] The claim that sight and touch alone provide extension’s source is required for spatial genealogy but does not scale into a general theory of all ideational recurrence.","The claim that sight and touch alone provide extension’s source is required for spatial genealogy but does not scale into a general theory of all ideational recurrence."]],"CL_THN_02:CGD-03":[["[Local] The asserted exhaustiveness of resemblance, contiguity, and causation remains local to the associative taxonomy; the current level requires only nonnecessary relational regulation.","The asserted exhaustiveness of resemblance, contiguity, and causation remains local to the associative taxonomy; the current level requires only nonnecessary relational regulation."]],"CL_THN_02:CGD-04":[["[Scaled] The copy principle scales upward because it constrains faculty content, abstract representation, spatial and temporal conception, and semantic application.","The copy principle scales upward because it constrains faculty content, abstract representation, spatial and temporal conception, and semantic application."]],"CL_THN_02:CGD-05":[["[Scaled] The distinction between content and arrangement becomes the cluster’s primary architecture, subsuming memory, imagination, association, space, and time.","The distinction between content and arrangement becomes the cluster’s primary architecture, subsuming memory, imagination, association, space, and time."]],"CL_THN_02:CGD-06":[["[Bridge] Separability connects imaginative composition to conceptual analysis, but its cross-unit use requires distinguishing separation from an original complex from separation from every content-bearing instance.","Separability connects imaginative composition to conceptual analysis, but its cross-unit use requires distinguishing separation from an original complex from separation from every content-bearing instance."]],"CL_THN_02:CGD-07":[["[Catalyst] Imaginative freedom generates the problem solved by association: once ideas can combine arbitrarily, recurrent regularity demands a non-random but noncompulsory principle.","Imaginative freedom generates the problem solved by association: once ideas can combine arbitrarily, recurrent regularity demands a non-random but noncompulsory principle."]],"CL_THN_02:CGD-08":[["[Superseded] The binary opposition between necessary determination and pure chance is replaced by graded tendency, custom, and attenuating relational force.","The binary opposition between necessary determination and pure chance is replaced by graded tendency, custom, and attenuating relational force."]],"CL_THN_02:CGD-09":[["[Recoded] Fiction is divided into lawful relational recombination and genealogically unsupported predication; novelty alone no longer determines illegitimacy.","Fiction is divided into lawful relational recombination and genealogically unsupported predication; novelty alone no longer determines illegitimacy."]],"CL_THN_02:CGD-10":[["[Transition] The expansion of causal association into social power demonstrates domain migration, but it does not itself govern the spatial and temporal ontology of the cluster.","The expansion of causal association into social power demonstrates domain migration, but it does not itself govern the spatial and temporal ontology of the cluster."]],"CL_THN_02:ALT-B01":[["[Surface] The explicit objects are memory, imagination, ideational association, extension, duration, abstraction, and the formation of complex ideas.","The explicit objects are memory, imagination, ideational association, extension, duration, abstraction, and the formation of complex ideas."]],"CL_THN_02:ALT-B02":[["[Structural] The active mechanisms are copying, recurrence, vivacity loss, order preservation, separation, recombination, associative routing, abstraction, and decomposition.","The active mechanisms are copying, recurrence, vivacity loss, order preservation, separation, recombination, associative routing, abstraction, and decomposition."]],"CL_THN_02:ALT-B03":[["[Metastrategic] Conceptual disputes are reframed as questions of source, operation, relational distance, and permissible application rather than contests among untested metaphysical entities.","Conceptual disputes are reframed as questions of source, operation, relational distance, and permissible application rather than contests among untested metaphysical entities."]],"CL_THN_02:ALT-B04":[["[Ontological / Temporal] Reality available to thought consists of content-bearing configurations, while time emerges from perceptible noncoexistence and is preserved or rearranged through mental recurrence.","Reality available to thought consists of content-bearing configurations, while time emerges from perceptible noncoexistence and is preserved or rearranged through mental recurrence."]],"CL_THN_02:ALT-B05":[["[Methodological / Performative] The system repeatedly performs its own claim by decomposing apparent unities, tracing their sources, removing unsupported additions, and reconstructing them as relational operations.","The system repeatedly performs its own claim by decomposing apparent unities, tracing their sources, removing unsupported additions, and reconstructing them as relational operations."]],"CL_THN_03:GA-01":[["[Persistent] Positive conceptual content is restricted to impressions, ideas, and their copied or recombined perceptual materials.","Positive conceptual content is restricted to impressions, ideas, and their copied or recombined perceptual materials."]],"CL_THN_03:GA-02":[["[Persistent] Existence is not an additional quality, predicate, or idea but is identical with the object as conceived.","Existence is not an additional quality, predicate, or idea but is identical with the object as conceived."]],"CL_THN_03:GA-03":[["[Emergent] Bare conception, existential conception, and factual belief can preserve identical representational content while producing radically different cognitive and practical effects.","Bare conception, existential conception, and factual belief can preserve identical representational content while producing radically different cognitive and practical effects."]],"CL_THN_03:GA-04":[["[Mutating] Belief begins as a difference in manner, becomes an intensification of force and vivacity, and terminates as a comparatively steady, impression-related, causally regulated mode.","Belief begins as a difference in manner, becomes an intensification of force and vivacity, and terminates as a comparatively steady, impression-related, causally regulated mode."]],"CL_THN_03:GA-05":[["[Persistent] Since contrary matters of fact remain conceivable, factual selection cannot arise from demonstrative necessity and must be determined by custom or association.","Since contrary matters of fact remain conceivable, factual selection cannot arise from demonstrative necessity and must be determined by custom or association."]],"CL_THN_03:GA-06":[["[Emergent] A present impression functions both as the experiential anchor of inference and as the reservoir from which vivacity is transmitted to a related idea.","A present impression functions both as the experiential anchor of inference and as the reservoir from which vivacity is transmitted to a related idea."]],"CL_THN_03:GA-07":[["[Emergent] Selective vivification gives absent and future objects present motivational efficacy without granting equivalent efficacy to every passing fiction.","Selective vivification gives absent and future objects present motivational efficacy without granting equivalent efficacy to every passing fiction."]],"CL_THN_03:GA-08":[["[Mutating] Force and vivacity expand from a distinction between impressions and ideas into a transmissible causal currency linking belief, passion, imagination, and action.","Force and vivacity expand from a distinction between impressions and ideas into a transmissible causal currency linking belief, passion, imagination, and action."]],"CL_THN_03:GA-09":[["[Emergent] Judgment, imagination, passion, and volition form a reciprocally permeable system rather than independent faculties.","Judgment, imagination, passion, and volition form a reciprocally permeable system rather than independent faculties."]],"CL_THN_03:GA-10":[["[Attractor] Factuality converges on stable practical presence: an idea counts as real for the mind by persistently affecting inference, passion, and conduct without acquiring new content.","Factuality converges on stable practical presence: an idea counts as real for the mind by persistently affecting inference, passion, and conduct without acquiring new content."]],"CL_THN_03:GA-11":[["[Terminal] First-order vividness cannot authenticate itself; settled conviction requires discrimination by source, steadiness, reality-connection, reflection, and general rules.","First-order vividness cannot authenticate itself; settled conviction requires discrimination by source, steadiness, reality-connection, reflection, and general rules."]],"CL_THN_03:GA-12":[["[Attractor] Reality is retained as a regulative relation organizing assent and correction while its intrinsic extra-perceptual nature remains positively unrepresented.","Reality is retained as a regulative relation organizing assent and correction while its intrinsic extra-perceptual nature remains positively unrepresented."]],"CL_THN_04:GA-01":[["[Persistent] Repeated conjunction and close relation acquire cognitive efficacy by facilitating transitions among perceptions rather than by revealing intrinsic bonds among objects.","Repeated conjunction and close relation acquire cognitive efficacy by facilitating transitions among perceptions rather than by revealing intrinsic bonds among objects."]],"CL_THN_04:GA-02":[["[Persistent] Neither substance nor causal power is available through mere inspection; actual causal judgment begins only from experienced relational structure.","Neither substance nor causal power is available through mere inspection; actual causal judgment begins only from experienced relational structure."]],"CL_THN_04:GA-03":[["[Mutating] Ease of mental transition produces belief when it transfers vivacity, but produces fictive identity and simplicity when its own fluency is attributed to objects.","Ease of mental transition produces belief when it transfers vivacity, but produces fictive identity and simplicity when its own fluency is attributed to objects."]],"CL_THN_04:GA-04":[["[Persistent] Natural customary transition precedes reflection and remains active after reflective correction; philosophy can redirect but cannot abolish it.","Natural customary transition precedes reflection and remains active after reflective correction; philosophy can redirect but cannot abolish it."]],"CL_THN_04:GA-05":[["[Mutating] Resemblance extends inference beyond identical cases, becoming prejudice when material differences are neglected and an experimental operator when resemblance is controlled by contrast.","Resemblance extends inference beyond identical cases, becoming prejudice when material differences are neglected and an experimental operator when resemblance is controlled by contrast."]],"CL_THN_04:GA-06":[["[Emergent] Reflection works through comparison, counterinstance, and circumstance-variation; it corrects fluent apprehension by making suppressed differences operationally salient.","Reflection works through comparison, counterinstance, and circumstance-variation; it corrects fluent apprehension by making suppressed differences operationally salient."]],"CL_THN_04:GA-07":[["[Emergent] Philosophical normativity is immanent to custom: more extensive and constant regularities regulate narrower associations without invoking an extra-customary tribunal.","Philosophical normativity is immanent to custom: more extensive and constant regularities regulate narrower associations without invoking an extra-customary tribunal."]],"CL_THN_04:GA-08":[["[Emergent] Actual causation is operationally constituted by contiguous, temporally ordered, uniform conjunction among experimentally discriminated circumstances.","Actual causation is operationally constituted by contiguous, temporally ordered, uniform conjunction among experimentally discriminated circumstances."]],"CL_THN_04:GA-09":[["[Persistent] Phenomena are compound, so causal identity must migrate from whole objects to qualities, differences, and auxiliary circumstances isolated through comparative tests.","Phenomena are compound, so causal identity must migrate from whole objects to qualities, differences, and auxiliary circumstances isolated through comparative tests."]],"CL_THN_04:GA-10":[["[Mutating] Contradiction and disappointed expectation do not determine their own resolution: they can provoke fictive substrates, prejudicial persistence, or renewed experimental decomposition.","Contradiction and disappointed expectation do not determine their own resolution: they can provoke fictive substrates, prejudicial persistence, or renewed experimental decomposition."]],"CL_THN_04:GA-11":[["[Persistent] Evidential warrant and experienced conviction are separable because conviction varies with vivacity, transition, temporal distance, and presentation, while warrant depends on comparative regularity.","Evidential warrant and experienced conviction are separable because conviction varies with vivacity, transition, temporal distance, and presentation, while warrant depends on comparative regularity."]],"CL_THN_04:GA-12":[["[Terminal] Corrective inquiry has no self-applying or final form: every metarule competes with prior habit, and every experiment becomes subject to renewed circumstance-analysis.","Corrective inquiry has no self-applying or final form: every metarule competes with prior habit, and every experiment becomes subject to renewed circumstance-analysis."]],"CL_THN_04:GA-13":[["[Attractor] Legitimate explanation converges on two constraints: terms must possess assignable ideational content, and causal distinctions must survive discriminating variation.","Legitimate explanation converges on two constraints: terms must possess assignable ideational content, and causal distinctions must survive discriminating variation."]],"CL_THN_04:GA-14":[["[Attractor] Moderate scepticism suspends claims to hidden substance and power while preserving disciplined empirical inquiry into observable regularities.","Moderate scepticism suspends claims to hidden substance and power while preserving disciplined empirical inquiry into observable regularities."]],"CL_THN_04:RMD-01":[["[Stable Identity] Constant conjunction retains its function as the empirical condition of causal inference while remaining explicitly distinct from perceived necessary connection.","Constant conjunction retains its function as the empirical condition of causal inference while remaining explicitly distinct from perceived necessary connection."]],"CL_THN_04:RMD-02":[["[Functional Recurrence] Facilitated transition recurs as belief-production, inferential compression, imputed identity, and imputed simplicity; its function changes with the object onto which fluency is projected.","Facilitated transition recurs as belief-production, inferential compression, imputed identity, and imputed simplicity; its function changes with the object onto which fluency is projected."]],"CL_THN_04:RMD-03":[["[Mutation] Custom moves from a first-order producer of expectation and prejudice to the material from which second-order philosophical rules are constructed.","Custom moves from a first-order producer of expectation and prejudice to the material from which second-order philosophical rules are constructed."]],"CL_THN_04:RMD-04":[["[Reversal] Resemblance changes from a source of illicit transfer into a controlled comparative instrument once difference is deliberately introduced.","Resemblance changes from a source of illicit transfer into a controlled comparative instrument once difference is deliberately introduced."]],"CL_THN_04:RMD-05":[["[Migration] Reflective comparison migrates from exposing variation and composition in bodies to isolating causal circumstances within compound phenomena.","Reflective comparison migrates from exposing variation and composition in bodies to isolating causal circumstances within compound phenomena."]],"CL_THN_04:RMD-06":[["[Escalation] The general rule expands from a correction of prejudicial inference into a recursive methodology for causal projection, decomposition, and experimental enlargement.","The general rule expands from a correction of prejudicial inference into a recursive methodology for causal projection, decomposition, and experimental enlargement."]],"CL_THN_04:RMD-07":[["[Displacement] Qualities cease to require a substantial bearer and become separable elements whose causal relevance must be experimentally determined.","Qualities cease to require a substantial bearer and become separable elements whose causal relevance must be experimentally determined."]],"CL_THN_04:RMD-08":[["[Terminal Transformation] Contradiction ceases to be evidence for an unknown substrate and becomes a demand to identify an omitted difference, scope condition, or auxiliary cause.","Contradiction ceases to be evidence for an unknown substrate and becomes a demand to identify an omitted difference, scope condition, or auxiliary cause."]],"CL_THN_04:RMD-09":[["[Absorption] The local theory of vivacity is absorbed into the current-level distinction between psychological uptake and methodological warrant.","The local theory of vivacity is absorbed into the current-level distinction between psychological uptake and methodological warrant."]],"CL_THN_04:RMD-10":[["[Disappearance] Substance, substantial form, accident, faculty, and occult quality disappear after supplying negative cases of how unexplained transition is converted into simulated ontology.","Substance, substantial form, accident, faculty, and occult quality disappear after supplying negative cases of how unexplained transition is converted into simulated ontology."]],"CL_THN_04:CGD-01":[["[Lower-Layer Local] Temporal fading, historical transmission, sign generality, and passion-amplification remain local specifications of how belief-force varies.","Temporal fading, historical transmission, sign generality, and passion-amplification remain local specifications of how belief-force varies."]],"CL_THN_04:CGD-02":[["[Lower-Layer Local] The individual comparative, proportional, and incomplete-cause rules remain local instruments; their recursive subjection to renewed variation scales upward.","The individual comparative, proportional, and incomplete-cause rules remain local instruments; their recursive subjection to renewed variation scales upward."]],"CL_THN_04:CGD-03":[["[Lower-Layer Local] The specific genealogy of matter, substantial forms, accidents, and occult qualities remains a local historical diagnosis.","The specific genealogy of matter, substantial forms, accidents, and occult qualities remains a local historical diagnosis."]],"CL_THN_04:CGD-04":[["[Scaled] The denial of intrinsic causal legibility scales upward into a general restriction against both a priori causal ontology and metaphysical explanation by hidden powers.","The denial of intrinsic causal legibility scales upward into a general restriction against both a priori causal ontology and metaphysical explanation by hidden powers."]],"CL_THN_04:CGD-05":[["[Bridge] The conflict between first-order and second-order general rules bridges the psychology of prejudice and the methodology of experimental causal judgment.","The conflict between first-order and second-order general rules bridges the psychology of prejudice and the methodology of experimental causal judgment."]],"CL_THN_04:CGD-06":[["[Bridge] Smooth mental transition connects belief-formation to fictive object-construction, revealing a shared mechanism beneath epistemic and ontological error.","Smooth mental transition connects belief-formation to fictive object-construction, revealing a shared mechanism beneath epistemic and ontological error."]],"CL_THN_04:CGD-07":[["[Catalyst] Reflectively disclosed contradiction catalyzes the transition from passive customary association to either metaphysical repair or active experimental differentiation.","Reflectively disclosed contradiction catalyzes the transition from passive customary association to either metaphysical repair or active experimental differentiation."]],"CL_THN_04:CGD-08":[["[Recoded] “Same cause” is recoded from identity of whole objects to identity of experimentally isolated operative circumstances.","“Same cause” is recoded from identity of whole objects to identity of experimentally isolated operative circumstances."]],"CL_THN_04:CGD-09":[["[Superseded] Objective substances, intrinsic faculties, and occult agencies are superseded by relational descriptions that remain answerable to assignable ideas and observable variation.","Objective substances, intrinsic faculties, and occult agencies are superseded by relational descriptions that remain answerable to assignable ideas and observable variation."]],"CL_THN_04:CGD-10":[["[Current-Level Emergent] Genuine philosophy becomes the conjunction of psychological self-diagnosis, comparative experiment, and refusal of semantically empty closure.","Genuine philosophy becomes the conjunction of psychological self-diagnosis, comparative experiment, and refusal of semantically empty closure."]],"CL_THN_05:GA-01":[["[Persistent] Legitimate explanation begins from experienced perceptions, conjunctions, pleasures, pains, and their observable transitions rather than from impression-transcendent entities.","Legitimate explanation begins from experienced perceptions, conjunctions, pleasures, pains, and their observable transitions rather than from impression-transcendent entities."]],"CL_THN_05:GA-02":[["[Emergent] Once unknown supports are excluded, the primary explanatory object becomes the network of relations and transformations among perceptions and affects.","Once unknown supports are excluded, the primary explanatory object becomes the network of relations and transformations among perceptions and affects."]],"CL_THN_05:GA-03":[["[Attractor] Imagination is simultaneously the indispensable medium of cognitive and affective synthesis and the source of fictive completion, contradiction, and excess.","Imagination is simultaneously the indispensable medium of cognitive and affective synthesis and the source of fictive completion, contradiction, and excess."]],"CL_THN_05:GA-04":[["[Mutating] Relation is not a uniform binary bond: it changes across separability, spatial compatibility, causal succession, self-reference, comparison, publicity, and temporal durability.","Relation is not a uniform binary bond: it changes across separability, spatial compatibility, causal succession, self-reference, comparison, publicity, and temporal durability."]],"CL_THN_05:GA-05":[["[Persistent] Repetition becomes operational through habit or custom, which projects conjunctions, stabilizes classifications, and regularizes otherwise delicate transitions.","Repetition becomes operational through habit or custom, which projects conjunctions, stabilizes classifications, and regularizes otherwise delicate transitions."]],"CL_THN_05:GA-06":[["[Emergent] Cognitive and affective efficacy requires force: vivacity, pleasure, pain, passion, or propensity must animate a relation before it governs assent or self-evaluation.","Cognitive and affective efficacy requires force: vivacity, pleasure, pain, passion, or propensity must animate a relation before it governs assent or self-evaluation."]],"CL_THN_05:GA-07":[["[Persistent] Causal intelligibility does not require perceived necessity; experienced conjunction and the transition it induces provide the operative causal content.","Causal intelligibility does not require perceived necessity; experienced conjunction and the transition it induces provide the operative causal content."]],"CL_THN_05:GA-08":[["[Persistent] Heterogeneous effects cannot be explained by indiscriminately extending one medium, faculty, or response-class over the entire field.","Heterogeneous effects cannot be explained by indiscriminately extending one medium, faculty, or response-class over the entire field."]],"CL_THN_05:GA-09":[["[Emergent] Unrestricted principles reveal their inadequacy by overgeneration: universal extension, pure reason, unrestricted fancy, and mere self-relation each produce contradictions or false positives.","Unrestricted principles reveal their inadequacy by overgeneration: universal extension, pure reason, unrestricted fancy, and mere self-relation each produce contradictions or false positives."]],"CL_THN_05:GA-10":[["[Mutating] Correction is immanent and restrictive: undecidability, skeptical diffidence, empirical practice, and threshold conditions limit mechanisms without abolishing them.","Correction is immanent and restrictive: undecidability, skeptical diffidence, empirical practice, and threshold conditions limit mechanisms without abolishing them."]],"CL_THN_05:GA-11":[["[Mutating] The self has no established status as a substantial bearer but remains indispensable as an object of passion and a temporally extended standard of comparison.","The self has no established status as a substantial bearer but remains indispensable as an object of passion and a temporally extended standard of comparison."]],"CL_THN_05:GA-12":[["[Emergent] Natural production and representational success do not guarantee correspondence: belief may lack rational foundation, apparent location may be fictive, and self-estimation may diverge from welfare.","Natural production and representational success do not guarantee correspondence: belief may lack rational foundation, apparent location may be fictive, and self-estimation may diverge from welfare."]],"CL_THN_05:GA-13":[["[Terminal] The viable endpoint is a reflexive science of human nature that investigates its own fallible operations under permanent skeptical and empirical restraint.","The viable endpoint is a reflexive science of human nature that investigates its own fallible operations under permanent skeptical and empirical restraint."]],"CL_THN_06:GA-01":[["[Persistent] Ideas and impressions differ principally in force and vivacity, permitting associative processes to transform represented affect into operative passion without changing its content.","Ideas and impressions differ principally in force and vivacity, permitting associative processes to transform represented affect into operative passion without changing its content."]],"CL_THN_06:GA-02":[["[Persistent] Relations are effective only as directed pathways that facilitate, preserve, intensify, interrupt, or redirect imaginative transition.","Relations are effective only as directed pathways that facilitate, preserve, intensify, interrupt, or redirect imaginative transition."]],"CL_THN_06:GA-03":[["[Persistent] Social passion requires a coupling between affective force and a relation that assigns or compares that force to a person.","Social passion requires a coupling between affective force and a relation that assigns or compares that force to a person."]],"CL_THN_06:GA-04":[["[Mutating] The self is not a sovereign source of valuation: its initial vivacity enables the very transitions through which external sentiments and comparative conditions alter it.","The self is not a sovereign source of valuation: its initial vivacity enables the very transitions through which external sentiments and comparative conditions alter it."]],"CL_THN_06:GA-05":[["[Mutating] Sympathy begins as conversion of an inferred sentiment into an impression but expands into constructive simulation capable of supplementing or replacing the source’s actual emotion.","Sympathy begins as conversion of an inferred sentiment into an impression but expands into constructive simulation capable of supplementing or replacing the source’s actual emotion."]],"CL_THN_06:GA-06":[["[Emergent] Sympathy and comparison are distinct transformations of retained affect: sympathy imports another’s represented condition, whereas comparison converts that condition into an inverse estimate of the self.","Sympathy and comparison are distinct transformations of retained affect: sympathy imports another’s represented condition, whereas comparison converts that condition into an inverse estimate of the self."]],"CL_THN_06:GA-07":[["[Emergent] Affective valence belongs neither to representation nor object alone; it depends on whether the object is directly surveyed, sympathetically appropriated, or comparatively opposed.","Affective valence belongs neither to representation nor object alone; it depends on whether the object is directly surveyed, sympathetically appropriated, or comparatively opposed."]],"CL_THN_06:GA-08":[["[Mutating] Personal attribution is regulated by forms of certification—durability, intention, authority, causal inference, and general expectation—that determine whether an affect is attached to a person and sustained.","Personal attribution is regulated by forms of certification—durability, intention, authority, causal inference, and general expectation—that determine whether an affect is attached to a person and sustained."]],"CL_THN_06:GA-09":[["[Emergent] Relational proximity is valence-neutral amplification: it can intensify affection, praise, pity, rivalry, envy, or humiliation according to the process routed through it.","Relational proximity is valence-neutral amplification: it can intensify affection, praise, pity, rivalry, envy, or humiliation according to the process routed through it."]],"CL_THN_06:GA-10":[["[Attractor] Social affect has a topology in which authority, resemblance, contiguity, acquaintance, convergence, direction, and separation govern force more decisively than bare content or absolute rank.","Social affect has a topology in which authority, resemblance, contiguity, acquaintance, convergence, direction, and separation govern force more decisively than bare content or absolute rank."]],"CL_THN_06:GA-11":[["[Attractor] The recurrent generative circuit is self → related other → transformed affect → altered self, with the altered self producing further judgments, signs, desires, and reflected sentiments.","The recurrent generative circuit is self → related other → transformed affect → altered self, with the altered self producing further judgments, signs, desires, and reflected sentiments."]],"CL_THN_06:GA-12":[["[Terminal] Passions can endogenously produce the beliefs and imagined conditions that preserve or amplify them.","Passions can endogenously produce the beliefs and imagined conditions that preserve or amplify them."]],"CL_THN_06:GA-13":[["[Terminal] No intrinsic affective baseline stabilizes self-worth, social value, or hierarchy independently of transmitted sentiment and active comparison.","No intrinsic affective baseline stabilizes self-worth, social value, or hierarchy independently of transmitted sentiment and active comparison."]],"CL_THN_06:RMD-01":[["[Stable identity] Force and vivacity retain their function as the common currency linking ideas, impressions, associative transitions, and passions.","Force and vivacity retain their function as the common currency linking ideas, impressions, associative transitions, and passions."]],"CL_THN_06:RMD-02":[["[Functional recurrence] Relation recurs as a conductor of sympathy, a condition of durable affection, a bidirectional pathway of attachment, and a gate permitting comparative impressions to interact.","Relation recurs as a conductor of sympathy, a condition of durable affection, a bidirectional pathway of attachment, and a gate permitting comparative impressions to interact."]],"CL_THN_06:RMD-03":[["[Mutation] Sympathy shifts from reproducing another’s expressed sentiment to appropriating proprietary satisfaction and finally to constructing sorrow absent from the observed person.","Sympathy shifts from reproducing another’s expressed sentiment to appropriating proprietary satisfaction and finally to constructing sorrow absent from the observed person."]],"CL_THN_06:RMD-04":[["[Domain migration] Resemblance moves from general human access to other minds, through affection and pity, into the wider topology determining which persons become affectively comparable.","Resemblance moves from general human access to other minds, through affection and pity, into the wider topology determining which persons become affectively comparable."]],"CL_THN_06:RMD-05":[["[Mutation] The self moves from vivid associative origin, to object of socially communicated judgment, to variable magnitude constituted against related others.","The self moves from vivid associative origin, to object of socially communicated judgment, to variable magnitude constituted against related others."]],"CL_THN_06:RMD-06":[["[Reversal] Pleasure and pain cease to have invariant direction: another’s satisfaction can become esteem through sympathy or pain through comparison, while another’s misery can become pity or malicious pleasure.","Pleasure and pain cease to have invariant direction: another’s satisfaction can become esteem through sympathy or pain through comparison, while another’s misery can become pity or malicious pleasure."]],"CL_THN_06:RMD-07":[["[Reversal] Proximity changes from a means of sympathetic intimacy into a condition of intensified rivalry without ceasing to perform its basic function of preserving affect across transition.","Proximity changes from a means of sympathetic intimacy into a condition of intensified rivalry without ceasing to perform its basic function of preserving affect across transition."]],"CL_THN_06:RMD-08":[["[Escalation] General rules progress from tests of causal regularity to constructive templates that supply absent passions and project altered emotional magnitude back onto objects.","General rules progress from tests of causal regularity to constructive templates that supply absent passions and project altered emotional magnitude back onto objects."]],"CL_THN_06:RMD-09":[["[Absorption] Intention and evaluator authority lose the status of isolated causes and become forms of personal certification governing durable attribution and evidential uptake.","Intention and evaluator authority lose the status of isolated causes and become forms of personal certification governing durable attribution and evidential uptake."]],"CL_THN_06:RMD-10":[["[Terminal transformation] Esteem becomes recursive social capital: communicated satisfaction generates esteem, perceived esteem increases satisfaction, and renewed satisfaction generates further esteem.","Esteem becomes recursive social capital: communicated satisfaction generates esteem, perceived esteem increases satisfaction, and renewed satisfaction generates further esteem."]],"CL_THN_06:RMD-11":[["[Disappearance] Original fame, intrinsic wealth-value, calculated advantage, and autonomous malevolence disappear after their explanatory roles are redistributed across sympathy, comparison, and associative topology.","Original fame, intrinsic wealth-value, calculated advantage, and autonomous malevolence disappear after their explanatory roles are redistributed across sympathy, comparison, and associative topology."]],"CL_THN_06:CGD-01":[["[Lower-layer local] The exact weighting of evaluator authority, self-concurrence, jest, and numerical accumulation remains specific to reputational influence rather than defining every social passion.","The exact weighting of evaluator authority, self-concurrence, jest, and numerical accumulation remains specific to reputational influence rather than defining every social passion."]],"CL_THN_06:CGD-02":[["[Lower-layer local] The distinction between durable qualities and transient intentional actions solves the temporal attribution of love and hatred but scales upward only as a general certification principle.","The distinction between durable qualities and transient intentional actions solves the temporal attribution of love and hatred but scales upward only as a general certification principle."]],"CL_THN_06:CGD-03":[["[Lower-layer local] The contingent conjunction of love with benevolence and hatred with anger remains an irreducible constitutional supplement rather than a global relational mechanism.","The contingent conjunction of love with benevolence and hatred with anger remains an irreducible constitutional supplement rather than a global relational mechanism."]],"CL_THN_06:CGD-04":[["[Lower-layer local] Habitual projection from altered emotion to altered object-magnitude is the specific perceptual machinery of comparative judgment, not the general form of sympathy.","Habitual projection from altered emotion to altered object-magnitude is the specific perceptual machinery of comparative judgment, not the general form of sympathy."]],"CL_THN_06:CGD-05":[["[Scales upward] Force, vivacity, associative transition, and retained impressions form the common machinery through which all three units generate social affect.","Force, vivacity, associative transition, and retained impressions form the common machinery through which all three units generate social affect."]],"CL_THN_06:CGD-06":[["[Bridge] Fame and wealth-esteem jointly establish that social rank is produced by circulated satisfaction and reflected judgment rather than by isolated possession or intrinsic excellence.","Fame and wealth-esteem jointly establish that social rank is produced by circulated satisfaction and reflected judgment rather than by isolated possession or intrinsic excellence."]],"CL_THN_06:CGD-07":[["[Bridge] Pity and envy demonstrate that proximity does not determine valence; it intensifies whichever sympathetic or comparative operation controls the transition.","Pity and envy demonstrate that proximity does not determine valence; it intensifies whichever sympathetic or comparative operation controls the transition."]],"CL_THN_06:CGD-08":[["[Catalyst] Constructed pity, resisted contempt, and direct pain joined to comparative pleasure force the separation of affective reception from belief, source-fidelity, and direct valence.","Constructed pity, resisted contempt, and direct pain joined to comparative pleasure force the separation of affective reception from belief, source-fidelity, and direct valence."]],"CL_THN_06:CGD-09":[["[Superseded] Primitive social appetites and static classifications are recoded as outputs of directed transitions, relational weights, and recursive feedback.","Primitive social appetites and static classifications are recoded as outputs of directed transitions, relational weights, and recursive feedback."]],"CL_THN_07:GA-01":[["[Attractor] Affective value is constituted through an encounter between an object and an operating sensitive system, not fixed by the object alone.","Affective value is constituted through an encounter between an object and an operating sensitive system, not fixed by the object alone."]],"CL_THN_07:GA-02":[["[Persistent] Pleasure and pain function both as direct effects and as mobile forces capable of augmenting, redirecting, transmitting, or reversing passions.","Pleasure and pain function both as direct effects and as mobile forces capable of augmenting, redirecting, transmitting, or reversing passions."]],"CL_THN_07:GA-03":[["[Mutating] Cognitive capacity is not the universal source of passion; it regulates the accessibility, complexity, and prevalence of particular affective channels.","Cognitive capacity is not the universal source of passion; it regulates the accessibility, complexity, and prevalence of particular affective channels."]],"CL_THN_07:GA-04":[["[Emergent] Affective causes become identifiable through controlled differences: remove reflection, vary repetition, or hold truth and assurance constant while altering the mode of attainment.","Affective causes become identifiable through controlled differences: remove reflection, vary repetition, or hold truth and assurance constant while altering the mode of attainment."]],"CL_THN_07:GA-05":[["[Mutating] Difficulty, facility, excitation, and stability have no invariant valence; their effects depend on degree, temporal position, and active or passive mode.","Difficulty, facility, excitation, and stability have no invariant valence; their effects depend on degree, temporal position, and active or passive mode."]],"CL_THN_07:GA-06":[["[Emergent] Affect is transferable across functional relations: from attendant emotion into a predominant passion, from action into its end, and from one sensitive being into another.","Affect is transferable across functional relations: from attendant emotion into a predominant passion, from action into its end, and from one sensitive being into another."]],"CL_THN_07:GA-07":[["[Persistent] Present passion is path-dependent: prior encounters, repeated performances, acquired inclinations, and transferred concerns enter into its current constitution.","Present passion is path-dependent: prior encounters, repeated performances, acquired inclinations, and transferred concerns enter into its current constitution."]],"CL_THN_07:GA-08":[["[Mutating] Relation is a generative operator rather than a static resemblance: it supports animal attachment, strengthens ideational force, transfers concern, and fixes attention.","Relation is a generative operator rather than a static resemblance: it supports animal attachment, strengthens ideational force, transfers concern, and fixes attention."]],"CL_THN_07:GA-09":[["[Emergent] Activity and passivity divide affective dynamics: active exercise can sustain force and produce concern, while passive reception tends toward transmitted affect, fading excitation, or uncertainty-relief.","Activity and passivity divide affective dynamics: active exercise can sustain force and produce concern, while passive reception tends toward transmitted affect, fading excitation, or uncertainty-relief."]],"CL_THN_07:GA-10":[["[Mutating] Stability is pleasurable when it resolves resistance or vacillation, but destructive when excessive facility removes the excitation required for interest.","Stability is pleasurable when it resolves resistance or vacillation, but destructive when excessive facility removes the excitation required for interest."]],"CL_THN_07:GA-11":[["[Emergent] Concern for an end need not precede the process directed toward it; repetition and pleasurable activity can generate inclination or acquired end-concern retrospectively.","Concern for an end need not precede the process directed toward it; repetition and pleasurable activity can generate inclination or acquired end-concern retrospectively."]],"CL_THN_07:GA-12":[["[Terminal] Affective plasticity is bounded by prior endowment: natural good and evil, complete disagreeability, instinct, and pre-existing salience constrain what process can produce.","Affective plasticity is bounded by prior endowment: natural good and evil, complete disagreeability, instinct, and pre-existing salience constrain what process can produce."]],"CL_THN_07:GA-13":[["[Terminal] The field is unified by species-general and recursively transferable operations, not by a single uniform mechanism of affective production.","The field is unified by species-general and recursively transferable operations, not by a single uniform mechanism of affective production."]],"CL_THN_07:RMD-01":[["[Stable identity] Pleasure and pain remain the basic affective currency, but their source migrates from sensible benefit and injury to mental motion, exercised understanding, belief, and doubt.","Pleasure and pain remain the basic affective currency, but their source migrates from sensible benefit and injury to mental motion, exercised understanding, belief, and doubt."]],"CL_THN_07:RMD-02":[["[Mutation] Cognition shifts from a capacity whose subtraction tests affective simplicity to an activity whose difficult exercise becomes an original source of pleasure.","Cognition shifts from a capacity whose subtraction tests affective simplicity to an activity whose difficult exercise becomes an original source of pleasure."]],"CL_THN_07:RMD-03":[["[Expansion] Relation begins as obvious animal association, then expands into attentional support, ideational force, and the transfer of passion from pursuit to end.","Relation begins as obvious animal association, then expands into attentional support, ideational force, and the transfer of passion from pursuit to end."]],"CL_THN_07:RMD-04":[["[Reversal] Difficulty is painful resistance in unfamiliar passive apprehension but pleasurable exercise when attention and attainable success organize active inquiry.","Difficulty is painful resistance in unfamiliar passive apprehension but pleasurable exercise when attention and attainable success organize active inquiry."]],"CL_THN_07:RMD-05":[["[Reversal] Familiarity extinguishes novelty and may produce languor under custom, yet can intensify informational curiosity by strengthening relation and ideational force.","Familiarity extinguishes novelty and may produce languor under custom, yet can intensify informational curiosity by strengthening relation and ideational force."]],"CL_THN_07:RMD-06":[["[Functional recurrence] Stabilization recurs as tranquillity, orderly facility, and fixed belief; it relieves disturbance but ceases to sustain interest once movement becomes excessively faint.","Stabilization recurs as tranquillity, orderly facility, and fixed belief; it relieves disturbance but ceases to sustain interest once movement becomes excessively faint."]],"CL_THN_07:RMD-07":[["[Displacement] Sympathy moves from direct communication of animal passion to faint imaginative concern whose function is not benevolence but attentional fixation.","Sympathy moves from direct communication of animal passion to faint imaginative concern whose function is not benevolence but attentional fixation."]],"CL_THN_07:RMD-08":[["[Absorption] The active/passive distinction moves from habit formation into a higher division between self-sustaining pursuit and receptive uncertainty-relief.","The active/passive distinction moves from habit formation into a higher division between self-sustaining pursuit and receptive uncertainty-relief."]],"CL_THN_07:RMD-09":[["[Terminal transformation] Truth disappears as an intrinsic motive after performing an exclusionary function, then returns as either an acquired endpoint of pursuit or the content stabilized by belief.","Truth disappears as an intrinsic motive after performing an exclusionary function, then returns as either an acquired endpoint of pursuit or the content stabilized by belief."]],"CL_THN_07:RMD-10":[["[Disappearance after structural work] Peculiar parental instinct does not generalize into the cluster’s main process model, but remains as the exception that blocks exhaustive associative reduction.","Peculiar parental instinct does not generalize into the cluster’s main process model, but remains as the exception that blocks exhaustive associative reduction."]],"CL_THN_07:CGD-01":[["[Local] Peculiar parental instinct remains specific to animal affection; at cluster scale it functions chiefly as a limit on causal monism.","Peculiar parental instinct remains specific to animal affection; at cluster scale it functions chiefly as a limit on causal monism."]],"CL_THN_07:CGD-02":[["[Local] The motion of the spirits is a chapter-level causal vocabulary for custom whose exact physiology does not scale upward.","The motion of the spirits is a chapter-level causal vocabulary for custom whose exact physiology does not scale upward."]],"CL_THN_07:CGD-03":[["[Local] The division between abstract relations and matters of existence, and the special role of imagined public utility, remain machinery of scientific curiosity.","The division between abstract relations and matters of existence, and the special role of imagined public utility, remain machinery of scientific curiosity."]],"CL_THN_07:CGD-04":[["[Scales upward] The survival of passion under reduced reflection becomes the general proposition that cognition selects affective routes without constituting sensitive life itself.","The survival of passion under reduced reflection becomes the general proposition that cognition selects affective routes without constituting sensitive life itself."]],"CL_THN_07:CGD-05":[["[Scales upward] Custom’s degree-sensitive phases become a general rule that affective operations change valence according to threshold, sequence, and mode.","Custom’s degree-sensitive phases become a general rule that affective operations change valence according to threshold, sequence, and mode."]],"CL_THN_07:CGD-06":[["[Bridge] Conversion, relational transfer, and sympathy jointly produce the current-level principle of mobile affective force.","Conversion, relational transfer, and sympathy jointly produce the current-level principle of mobile affective force."]],"CL_THN_07:CGD-07":[["[Bridge] The active/passive habit distinction connects custom to curiosity’s division between challenge-seeking inquiry and uncertainty-relieving fixation.","The active/passive habit distinction connects custom to curiosity’s division between challenge-seeking inquiry and uncertainty-relieving fixation."]],"CL_THN_07:CGD-08":[["[Catalyst] Animal comparison, repeated encounter, and equal-truth comparison become three implementations of one differential method for separating content from operation.","Animal comparison, repeated encounter, and equal-truth comparison become three implementations of one differential method for separating content from operation."]],"CL_THN_07:CGD-09":[["[Recoded] Sensible benefit, natural emotion, utility, and truth retain local efficacy but are subordinated to the histories and operations through which they become affectively forceful.","Sensible benefit, natural emotion, utility, and truth retain local efficacy but are subordinated to the histories and operations through which they become affectively forceful."]],"CL_THN_08:GA-01":[["[Persistent] Society is necessary under conditions in which human weakness, partial affection, conflicting self-love, and scarce transferable goods make unregulated possession unstable.","Society is necessary under conditions in which human weakness, partial affection, conflicting self-love, and scarce transferable goods make unregulated possession unstable."]],"CL_THN_08:GA-02":[["[Persistent] A moral predicate cannot supply the first motive for the conduct whose morality it evaluates; institutional genesis must therefore begin from pre-moral passions and interests.","A moral predicate cannot supply the first motive for the conduct whose morality it evaluates; institutional genesis must therefore begin from pre-moral passions and interests."]],"CL_THN_08:GA-03":[["[Attractor] Justice is artificial without being arbitrary: it is convention-dependent in origin but functionally necessitated by durable human and material conditions.","Justice is artificial without being arbitrary: it is convention-dependent in origin but functionally necessitated by durable human and material conditions."]],"CL_THN_08:GA-04":[["[Persistent] Convention arises through mutually known, conditionally reciprocal restraint grounded in common interest and repeated experience, not through an antecedent promise or sovereign command.","Convention arises through mutually known, conditionally reciprocal restraint grounded in common interest and repeated experience, not through an antecedent promise or sovereign command."]],"CL_THN_08:GA-05":[["[Mutating] Self-interest changes function across scales: immediate acquisition destabilizes society, while reflective and coordinated self-interest generates the rules that restrain acquisition.","Self-interest changes function across scales: immediate acquisition destabilizes society, while reflective and coordinated self-interest generates the rules that restrain acquisition."]],"CL_THN_08:GA-06":[["[Terminal] Property is not antecedent to justice but is constituted as a socially enforced relation of duties, expectations, rights, and exclusions.","Property is not antecedent to justice but is constituted as a socially enforced relation of duties, expectations, rights, and exclusions."]],"CL_THN_08:GA-07":[["[Emergent] The convention stabilizing possession does not itself assign goods; institutional existence and juridical individuation are distinct generative problems.","The convention stabilizing possession does not itself assign goods; institutional existence and juridical individuation are distinct generative problems."]],"CL_THN_08:GA-08":[["[Emergent] Property has a dual determination: general utility necessitates settled allocation, while imagination and antecedent relations principally specify who receives which title.","Property has a dual determination: general utility necessitates settled allocation, while imagination and antecedent relations principally specify who receives which title."]],"CL_THN_08:GA-09":[["[Persistent] Stable justice requires society-wide general and inflexible rules because case-sensitive judgments of need, merit, fitness, or immediate utility reproduce partiality and contention.","Stable justice requires society-wide general and inflexible rules because case-sensitive judgments of need, merit, fitness, or immediate utility reproduce partiality and contention."]],"CL_THN_08:GA-10":[["[Mutating] Title is temporally layered: present possession governs founding settlement, while occupation, prescription, accession, and succession govern differentiated acquisition within established society.","Title is temporally layered: present possession governs founding settlement, while occupation, prescription, accession, and succession govern differentiated acquisition within established society."]],"CL_THN_08:GA-11":[["[Emergent] Juridical outputs are integral and binary even though their psychological, utilitarian, temporal, and relational grounds vary by degree.","Juridical outputs are integral and binary even though their psychological, utilitarian, temporal, and relational grounds vary by degree."]],"CL_THN_08:GA-12":[["[Terminal] Municipal law supplies practical closure where natural association and public utility fail to determine a unique title.","Municipal law supplies practical closure where natural association and public utility fail to determine a unique title."]],"CL_THN_08:GA-13":[["[Attractor] The justice of an act derives from its position within a socially advantageous rule-system rather than from its isolated consequences.","The justice of an act derives from its position within a socially advantageous rule-system rather than from its isolated consequences."]],"CL_THN_08:GA-14":[["[Persistent] Justice has a temporally divided foundation: common interest generates observance before sympathy with public utility generates moral approval.","Justice has a temporally divided foundation: common interest generates observance before sympathy with public utility generates moral approval."]],"CL_THN_08:GA-15":[["[Attractor] Once established, convention, juridical determination, moral approbation, education, reputation, and government form a reinforcing system that converts artificial rules into durable dispositions.","Once established, convention, juridical determination, moral approbation, education, reputation, and government form a reinforcing system that converts artificial rules into durable dispositions."]],"CL_THN_08:RMD-01":[["[Stable identity] Justice remains an artificial virtue throughout: neither its necessity, its utility, nor its affective approval converts it into an innate moral principle.","Justice remains an artificial virtue throughout: neither its necessity, its utility, nor its affective approval converts it into an innate moral principle."]],"CL_THN_08:RMD-02":[["[Functional recurrence] Stability of possession first solves social conflict, then reappears as an insufficient general rule whose allocation gap generates the detailed property regime.","Stability of possession first solves social conflict, then reappears as an insufficient general rule whose allocation gap generates the detailed property regime."]],"CL_THN_08:RMD-03":[["[Escalation] Property moves from an effect of stabilized possession, to a differentiated system of relational titles, to evidence that juridical reality is institutionally constituted.","Property moves from an effect of stabilized possession, to a differentiated system of relational titles, to evidence that juridical reality is institutionally constituted."]],"CL_THN_08:RMD-04":[["[Mutation] Utility first explains why justice is necessary, then becomes insufficient to specify particular titles, and finally becomes the public effect whose contemplation moralizes the completed system.","Utility first explains why justice is necessary, then becomes insufficient to specify particular titles, and finally becomes the public effect whose contemplation moralizes the completed system."]],"CL_THN_08:RMD-05":[["[Reversal] Self-love changes from the principal source of possessory conflict into the originating material of reciprocal restraint and unintended public advantage.","Self-love changes from the principal source of possessory conflict into the originating material of reciprocal restraint and unintended public advantage."]],"CL_THN_08:RMD-06":[["[Displacement] Imagination migrates from a general psychological faculty of associative completion into a juridical mechanism that joins persons to objects, extends titles, and structures inheritance.","Imagination migrates from a general psychological faculty of associative completion into a juridical mechanism that joins persons to objects, extends titles, and structures inheritance."]],"CL_THN_08:RMD-07":[["[Mutation] Generality changes from reciprocal abstention governing possession into differentiated but society-wide rules whose inflexibility suppresses case-specific natural motivation.","Generality changes from reciprocal abstention governing possession into differentiated but society-wide rules whose inflexibility suppresses case-specific natural motivation."]],"CL_THN_08:RMD-08":[["[Terminal transformation] Present possession produces founding title but disappears as a perpetual criterion once its founding work is complete; occupation and restitution require its restriction.","Present possession produces founding title but disappears as a perpetual criterion once its founding work is complete; occupation and restitution require its restriction."]],"CL_THN_08:RMD-09":[["[Migration] Graduality moves from possessory probability and temporal association into a general challenge to the integral form of property, right, and obligation.","Graduality moves from possessory probability and temporal association into a general challenge to the integral form of property, right, and obligation."]],"CL_THN_08:RMD-10":[["[Absorption] Sympathy begins as the explanation of moral approval and is absorbed into a larger institutional feedback loop involving public judgment, education, reputation, and stabilized compliance.","Sympathy begins as the explanation of moral approval and is absorbed into a larger institutional feedback loop involving public judgment, education, reputation, and stabilized compliance."]],"CL_THN_08:RMD-11":[["[Disappearance after structural work] Universal benevolence, direct public concern, private benevolence, and an innate sense of justice disappear as originating motives after forcing the transition to convention and reflected interest.","Universal benevolence, direct public concern, private benevolence, and an innate sense of justice disappear as originating motives after forcing the transition to convention and reflected interest."]],"CL_THN_08:CGD-01":[["[Local-to-scaling] The semantic disambiguation of “nature” remains preparatory machinery, but it scales upward by preventing artificial justice from being classified as unnatural, arbitrary, or morally defective.","The semantic disambiguation of “nature” remains preparatory machinery, but it scales upward by preventing artificial justice from being classified as unnatural, arbitrary, or morally defective."]],"CL_THN_08:CGD-02":[["[Local] The detailed taxonomies of occupation, prescription, accession, and succession remain lower-layer jurisprudential machinery; only their common relational and temporal structure scales upward.","The detailed taxonomies of occupation, prescription, accession, and succession remain lower-layer jurisprudential machinery; only their common relational and temporal structure scales upward."]],"CL_THN_08:CGD-03":[["[Scales upward] The convention of stable possession becomes the cluster’s constitutive threshold between physical control and normative property.","The convention of stable possession becomes the cluster’s constitutive threshold between physical control and normative property."]],"CL_THN_08:CGD-04":[["[Bridge] Imagination bridges institutional necessity and determinate title by converting natural relations of proximity, causality, duration, scale, and kinship into socially stabilized juridical attachments.","Imagination bridges institutional necessity and determinate title by converting natural relations of proximity, causality, duration, scale, and kinship into socially stabilized juridical attachments."]],"CL_THN_08:CGD-05":[["[Bridge] The priority of motive over moral judgment bridges the sentimental theory of virtue and the institutional genealogy by requiring pre-moral interest to precede moral obligation.","The priority of motive over moral judgment bridges the sentimental theory of virtue and the institutional genealogy by requiring pre-moral interest to precede moral obligation."]],"CL_THN_08:CGD-06":[["[Catalyst] The gradation test converts local observations about fluid possession and natural motivation into a general explanation of why juridical decision requires imposed binary closure.","The gradation test converts local observations about fluid possession and natural motivation into a general explanation of why juridical decision requires imposed binary closure."]],"CL_THN_08:CGD-07":[["[Superseded] Present possession is indispensable at the founding threshold but becomes invalid as a universal title once an established regime supports restitution and differentiated acquisition.","Present possession is indispensable at the founding threshold but becomes invalid as a universal title once an established regime supports restitution and differentiated acquisition."]],"CL_THN_08:CGD-08":[["[Recoded] Education, reputation, and political reinforcement do not originate justice; they recode an established convention as honor, duty, and second nature.","Education, reputation, and political reinforcement do not originate justice; they recode an established convention as honor, duty, and second nature."]],"CL_THN_08:CGD-09":[["[Local] The solitary state of nature remains an analytical fiction used to isolate passions from understanding; the cluster does not require it as an actual historical stage.","The solitary state of nature remains an analytical fiction used to isolate passions from understanding; the cluster does not require it as an actual historical stage."]],"CL_THN_08:CGD-10":[["[Peripheral] Consensual transfer and promise-performance mark the broader perimeter of justice, but the current architecture develops possession and property rather than independently reconstructing those laws.","Consensual transfer and promise-performance mark the broader perimeter of justice, but the current architecture develops possession and property rather than independently reconstructing those laws."]],"CL_THN_08:ALT-B01":[["[Surface] The explicit objects are justice, stable possession, property, acquisition, title, adjudication, and the moral approval attached to their observance.","The explicit objects are justice, stable possession, property, acquisition, title, adjudication, and the moral approval attached to their observance."]],"CL_THN_08:ALT-B02":[["[Structural] Partial passions, scarcity, reciprocal expectations, general rules, associative imagination, municipal closure, and sympathetic reinforcement form the operative institutional system.","Partial passions, scarcity, reciprocal expectations, general rules, associative imagination, municipal closure, and sympathetic reinforcement form the operative institutional system."]],"CL_THN_08:ALT-B03":[["[Metastrategic] Explanation proceeds by reversing presumed dependencies: motives precede moral predicates, justice precedes property, systemic utility precedes approval, and legal decision completes rather than discovers natural determinacy.","Explanation proceeds by reversing presumed dependencies: motives precede moral predicates, justice precedes property, systemic utility precedes approval, and legal decision completes rather than discovers natural determinacy."]],"CL_THN_08:ALT-B04":[["[Ontological / Temporal] Reality contains no object-inherent property; juridical relations emerge gradually, change through temporal and institutional mediation, and become integral only through rule-governed recognition.","Reality contains no object-inherent property; juridical relations emerge gradually, change through temporal and institutional mediation, and become integral only through rule-governed recognition."]],"CL_THN_08:ALT-B05":[["[Methodological / Performative] The system performs its thesis through successive elimination, inversion, differentiation, and forced closure: its method reproduces the passage from fluid natural materials to determinate artificial relations.","The system performs its thesis through successive elimination, inversion, differentiation, and forced closure: its method reproduces the passage from fluid natural materials to determinate artificial relations."]],"CL_THN_09:GA-01":[["[Persistent] Normative authority is generated within ordinary human nature: interest, pleasure, uneasiness, and sympathetically apprehended relations furnish its operative materials.","Normative authority is generated within ordinary human nature: interest, pleasure, uneasiness, and sympathetically apprehended relations furnish its operative materials."]],"CL_THN_09:GA-02":[["[Persistent] Human motivation is partial, variable, and passion-bound; neither rulers nor spectators occupy a naturally impartial or morally transformed position.","Human motivation is partial, variable, and passion-bound; neither rulers nor spectators occupy a naturally impartial or morally transformed position."]],"CL_THN_09:GA-03":[["[Persistent] Sympathy makes the effects of qualities on others available to spectators who possess no direct private interest in those effects.","Sympathy makes the effects of qualities on others available to spectators who possess no direct private interest in those effects."]],"CL_THN_09:GA-04":[["[Attractor] Shared moral order is produced by generalizing situated responses into stable rules, common standpoints, and publicly usable evaluative language.","Shared moral order is produced by generalizing situated responses into stable rules, common standpoints, and publicly usable evaluative language."]],"CL_THN_09:GA-05":[["[Persistent] The principal evaluative object is a durable tendency or function, not an isolated act, transient feeling, or accidental outcome.","The principal evaluative object is a durable tendency or function, not an isolated act, transient feeling, or accidental outcome."]],"CL_THN_09:GA-06":[["[Mutating] Interest and utility change scope across the cluster: they uniquely sanction political allegiance but constitute only part of the plural basis of moral approval.","Interest and utility change scope across the cluster: they uniquely sanction political allegiance but constitute only part of the plural basis of moral approval."]],"CL_THN_09:GA-07":[["[Mutating] Artifice does not create ultimate value; it coordinates natural limitations and interests into promises, government, justice, good-breeding, and stable moral discourse.","Artifice does not create ultimate value; it coordinates natural limitations and interests into promises, government, justice, good-breeding, and stable moral discourse."]],"CL_THN_09:GA-08":[["[Emergent] Generalized judgment acquires relative autonomy from its origin: it can preserve obligation beyond immediate interest and preserve esteem despite weak affection, distance, or bad fortune.","Generalized judgment acquires relative autonomy from its origin: it can preserve obligation beyond immediate interest and preserve esteem despite weak affection, distance, or bad fortune."]],"CL_THN_09:GA-09":[["[Emergent] A legitimate exception must itself be generalizable: repeated anti-functional conduct, not private injury or isolated failure, authorizes normative reversal.","A legitimate exception must itself be generalizable: repeated anti-functional conduct, not private injury or isolated failure, authorizes normative reversal."]],"CL_THN_09:GA-10":[["[Persistent] Corrected judgment, occurrent affection, moral language, and practical motivation remain distinct layers and need not converge.","Corrected judgment, occurrent affection, moral language, and practical motivation remain distinct layers and need not converge."]],"CL_THN_09:GA-11":[["[Terminal] Offices, capacities, passions, and dispositions acquire moral valence from their direction and relational effects; systematic reversal of function produces reclassification from virtue or authority into vice or enmity.","Offices, capacities, passions, and dispositions acquire moral valence from their direction and relational effects; systematic reversal of function produces reclassification from virtue or authority into vice or enmity."]],"CL_THN_09:GA-12":[["[Attractor] The cluster converges on a conditionally ordered relational field: character is judged across its roles and government by its protective function, while no single utility calculus governs every moral source.","The cluster converges on a conditionally ordered relational field: character is judged across its roles and government by its protective function, while no single utility calculus governs every moral source."]],"CL_THN_09:RMD-01":[["[Stable identity] Sympathy retains its function as affective transmission: another’s pleasures and pains become spectator sentiments capable of grounding approval, affection, blame, and hatred.","Sympathy retains its function as affective transmission: another’s pleasures and pains become spectator sentiments capable of grounding approval, affection, blame, and hatred."]],"CL_THN_09:RMD-02":[["[Mutation] Interest moves from the cause of convention and exclusive sanction of allegiance to one evaluative relation among usefulness, immediate agreeableness, self-regard, and regard for others.","Interest moves from the cause of convention and exclusive sanction of allegiance to one evaluative relation among usefulness, immediate agreeableness, self-regard, and regard for others."]],"CL_THN_09:RMD-03":[["[Functional recurrence] The general point of view, common standard, general moral rule, and general opinion perform homologous work: they convert situated responses into socially stable verdicts.","The general point of view, common standard, general moral rule, and general opinion perform homologous work: they convert situated responses into socially stable verdicts."]],"CL_THN_09:RMD-04":[["[Reversal] Generalization first stabilizes allegiance and moral language, then becomes the mechanism by which recurrent abuses establish an exception to obedience.","Generalization first stabilizes allegiance and moral language, then becomes the mechanism by which recurrent abuses establish an exception to obedience."]],"CL_THN_09:RMD-05":[["[Domain expansion] Natural tendency migrates from the evaluation of personal dispositions under bad fortune to the evaluation of government under repeated historical performance.","Natural tendency migrates from the evaluation of personal dispositions under bad fortune to the evaluation of government under repeated historical performance."]],"CL_THN_09:RMD-06":[["[Absorption] The natural/artificial distinction ceases to divide sources of moral authority and instead marks different scales and mechanisms of coordinated benefit.","The natural/artificial distinction ceases to divide sources of moral authority and instead marks different scales and mechanisms of coordinated benefit."]],"CL_THN_09:RMD-07":[["[Escalation] Neutral capacities become morally charged through direction: benevolence makes power useful, while ambition or cruelty converts capacity and office into magnified harm.","Neutral capacities become morally charged through direction: benevolence makes power useful, while ambition or cruelty converts capacity and office into magnified harm."]],"CL_THN_09:RMD-08":[["[Disappearance after structural work] Promise, custom, and imitation disappear as original grounds once they have exposed the need for a prior interest capable of generating and transmitting allegiance.","Promise, custom, and imitation disappear as original grounds once they have exposed the need for a prior interest capable of generating and transmitting allegiance."]],"CL_THN_09:RMD-09":[["[Absorption after diagnostic use] Pride, tenderness, modesty, and heroic elevation remain local test cases, but their higher-order result is retained as evaluative pluralism and the separation of inward merit from social presentation.","Pride, tenderness, modesty, and heroic elevation remain local test cases, but their higher-order result is retained as evaluative pluralism and the separation of inward merit from social presentation."]],"CL_THN_09:RMD-10":[["[Mutation] Negative passion moves from constitutionally fitting anger to moral blame and, under public, recurrent, and severe injury, to resistance against tyrannical power.","Negative passion moves from constitutionally fitting anger to moral blame and, under public, recurrent, and severe injury, to resistance against tyrannical power."]],"CL_THN_09:CGD-01":[["[Local] The regress from promise through convention to interest is specific machinery for dismantling contractual allegiance; its scalable result is the dependence of artificial norms on prior human interests.","The regress from promise through convention to interest is specific machinery for dismantling contractual allegiance; its scalable result is the dependence of artificial norms on prior human interests."]],"CL_THN_09:CGD-02":[["[Local] The detailed mechanics of pride, comparison, heroic elevation, and conventional modesty remain a stress test of the four-source moral system rather than a global account of political authority.","The detailed mechanics of pride, comparison, heroic elevation, and conventional modesty remain a stress test of the four-source moral system rather than a global account of political authority."]],"CL_THN_09:CGD-03":[["[Local] Tenderness and qualified anger establish the dual sources and degree-sensitivity of benevolent merit but do not independently determine the limits of allegiance.","Tenderness and qualified anger establish the dual sources and degree-sensitivity of benevolent merit but do not independently determine the limits of allegiance."]],"CL_THN_09:CGD-04":[["[Scales upward] Correction for distance, private position, current disposition, and fortune becomes the cluster-wide mechanism for separating stable judgment from immediate affect.","Correction for distance, private position, current disposition, and fortune becomes the cluster-wide mechanism for separating stable judgment from immediate affect."]],"CL_THN_09:CGD-05":[["[Scales upward] Evaluation by durable tendency scales from personal character to institutional function and supplies the shared grammar of virtue, vice, legitimacy, and tyranny.","Evaluation by durable tendency scales from personal character to institutional function and supplies the shared grammar of virtue, vice, legitimacy, and tyranny."]],"CL_THN_09:CGD-06":[["[Bridge] Artificial justice and government are coordinated schemes whose moral standing depends on general benefit rather than the independent value of every isolated act.","Artificial justice and government are coordinated schemes whose moral standing depends on general benefit rather than the independent value of every isolated act."]],"CL_THN_09:CGD-07":[["[Catalyst] The distinction between originating cause and persisting moral rule forces the transition from simple causal genealogy to a temporal account of normative inertia and correction.","The distinction between originating cause and persisting moral rule forces the transition from simple causal genealogy to a temporal account of normative inertia and correction."]],"CL_THN_09:CGD-08":[["[Superseded] Utility monism, raw sympathetic intensity, isolated outcome evaluation, and absolute allegiance are jointly replaced by plural sources, corrected judgment, dispositional appraisal, and conditional authority.","Utility monism, raw sympathetic intensity, isolated outcome evaluation, and absolute allegiance are jointly replaced by plural sources, corrected judgment, dispositional appraisal, and conditional authority."]],"MC_THN_L1_01:GA-01":[["[Attractor] A science of human nature must reconstruct the perceptual medium through which evidence, inference, belief, and every other science operate.","A science of human nature must reconstruct the perceptual medium through which evidence, inference, belief, and every other science operate."]],"MC_THN_L1_01:GA-02":[["[Persistent] Legitimate inquiry proceeds from experienced perceptions, operations, relations, and effects rather than from speculative access to mental or external essence.","Legitimate inquiry proceeds from experienced perceptions, operations, relations, and effects rather than from speculative access to mental or external essence."]],"MC_THN_L1_01:GA-03":[["[Persistent] Simple ideational content is asymmetrically dependent on antecedent impression-material, even when later ideas become causally productive.","Simple ideational content is asymmetrically dependent on antecedent impression-material, even when later ideas become causally productive."]],"MC_THN_L1_01:GA-04":[["[Emergent] Provenance, arrangement, and force constitute distinct explanatory coordinates: what an idea contains, how it is ordered, and how efficaciously it is conceived cannot be reduced to one another.","Provenance, arrangement, and force constitute distinct explanatory coordinates: what an idea contains, how it is ordered, and how efficaciously it is conceived cannot be reduced to one another."]],"MC_THN_L1_01:GA-05":[["[Mutating] The idea is first a derivative copy, then a recombinable component, an associative node, and finally a force-bearing mediator of belief, passion, and action.","The idea is first a derivative copy, then a recombinable component, an associative node, and finally a force-bearing mediator of belief, passion, and action."]],"MC_THN_L1_01:GA-06":[["[Attractor] Mental production is asymmetrically recursive: sensory grounding remains one-way, while downstream perceptions repeatedly exchange the roles of effect, antecedent, and regulator.","Mental production is asymmetrically recursive: sensory grounding remains one-way, while downstream perceptions repeatedly exchange the roles of effect, antecedent, and regulator."]],"MC_THN_L1_01:GA-07":[["[Emergent] Novelty is relational and intensive rather than elemental: new complexes, abstractions, expectations, and reality-effects arise without unprecedented simple content.","Novelty is relational and intensive rather than elemental: new complexes, abstractions, expectations, and reality-effects arise without unprecedented simple content."]],"MC_THN_L1_01:GA-08":[["[Mutating] Order changes from a preserved feature of experience into a manipulable arrangement, an associative pathway, and the constitutive form of spatial and temporal appearance.","Order changes from a preserved feature of experience into a manipulable arrangement, an associative pathway, and the constitutive form of spatial and temporal appearance."]],"MC_THN_L1_01:GA-09":[["[Emergent] Stable mental regularity is generated by associative tendency and custom, which constrain transitions without imposing demonstrative necessity or abolishing imaginative variation.","Stable mental regularity is generated by associative tendency and custom, which constrain transitions without imposing demonstrative necessity or abolishing imaginative variation."]],"MC_THN_L1_01:GA-10":[["[Persistent] Space and time are content-bearing orders of coexistence and succession, not independent impressions or empty containers.","Space and time are content-bearing orders of coexistence and succession, not independent impressions or empty containers."]],"MC_THN_L1_01:GA-11":[["[Emergent] Existence contributes no additional represented quality; factuality must therefore be generated through a difference in the manner and force of conception.","Existence contributes no additional represented quality; factuality must therefore be generated through a difference in the manner and force of conception."]],"MC_THN_L1_01:GA-12":[["[Mutating] Force and vivacity develop from taxonomic marks into transmissible causal quantities, then into regulated quantities whose epistemic status depends on pedigree and steadiness.","Force and vivacity develop from taxonomic marks into transmissible causal quantities, then into regulated quantities whose epistemic status depends on pedigree and steadiness."]],"MC_THN_L1_01:GA-13":[["[Emergent] A present impression anchors inference, supplies transferable vivacity, and gives absent or future objects current motivational efficacy.","A present impression anchors inference, supplies transferable vivacity, and gives absent or future objects current motivational efficacy."]],"MC_THN_L1_01:GA-14":[["[Attractor] Practical reality is stable, regulated presence within the perception-system: an idea becomes real for the mind insofar as it persistently governs inference, passion, expectation, and conduct.","Practical reality is stable, regulated presence within the perception-system: an idea becomes real for the mind insofar as it persistently governs inference, passion, expectation, and conduct."]],"MC_THN_L1_01:GA-15":[["[Emergent] Epistemic legitimacy is genealogical and second-order: it requires admissible content, permissible relational application, and a force-producing history capable of surviving correction.","Epistemic legitimacy is genealogical and second-order: it requires admissible content, permissible relational application, and a force-producing history capable of surviving correction."]],"MC_THN_L1_01:GA-16":[["[Terminal] Explanation terminates at maximally general experienced relations while sensory origins, associative attraction, external actuality, and the final authority of corrective rules remain undisclosed.","Explanation terminates at maximally general experienced relations while sensory origins, associative attraction, external actuality, and the final authority of corrective rules remain undisclosed."]],"MC_THN_L1_01:RMD-01":[["[Stable identity] Experience remains the admissible field from the initial science of human nature through compositional analysis and the genealogy of factual assent.","Experience remains the admissible field from the initial science of human nature through compositional analysis and the genealogy of factual assent."]],"MC_THN_L1_01:RMD-02":[["[Functional recurrence] Observation mutates into perceptual classification, source-audit, compositional decomposition, tracking of associative effects, and diagnosis of force-producing pedigrees.","Observation mutates into perceptual classification, source-audit, compositional decomposition, tracking of associative effects, and diagnosis of force-producing pedigrees."]],"MC_THN_L1_01:RMD-03":[["[Escalation] The copy principle moves from a claim about simple ideas to a general constraint on imagination, abstraction, spatiotemporal predication, and existential representation.","The copy principle moves from a claim about simple ideas to a general constraint on imagination, abstraction, spatiotemporal predication, and existential representation."]],"MC_THN_L1_01:RMD-04":[["[Mutation] The idea changes from faint effect into reflective cause, recombinable component, associated transition-node, and practically efficacious object of belief.","The idea changes from faint effect into reflective cause, recombinable component, associated transition-node, and practically efficacious object of belief."]],"MC_THN_L1_01:RMD-05":[["[Mutation] Order changes from a standard of mnemonic fidelity into the common machinery of recombination, association, extension, duration, and customary expectation.","Order changes from a standard of mnemonic fidelity into the common machinery of recombination, association, extension, duration, and customary expectation."]],"MC_THN_L1_01:RMD-06":[["[Domain migration] Association moves from a gentle relation among freely recombinable ideas into the customary mechanism that selects factual alternatives and transmits vivacity.","Association moves from a gentle relation among freely recombinable ideas into the customary mechanism that selects factual alternatives and transmits vivacity."]],"MC_THN_L1_01:RMD-07":[["[Escalation and reversal] Vivacity progresses from perception-classification and mnemonic discrimination to belief-production, then reverses when poetry, passion, and madness show that intensity cannot warrant itself.","Vivacity progresses from perception-classification and mnemonic discrimination to belief-production, then reverses when poetry, passion, and madness show that intensity cannot warrant itself."]],"MC_THN_L1_01:RMD-08":[["[Absorption] Existence disappears as an independent content-question after its non-addition becomes the constraint forcing factual difference into modal and causal explanation.","Existence disappears as an independent content-question after its non-addition becomes the constraint forcing factual difference into modal and causal explanation."]],"MC_THN_L1_01:RMD-09":[["[Reversal] Separability first authorizes imaginative liberty, then becomes a negative test excluding empty space, bare time, and other structures detached from every positive content.","Separability first authorizes imaginative liberty, then becomes a negative test excluding empty space, bare time, and other structures detached from every positive content."]],"MC_THN_L1_01:RMD-10":[["[Escalation] Causation migrates from temporal dependence and ideational association to productive capacity, social authority, force transmission, and the regulation of belief.","Causation migrates from temporal dependence and ideational association to productive capacity, social authority, force transmission, and the regulation of belief."]],"MC_THN_L1_01:RMD-11":[["[Terminal transformation] Ignorance changes from a disciplinary deficiency into a constitutive boundary permitting operational explanation without essential, causal, or metaphysical completion.","Ignorance changes from a disciplinary deficiency into a constitutive boundary permitting operational explanation without essential, causal, or metaphysical completion."]],"MC_THN_L1_01:RMD-12":[["[Disappearance through absorption] Separate faculty names lose final explanatory status as memory, imagination, judgment, passion, and volition become differentiated operations within one distributed perception-system.","Separate faculty names lose final explanatory status as memory, imagination, judgment, passion, and volition become differentiated operations within one distributed perception-system."]],"MC_THN_L1_01:CGD-01":[["[Local] The initial diagnosis of philosophical controversy motivates the metascientific project but does not govern the later machinery of order, association, and belief.","The initial diagnosis of philosophical controversy motivates the metascientific project but does not govern the later machinery of order, association, and belief."]],"MC_THN_L1_01:CGD-02":[["[Local] The missing shade remains an exception to strict copy-priority rather than an alternative source of the current-level architecture.","The missing shade remains an exception to strict copy-priority rather than an alternative source of the current-level architecture."]],"MC_THN_L1_01:CGD-03":[["[Local] Exact mnemonic vivacity, the sensory source of extension, and content-filled minima remain local criteria whose broader function is only to constrain unconstrained separation.","Exact mnemonic vivacity, the sensory source of extension, and content-filled minima remain local criteria whose broader function is only to constrain unconstrained separation."]],"MC_THN_L1_01:CGD-04":[["[Local] The exhaustiveness of the three associative relations and the extension of causation into social subordination are domain-specific claims, not universal axioms of the whole meta-cluster.","The exhaustiveness of the three associative relations and the extension of causation into social subordination are domain-specific claims, not universal axioms of the whole meta-cluster."]],"MC_THN_L1_01:CGD-05":[["[Scales upward] The prohibition on essence-first explanation becomes the common boundary governing perceptions, faculties, space, time, existence, belief, and reality.","The prohibition on essence-first explanation becomes the common boundary governing perceptions, faculties, space, time, existence, belief, and reality."]],"MC_THN_L1_01:CGD-06":[["[Scales upward] The copy principle becomes a general genealogy of admissible content, while the distinction between content and operation prevents genealogy from collapsing into passive replay.","The copy principle becomes a general genealogy of admissible content, while the distinction between content and operation prevents genealogy from collapsing into passive replay."]],"MC_THN_L1_01:CGD-07":[["[Bridge] Ideas connect sensory derivation to reflection, memory, recombination, association, factual belief, and practical action.","Ideas connect sensory derivation to reflection, memory, recombination, association, factual belief, and practical action."]],"MC_THN_L1_01:CGD-08":[["[Bridge] Association and custom connect relational order to intensive actuality by converting recurrent transitions into channels of transferred vivacity.","Association and custom connect relational order to intensive actuality by converting recurrent transitions into channels of transferred vivacity."]],"MC_THN_L1_01:CGD-09":[["[Catalyst] Poetry, eloquence, passion, and madness are local cases that scale only as stress tests forcing belief to mutate from raw vividness into regulated intensity.","Poetry, eloquence, passion, and madness are local cases that scale only as stress tests forcing belief to mutate from raw vividness into regulated intensity."]],"MC_THN_L1_01:CGD-10":[["[Superseded and recoded] Linear copy chronology, passive receptivity, sealed faculties, empty forms, and intrinsic actuality-markers are replaced by asymmetrical recursion, relational organization, and second-order genealogy.","Linear copy chronology, passive receptivity, sealed faculties, empty forms, and intrinsic actuality-markers are replaced by asymmetrical recursion, relational organization, and second-order genealogy."]],"MC_THN_L1_01:ALT-B01":[["[Surface] The explicit field comprises human nature, impressions, ideas, memory, imagination, association, space, time, existence, belief, passion, fiction, and factual judgment.","The explicit field comprises human nature, impressions, ideas, memory, imagination, association, space, time, existence, belief, passion, fiction, and factual judgment."]],"MC_THN_L1_01:ALT-B02":[["[Structural] Copying, recurrence, separation, recombination, associative routing, ordered coexistence and succession, force-transfer, affective feedback, and correction form one distributed mechanism.","Copying, recurrence, separation, recombination, associative routing, ordered coexistence and succession, force-transfer, affective feedback, and correction form one distributed mechanism."]],"MC_THN_L1_01:ALT-B03":[["[Metastrategic] Metaphysical disputes are converted into audits of perceptual origin, relational operation, permissible application, causal pedigree, and susceptibility to correction.","Metaphysical disputes are converted into audits of perceptual origin, relational operation, permissible application, causal pedigree, and susceptibility to correction."]],"MC_THN_L1_01:ALT-B04":[["[Ontological / Temporal] Reality available to thought consists of content-bearing events and configurations; time is generated succession recursively reorganized by memory, custom, expectation, and present practical force.","Reality available to thought consists of content-bearing events and configurations; time is generated succession recursively reorganized by memory, custom, expectation, and present practical force."]],"MC_THN_L1_01:ALT-B05":[["[Methodological / Performative] The system performs its claims by decomposing apparent unities, denying unsupported additions, reconstructing operational relations, testing them against anomalies, and replacing universality with qualified recursive regulation.","The system performs its claims by decomposing apparent unities, denying unsupported additions, reconstructing operational relations, testing them against anomalies, and replacing universality with qualified recursive regulation."]],"MC_THN_L1_02:GA-01":[["[Persistent] Legitimate explanation begins from perceptions, affects, experienced conjunctions, and observable transformations rather than from unknown substances or intrinsic productive powers.","Legitimate explanation begins from perceptions, affects, experienced conjunctions, and observable transformations rather than from unknown substances or intrinsic productive powers."]],"MC_THN_L1_02:GA-02":[["[Persistent] Relation is causally effective only through the transitions it facilitates, preserves, interrupts, or redirects; it is not an inert predicate or an intrinsically binding nexus.","Relation is causally effective only through the transitions it facilitates, preserves, interrupts, or redirects; it is not an inert predicate or an intrinsically binding nexus."]],"MC_THN_L1_02:GA-03":[["[Mutating] Force and vivacity migrate from determinants of conviction into the general currency by which cognitive, affective, and social representations become operative.","Force and vivacity migrate from determinants of conviction into the general currency by which cognitive, affective, and social representations become operative."]],"MC_THN_L1_02:GA-04":[["[Persistent] Repetition, habit, and custom stabilize transitions without converting psychological regularity, practical necessity, or social circulation into truth.","Repetition, habit, and custom stabilize transitions without converting psychological regularity, practical necessity, or social circulation into truth."]],"MC_THN_L1_02:GA-05":[["[Attractor] Imagination is the indispensable medium of synthesis and the endogenous source of fictive completion, overextension, constructed sentiment, and self-confirming error.","Imagination is the indispensable medium of synthesis and the endogenous source of fictive completion, overextension, constructed sentiment, and self-confirming error."]],"MC_THN_L1_02:GA-06":[["[Mutating] Comparison changes from controlled experimental differentiation into affective opposition, retaining the common operation of preserving difference while reversing its epistemic function.","Comparison changes from controlled experimental differentiation into affective opposition, retaining the common operation of preserving difference while reversing its epistemic function."]],"MC_THN_L1_02:GA-07":[["[Mutating] Causation expands from regular conjunction among discriminated circumstances into gated conversion and recursive feedback in which effects alter subsequent causes, judgments, and relations.","Causation expands from regular conjunction among discriminated circumstances into gated conversion and recursive feedback in which effects alter subsequent causes, judgments, and relations."]],"MC_THN_L1_02:GA-08":[["[Emergent] Anomalies and contradictions reveal unrestricted principles by their excesses and force their conversion into range-bound, threshold-dependent mechanisms.","Anomalies and contradictions reveal unrestricted principles by their excesses and force their conversion into range-bound, threshold-dependent mechanisms."]],"MC_THN_L1_02:GA-09":[["[Attractor] Normative correction is immanent: broader comparison, discriminating variation, skeptical restraint, and recursive audit regulate the same natural operations that generate error.","Normative correction is immanent: broader comparison, discriminating variation, skeptical restraint, and recursive audit regulate the same natural operations that generate error."]],"MC_THN_L1_02:GA-10":[["[Mutating] The self has no warranted status as a substantial origin but remains operative as a vivid relay, represented object, temporal comparator, and socially altered magnitude.","The self has no warranted status as a substantial origin but remains operative as a vivid relay, represented object, temporal comparator, and socially altered magnitude."]],"MC_THN_L1_02:GA-11":[["[Persistent] Natural production and felt efficacy do not establish representational truth, epistemic warrant, intrinsic value, or source-fidelity.","Natural production and felt efficacy do not establish representational truth, epistemic warrant, intrinsic value, or source-fidelity."]],"MC_THN_L1_02:GA-12":[["[Emergent] Social value is generated in circulation: transmitted satisfaction, reflected judgment, comparative opposition, and recursive uptake constitute rank and self-estimation.","Social value is generated in circulation: transmitted satisfaction, reflected judgment, comparative opposition, and recursive uptake constitute rank and self-estimation."]],"MC_THN_L1_02:GA-13":[["[Emergent] Relational proximity and intensity possess no intrinsic valence; they amplify whichever epistemic, sympathetic, or comparative transformation controls the route.","Relational proximity and intensity possess no intrinsic valence; they amplify whichever epistemic, sympathetic, or comparative transformation controls the route."]],"MC_THN_L1_02:GA-14":[["[Emergent] Time is an active operator of projection, attenuation, retention, durable attribution, and feedback rather than a neutral container for stable objects and subjects.","Time is an active operator of projection, attenuation, retention, durable attribution, and feedback rather than a neutral container for stable objects and subjects."]],"MC_THN_L1_02:GA-15":[["[Terminal] The viable endpoint is a reflexive science of human nature that preserves empirically useful causal and affective mechanisms under permanent semantic, experimental, skeptical, and relational correction.","The viable endpoint is a reflexive science of human nature that preserves empirically useful causal and affective mechanisms under permanent semantic, experimental, skeptical, and relational correction."]],"MC_THN_L1_02:RMD-01":[["[Stable Identity] Experienced conjunction remains the minimum causal input, although its output expands from expectation to bodily influence, affective conversion, and social feedback.","Experienced conjunction remains the minimum causal input, although its output expands from expectation to bodily influence, affective conversion, and social feedback."]],"MC_THN_L1_02:RMD-02":[["[Escalation] Vivacity moves from explaining unequal conviction to animating belief and passion, then becomes the transmissible currency of a social-affective network.","Vivacity moves from explaining unequal conviction to animating belief and passion, then becomes the transmissible currency of a social-affective network."]],"MC_THN_L1_02:RMD-03":[["[Mutation] Imagination changes from a producer of causal expectation and fictive object-unity into the general medium of cognition, then into a simulator capable of constructing another’s absent emotion.","Imagination changes from a producer of causal expectation and fictive object-unity into the general medium of cognition, then into a simulator capable of constructing another’s absent emotion."]],"MC_THN_L1_02:RMD-04":[["[Functional Recurrence] Custom recurs as first-order projection, second-order regulation, affective stabilization, and constructive expectation, with renewed overextension at every phase.","Custom recurs as first-order projection, second-order regulation, affective stabilization, and constructive expectation, with renewed overextension at every phase."]],"MC_THN_L1_02:RMD-05":[["[Reversal] Comparison changes from a corrective instrument that exposes suppressed differences into a social operator that preserves difference as inverse self-estimation.","Comparison changes from a corrective instrument that exposes suppressed differences into a social operator that preserves difference as inverse self-estimation."]],"MC_THN_L1_02:RMD-06":[["[Migration] Relation migrates from conjunction, separability, and spatial compatibility into cognitive gating, self-reference, social proximity, directed transmission, and comparative interaction.","Relation migrates from conjunction, separability, and spatial compatibility into cognitive gating, self-reference, social proximity, directed transmission, and comparative interaction."]],"MC_THN_L1_02:RMD-07":[["[Terminal Transformation] The self moves from an absent invariant bearer to an operational object and finally to a socially constituted relay-comparator whose states are generated through feedback.","The self moves from an absent invariant bearer to an operational object and finally to a socially constituted relay-comparator whose states are generated through feedback."]],"MC_THN_L1_02:RMD-08":[["[Escalation] Cause shifts from whole-object identity to operative circumstance, then to domain-specific conversion, and finally to nonlinear circuits in which generated passions modify their own conditions.","Cause shifts from whole-object identity to operative circumstance, then to domain-specific conversion, and finally to nonlinear circuits in which generated passions modify their own conditions."]],"MC_THN_L1_02:RMD-09":[["[Mutation] Contradiction changes from a stimulus for metaphysical repair into a diagnostic of unrestricted transition and then into a controlled anomaly for reconstructing social-affective routing.","Contradiction changes from a stimulus for metaphysical repair into a diagnostic of unrestricted transition and then into a controlled anomaly for reconstructing social-affective routing."]],"MC_THN_L1_02:RMD-10":[["[Disappearance] Substance, autonomous reason, intrinsic value, primitive social instinct, and sovereign selfhood disappear after their explanatory work is redistributed across relation, force, custom, comparison, and feedback.","Substance, autonomous reason, intrinsic value, primitive social instinct, and sovereign selfhood disappear after their explanatory work is redistributed across relation, force, custom, comparison, and feedback."]],"MC_THN_L1_02:CGD-01":[["[Lower-Layer Local] Particular rules for isolating causal circumstances remain local experimental instruments; their scalable function is recursive differentiation under counterinstance.","Particular rules for isolating causal circumstances remain local experimental instruments; their scalable function is recursive differentiation under counterinstance."]],"MC_THN_L1_02:CGD-02":[["[Lower-Layer Local] Spatial compatibility, soul-substance, immortality, and the exact gates of pride and humility remain local problems rather than current-level explanatory centers.","Spatial compatibility, soul-substance, immortality, and the exact gates of pride and humility remain local problems rather than current-level explanatory centers."]],"MC_THN_L1_02:CGD-03":[["[Lower-Layer Local] Fame, wealth-esteem, pity, envy, malice, and the constitutional conjunctions of love or hatred remain local outputs of the broader relational machine.","Fame, wealth-esteem, pity, envy, malice, and the constitutional conjunctions of love or hatred remain local outputs of the broader relational machine."]],"MC_THN_L1_02:CGD-04":[["[Scaled] Relation-mediated force scales upward as the common architecture connecting belief, causal inference, affective conversion, and social valuation.","Relation-mediated force scales upward as the common architecture connecting belief, causal inference, affective conversion, and social valuation."]],"MC_THN_L1_02:CGD-05":[["[Bridge] Experimental circumstance-analysis and affective threshold-gating jointly establish that causal mechanisms are individuated by controlled differences in routing, not by whole-object classification.","Experimental circumstance-analysis and affective threshold-gating jointly establish that causal mechanisms are individuated by controlled differences in routing, not by whole-object classification."]],"MC_THN_L1_02:CGD-06":[["[Bridge] The operational self of the skeptical and affective analyses becomes the relay-comparator required by social transmission and reflected valuation.","The operational self of the skeptical and affective analyses becomes the relay-comparator required by social transmission and reflected valuation."]],"MC_THN_L1_02:CGD-07":[["[Catalyst] Social anomalies demonstrate that unchanged content or objective condition can generate opposed effects, forcing causation to include sequence, topology, retention, and mode selection.","Social anomalies demonstrate that unchanged content or objective condition can generate opposed effects, forcing causation to include sequence, topology, retention, and mode selection."]],"MC_THN_L1_02:CGD-08":[["[Recoded] Causal identity is recoded from an intrinsic power or whole object into a reproducible transformation distributed across input, relation, force, gate, and feedback.","Causal identity is recoded from an intrinsic power or whole object into a reproducible transformation distributed across input, relation, force, gate, and feedback."]],"MC_THN_L1_02:CGD-09":[["[Current-Level Emergent] Philosophy becomes a reflexive regulation of cognitive and social-affective machinery rather than a separate faculty judging nature from outside.","Philosophy becomes a reflexive regulation of cognitive and social-affective machinery rather than a separate faculty judging nature from outside."]],"MC_THN_L1_03:GA-01":[["[Persistent] Pleasure, pain, interest, uneasiness, sympathy, and acquired concern are the indispensable materials from which social and normative order must be generated.","Pleasure, pain, interest, uneasiness, sympathy, and acquired concern are the indispensable materials from which social and normative order must be generated."]],"MC_THN_L1_03:GA-02":[["[Attractor] Affective, juridical, and moral value is relationally constituted: objects, goods, persons, dispositions, and offices acquire force or status through mediated relations rather than intrinsic properties alone.","Affective, juridical, and moral value is relationally constituted: objects, goods, persons, dispositions, and offices acquire force or status through mediated relations rather than intrinsic properties alone."]],"MC_THN_L1_03:GA-03":[["[Persistent] Present force and authority are path-dependent effects of prior encounters, repeated conduct, stabilized expectations, institutional history, and accumulated evaluations.","Present force and authority are path-dependent effects of prior encounters, repeated conduct, stabilized expectations, institutional history, and accumulated evaluations."]],"MC_THN_L1_03:GA-04":[["[Mutating] Partiality is both destabilizing material and generative resource: immediate passion produces conflict, while reflected, coordinated, and generalized partiality produces durable order.","Partiality is both destabilizing material and generative resource: immediate passion produces conflict, while reflected, coordinated, and generalized partiality produces durable order."]],"MC_THN_L1_03:GA-05":[["[Mutating] Reflection is not a sovereign source of value; it changes the scale, temporal horizon, and organization of passions already in operation.","Reflection is not a sovereign source of value; it changes the scale, temporal horizon, and organization of passions already in operation."]],"MC_THN_L1_03:GA-06":[["[Persistent] A generated category cannot explain its own genesis: acquired ends cannot presuppose antecedent concern, justice cannot presuppose property, and allegiance cannot presuppose contractual obligation.","A generated category cannot explain its own genesis: acquired ends cannot presuppose antecedent concern, justice cannot presuppose property, and allegiance cannot presuppose contractual obligation."]],"MC_THN_L1_03:GA-07":[["[Attractor] Artifice is necessary without being arbitrary when durable natural limitations require second-order coordination but do not independently determine the form of that coordination.","Artifice is necessary without being arbitrary when durable natural limitations require second-order coordination but do not independently determine the form of that coordination."]],"MC_THN_L1_03:GA-08":[["[Persistent] Convention begins as mutually legible, conditionally reciprocal conduct whose repetition stabilizes expectation before explicit moral obligation or authoritative command.","Convention begins as mutually legible, conditionally reciprocal conduct whose repetition stabilizes expectation before explicit moral obligation or authoritative command."]],"MC_THN_L1_03:GA-09":[["[Terminal] Institutions constitute normative objects: stabilized possession becomes property, coordinated benefit becomes justice, and protective function becomes political authority only within rule-governed relations.","Institutions constitute normative objects: stabilized possession becomes property, coordinated benefit becomes justice, and protective function becomes political authority only within rule-governed relations."]],"MC_THN_L1_03:GA-10":[["[Emergent] Integral rights and stable verdicts require imposed closure because their affective, possessory, utilitarian, and relational grounds remain gradual, conflicting, and underdeterminate.","Integral rights and stable verdicts require imposed closure because their affective, possessory, utilitarian, and relational grounds remain gradual, conflicting, and underdeterminate."]],"MC_THN_L1_03:GA-11":[["[Mutating] Utility changes function across the architecture: it motivates coordination, necessitates institutions, sanctions rule-systems, and tests political authority, but does not uniquely determine every title or exhaust moral merit.","Utility changes function across the architecture: it motivates coordination, necessitates institutions, sanctions rule-systems, and tests political authority, but does not uniquely determine every title or exhaust moral merit."]],"MC_THN_L1_03:GA-12":[["[Mutating] Sympathy expands from affective transmission into institutional sanction and standpoint generalization, while never becoming universal benevolence or complete motivational impartiality.","Sympathy expands from affective transmission into institutional sanction and standpoint generalization, while never becoming universal benevolence or complete motivational impartiality."]],"MC_THN_L1_03:GA-13":[["[Attractor] Impartiality is manufactured by general rules, corrected standpoints, and invariant application rather than discovered in an originally impartial subject.","Impartiality is manufactured by general rules, corrected standpoints, and invariant application rather than discovered in an originally impartial subject."]],"MC_THN_L1_03:GA-14":[["[Persistent] Durable tendency, coordinated scheme, and relational function outrank isolated action, immediate consequence, and accidental outcome as objects of normative evaluation.","Durable tendency, coordinated scheme, and relational function outrank isolated action, immediate consequence, and accidental outcome as objects of normative evaluation."]],"MC_THN_L1_03:GA-15":[["[Emergent] Generated norms acquire relative autonomy: they can outlast their immediate motives, redirect later passions, and authorize judgments unavailable at the moment of their origin.","Generated norms acquire relative autonomy: they can outlast their immediate motives, redirect later passions, and authorize judgments unavailable at the moment of their origin."]],"MC_THN_L1_03:GA-16":[["[Terminal] Legitimate reversal must itself be generalized: accumulated, public, and recurrent anti-function—not isolated dislike or private injury—can terminate established authority.","Legitimate reversal must itself be generalized: accumulated, public, and recurrent anti-function—not isolated dislike or private injury—can terminate established authority."]],"MC_THN_L1_03:GA-17":[["[Terminal] The resulting order is endogenous, relational, plural, and conditionally stable; no single affective, legal, utilitarian, or moral mechanism completes every stage.","The resulting order is endogenous, relational, plural, and conditionally stable; no single affective, legal, utilitarian, or moral mechanism completes every stage."]],"MC_THN_L1_03:RMD-01":[["[Stable identity] Pleasure and pain remain the basic currency, but their function expands from direct affective modulation into support for inclination, institutional observance, moral approval, blame, and resistance.","Pleasure and pain remain the basic currency, but their function expands from direct affective modulation into support for inclination, institutional observance, moral approval, blame, and resistance."]],"MC_THN_L1_03:RMD-02":[["[Domain expansion] Relation moves from association and affective transfer to juridical attachment and finally to the evaluative field in which dispositions and institutions acquire moral identity.","Relation moves from association and affective transfer to juridical attachment and finally to the evaluative field in which dispositions and institutions acquire moral identity."]],"MC_THN_L1_03:RMD-03":[["[Functional recurrence] Repetition successively produces habit, reciprocal confidence, institutional sedimentation, stable moral language, and historical evidence of durable function or anti-function.","Repetition successively produces habit, reciprocal confidence, institutional sedimentation, stable moral language, and historical evidence of durable function or anti-function."]],"MC_THN_L1_03:RMD-04":[["[Mutation] Stability changes from affective relief into possessory security, juridical rigidity, normative inertia, and finally a condition vulnerable to reversal when it protects recurrent anti-function.","Stability changes from affective relief into possessory security, juridical rigidity, normative inertia, and finally a condition vulnerable to reversal when it protects recurrent anti-function."]],"MC_THN_L1_03:RMD-05":[["[Escalation] Sympathy begins as inter-organismic communication, becomes approval of public utility, and culminates in corrected moral judgment capable of evaluating strangers, institutions, and political effects.","Sympathy begins as inter-organismic communication, becomes approval of public utility, and culminates in corrected moral judgment capable of evaluating strangers, institutions, and political effects."]],"MC_THN_L1_03:RMD-06":[["[Mutation] Cognition shifts from an affective channel-selector into reflective interest, genealogical correction, and standpoint adjustment; its function is organizational rather than value-creating.","Cognition shifts from an affective channel-selector into reflective interest, genealogical correction, and standpoint adjustment; its function is organizational rather than value-creating."]],"MC_THN_L1_03:RMD-07":[["[Reversal] Self-interest changes from immediate acquisitive disruption into reciprocal restraint and then into allegiance to a system whose generalized rules can oppose immediate interest.","Self-interest changes from immediate acquisitive disruption into reciprocal restraint and then into allegiance to a system whose generalized rules can oppose immediate interest."]],"MC_THN_L1_03:RMD-08":[["[Mutation] Utility moves from an affectively mediated input to the necessity of settlement, then to institutional sanction, and finally to a functional criterion capable of withdrawing political authority.","Utility moves from an affectively mediated input to the necessity of settlement, then to institutional sanction, and finally to a functional criterion capable of withdrawing political authority."]],"MC_THN_L1_03:RMD-09":[["[Reversal] General rules first suppress local variability and preserve authority beyond immediate causes; recurrent public failure then produces a counter-rule that authorizes reclassification and resistance.","General rules first suppress local variability and preserve authority beyond immediate causes; recurrent public failure then produces a counter-rule that authorizes reclassification and resistance."]],"MC_THN_L1_03:RMD-10":[["[Absorption] The natural/artificial distinction is absorbed into a layered model in which natural affects and limitations supply materials while artificial coordination produces objects, rules, standpoints, and second-order dispositions.","The natural/artificial distinction is absorbed into a layered model in which natural affects and limitations supply materials while artificial coordination produces objects, rules, standpoints, and second-order dispositions."]],"MC_THN_L1_03:RMD-11":[["[Terminal transformation] Normative objects cease to appear antecedent to their relations: affective value, property, moral character, and political authority become stabilized outcomes of mediation, institution, and functional judgment.","Normative objects cease to appear antecedent to their relations: affective value, property, moral character, and political authority become stabilized outcomes of mediation, institution, and functional judgment."]],"MC_THN_L1_03:CGD-01":[["[Local] Species comparison, cognitive thresholds, excitatory bands, and the detailed mechanisms of curiosity remain affective diagnostics; their scalable result is the mediated and phase-sensitive constitution of motivation.","Species comparison, cognitive thresholds, excitatory bands, and the detailed mechanisms of curiosity remain affective diagnostics; their scalable result is the mediated and phase-sensitive constitution of motivation."]],"MC_THN_L1_03:CGD-02":[["[Local] Occupation, prescription, accession, succession, and municipal title rules remain juridical implementations; their scalable result is that gradual relations require socially imposed determinacy.","Occupation, prescription, accession, succession, and municipal title rules remain juridical implementations; their scalable result is that gradual relations require socially imposed determinacy."]],"MC_THN_L1_03:CGD-03":[["[Local] Pride, tenderness, anger, allegiance, and tyranny remain differentiated moral-political cases; their scalable result is evaluation by durable relational tendency and generalizable exception.","Pride, tenderness, anger, allegiance, and tyranny remain differentiated moral-political cases; their scalable result is evaluation by durable relational tendency and generalizable exception."]],"MC_THN_L1_03:CGD-04":[["[Scales upward] Affective mediation becomes the substrate of institutional genesis: passions can be redirected, transferred, and stabilized because they are not fixed responses to intrinsic object-values.","Affective mediation becomes the substrate of institutional genesis: passions can be redirected, transferred, and stabilized because they are not fixed responses to intrinsic object-values."]],"MC_THN_L1_03:CGD-05":[["[Scales upward] Path-dependence becomes sedimentary social ontology: repeated encounters create inclinations, repeated restraint creates convention, and repeated evaluation creates stable authority or evidence of anti-function.","Path-dependence becomes sedimentary social ontology: repeated encounters create inclinations, repeated restraint creates convention, and repeated evaluation creates stable authority or evidence of anti-function."]],"MC_THN_L1_03:CGD-06":[["[Bridge] Affective transfer and sympathy connect individual passion to public normativity by allowing generated force and perceived consequences to cross persons, practices, and institutions.","Affective transfer and sympathy connect individual passion to public normativity by allowing generated force and perceived consequences to cross persons, practices, and institutions."]],"MC_THN_L1_03:CGD-07":[["[Bridge] Relation and imagination connect affective association to juridical and moral object-construction: the same relational field joins ideas, persons, goods, duties, and evaluative roles.","Relation and imagination connect affective association to juridical and moral object-construction: the same relational field joins ideas, persons, goods, duties, and evaluative roles."]],"MC_THN_L1_03:CGD-08":[["[Catalyst] The possibility that conduct generates its later motive scales into the claim that observance can precede duty and that institutional authority can be retrospectively moralized.","The possibility that conduct generates its later motive scales into the claim that observance can precede duty and that institutional authority can be retrospectively moralized."]],"MC_THN_L1_03:CGD-09":[["[Recoded] Instinct, scarcity, limited benevolence, and shared affective constitution are retained not as complete explanations but as boundary conditions constraining what recursive construction can generate.","Instinct, scarcity, limited benevolence, and shared affective constitution are retained not as complete explanations but as boundary conditions constraining what recursive construction can generate."]],"MC_THN_L1_03:CGD-10":[["[Superseded] Intrinsic value, pre-social property, naturally impartial motivation, and absolute political title are replaced by mediated force, constituted relation, corrected judgment, and conditional function.","Intrinsic value, pre-social property, naturally impartial motivation, and absolute political title are replaced by mediated force, constituted relation, corrected judgment, and conditional function."]],"MC_THN_L1_03:ALT-B01":[["[Surface level] The explicit objects are affective variation, habit, curiosity, justice, possession, property, moral merit, political allegiance, tyranny, and resistance.","The explicit objects are affective variation, habit, curiosity, justice, possession, property, moral merit, political allegiance, tyranny, and resistance."]],"MC_THN_L1_03:ALT-B02":[["[Structural level] Mediation, transfer, repetition, reflected interest, reciprocal expectation, relation, imagination, general rules, sympathy, and functional testing form one recursive production system.","Mediation, transfer, repetition, reflected interest, reciprocal expectation, relation, imagination, general rules, sympathy, and functional testing form one recursive production system."]],"MC_THN_L1_03:ALT-B03":[["[Metastrategic level] Intervention requires diagnosing phase and scale: whether a force should be redirected, a relation stabilized, a boundary stipulated, a judgment corrected, or an institution reclassified under recurrent anti-function.","Intervention requires diagnosing phase and scale: whether a force should be redirected, a relation stabilized, a boundary stipulated, a judgment corrected, or an institution reclassified under recurrent anti-function."]],"MC_THN_L1_03:ALT-B04":[["[Ontological / Temporal level] Reality consists of historically accumulated relational configurations whose status can persist beyond immediate causes yet change through repeated performance and public reassessment.","Reality consists of historically accumulated relational configurations whose status can persist beyond immediate causes yet change through repeated performance and public reassessment."]],"MC_THN_L1_03:ALT-B05":[["[Methodological / Performative level] The architecture performs its thesis through differential variation, genealogical inversion, staged constitution, objection-driven correction, and terminal stress-testing of stabilized categories.","The architecture performs its thesis through differential variation, genealogical inversion, staged constitution, objection-driven correction, and terminal stress-testing of stabilized categories."]],"WB_THN:GA-01":[["[Attractor] Human nature is the medium within which evidence, reality, agency, value, and authority must be reconstructed and through which every reconstruction must itself operate.","Human nature is the medium within which evidence, reality, agency, value, and authority must be reconstructed and through which every reconstruction must itself operate."]],"WB_THN:GA-02":[["[Persistent] Legitimate explanation begins from perceptions, affects, experienced relations, observable operations, and recurrent effects rather than from inaccessible substances, essences, powers, or intrinsic values.","Legitimate explanation begins from perceptions, affects, experienced relations, observable operations, and recurrent effects rather than from inaccessible substances, essences, powers, or intrinsic values."]],"WB_THN:GA-03":[["[Persistent] The system produces no ex nihilo content, affective valence, or normative authority: higher-order novelty arises by reorganizing constrained perceptual, affective, natural, and social materials.","The system produces no ex nihilo content, affective valence, or normative authority: higher-order novelty arises by reorganizing constrained perceptual, affective, natural, and social materials."]],"WB_THN:GA-04":[["[Attractor] Relation is the trans-scalar operator that organizes perception, association, causation, self-reference, affective transmission, comparison, possession, duty, moral identity, and political function.","Relation is the trans-scalar operator that organizes perception, association, causation, self-reference, affective transmission, comparison, possession, duty, moral identity, and political function."]],"WB_THN:GA-05":[["[Mutating] Force develops from a difference among perceptions into transferable vivacity, affective activation, social efficacy, institutional adherence, and practical authority.","Force develops from a difference among perceptions into transferable vivacity, affective activation, social efficacy, institutional adherence, and practical authority."]],"WB_THN:GA-06":[["[Mutating] Repetition and custom move from stabilizing mental transitions to producing expectations, selves, social values, conventions, rights, moral inertia, and evidence for terminal reversal.","Repetition and custom move from stabilizing mental transitions to producing expectations, selves, social values, conventions, rights, moral inertia, and evidence for terminal reversal."]],"WB_THN:GA-07":[["[Attractor] Generated effects recursively become causes: ideas, beliefs, passions, reflected judgments, conventions, rules, and institutions return to reorganize subsequent perception, conduct, and relation.","Generated effects recursively become causes: ideas, beliefs, passions, reflected judgments, conventions, rules, and institutions return to reorganize subsequent perception, conduct, and relation."]],"WB_THN:GA-08":[["[Mutating] Imagination is both the productive medium of synthesis and the endogenous source of fictive completion, projected unity, social simulation, and institutionally mediated object-construction.","Imagination is both the productive medium of synthesis and the endogenous source of fictive completion, projected unity, social simulation, and institutionally mediated object-construction."]],"WB_THN:GA-09":[["[Emergent] Comparison is a branching operator: controlled variation can correct projection, retained contrast can produce rivalry, and generalized standpoint-comparison can stabilize public judgment.","Comparison is a branching operator: controlled variation can correct projection, retained contrast can produce rivalry, and generalized standpoint-comparison can stabilize public judgment."]],"WB_THN:GA-10":[["[Mutating] The self has no warranted status as a substantial origin but remains operationally indispensable as relay, temporal comparator, represented object, institutional participant, and recursive locus of attribution.","The self has no warranted status as a substantial origin but remains operationally indispensable as relay, temporal comparator, represented object, institutional participant, and recursive locus of attribution."]],"WB_THN:GA-11":[["[Emergent] Practical reality consists in stable relational efficacy: factual objects, social ranks, property, character, and authority become operative through regulated effects, expectations, classifications, and conduct.","Practical reality consists in stable relational efficacy: factual objects, social ranks, property, character, and authority become operative through regulated effects, expectations, classifications, and conduct."]],"WB_THN:GA-12":[["[Persistent] Natural production, subjective force, social circulation, and institutional stability do not by themselves establish truth, warrant, merit, justice, or legitimacy.","Natural production, subjective force, social circulation, and institutional stability do not by themselves establish truth, warrant, merit, justice, or legitimacy."]],"WB_THN:GA-13":[["[Attractor] Correction is immanent and recursive: source-audit, comparison, controlled variation, general rules, corrected standpoints, and functional reassessment regulate mechanisms from within the same system that generates error.","Correction is immanent and recursive: source-audit, comparison, controlled variation, general rules, corrected standpoints, and functional reassessment regulate mechanisms from within the same system that generates error."]],"WB_THN:GA-14":[["[Emergent] Time is constitutive and phase-changing: succession permits memory and projection, repetition creates disposition and authority, and accumulated performance can transform status rather than merely extend it.","Time is constitutive and phase-changing: succession permits memory and projection, repetition creates disposition and authority, and accumulated performance can transform status rather than merely extend it."]],"WB_THN:GA-15":[["[Emergent] Artifice is necessary without being arbitrary when natural constraints underdetermine the second-order forms required for stable coordination, judgment, and authority.","Artifice is necessary without being arbitrary when natural constraints underdetermine the second-order forms required for stable coordination, judgment, and authority."]],"WB_THN:GA-16":[["[Emergent] Agency is second-order navigation: intervention alters attention, association, comparison, circumstance, authority, expectation, rule, and institutional route rather than escaping the machinery of human nature.","Agency is second-order navigation: intervention alters attention, association, comparison, circumstance, authority, expectation, rule, and institutional route rather than escaping the machinery of human nature."]],"WB_THN:GA-17":[["[Terminal] The system closes as bounded recursive naturalism: explanatory operations are preserved, metaphysical foundations are withheld, determinate institutions remain revisable, and no stabilization is exempt from renewed audit.","The system closes as bounded recursive naturalism: explanatory operations are preserved, metaphysical foundations are withheld, determinate institutions remain revisable, and no stabilization is exempt from renewed audit."]],"WB_THN:RMD-01":[["[Stable identity] Experience remains the admissible field from perceptual genealogy through causal experiment, affective analysis, institutional genesis, and political reassessment.","Experience remains the admissible field from perceptual genealogy through causal experiment, affective analysis, institutional genesis, and political reassessment."]],"WB_THN:RMD-02":[["[Escalation] Genealogy expands from tracing ideational content to tracing conviction, self-attribution, social value, property, obligation, and political legitimacy.","Genealogy expands from tracing ideational content to tracing conviction, self-attribution, social value, property, obligation, and political legitimacy."]],"WB_THN:RMD-03":[["[Absorption] The idea begins as a derivative switching element and is progressively absorbed into the broader categories of representation, simulated condition, social classification, and constituted normative object.","The idea begins as a derivative switching element and is progressively absorbed into the broader categories of representation, simulated condition, social classification, and constituted normative object."]],"WB_THN:RMD-04":[["[Domain expansion] Relation moves from perceptual arrangement and association into causal routing, affective transmission, social topology, juridical attachment, and moral-political identity.","Relation moves from perceptual arrangement and association into causal routing, affective transmission, social topology, juridical attachment, and moral-political identity."]],"WB_THN:RMD-05":[["[Escalation] Force progresses from perceptual classification to belief-production, affective activation, social circulation, institutional observance, and practical authority.","Force progresses from perceptual classification to belief-production, affective activation, social circulation, institutional observance, and practical authority."]],"WB_THN:RMD-06":[["[Terminal transformation] Repetition changes from recurrence into custom, feedback, convention, second nature, normative inertia, and finally accumulated evidence capable of authorizing reversal.","Repetition changes from recurrence into custom, feedback, convention, second nature, normative inertia, and finally accumulated evidence capable of authorizing reversal."]],"WB_THN:RMD-07":[["[Mutation] Imagination changes from recombination and associative completion into factual projection, metaphysical fiction, constructive sympathy, and social object-production.","Imagination changes from recombination and associative completion into factual projection, metaphysical fiction, constructive sympathy, and social object-production."]],"WB_THN:RMD-08":[["[Reversal] Comparison begins as source-sensitive differentiation, reverses into affective opposition and self-estimation, and is recoded as corrected public standpoint.","Comparison begins as source-sensitive differentiation, reverses into affective opposition and self-estimation, and is recoded as corrected public standpoint."]],"WB_THN:RMD-09":[["[Escalation] Causation moves from perceptual dependence and customary transition to gated conversion, social feedback, institutional path-production, and historical reassessment.","Causation moves from perceptual dependence and customary transition to gated conversion, social feedback, institutional path-production, and historical reassessment."]],"WB_THN:RMD-10":[["[Mutation] Reality moves from regulated factual presence to socially productive representation and finally to historically stabilized juridical, moral, and political status.","Reality moves from regulated factual presence to socially productive representation and finally to historically stabilized juridical, moral, and political status."]],"WB_THN:RMD-11":[["[Terminal transformation] The subject changes from non-originating relay to temporal comparator, socially permeable self-reference, institutionally installed participant, and possible resister.","The subject changes from non-originating relay to temporal comparator, socially permeable self-reference, institutionally installed participant, and possible resister."]],"WB_THN:RMD-12":[["[Reversal] General rules first regulate conviction and suppress local variation, then produce stable public judgment, and finally become counter-rules capable of revising authority.","General rules first regulate conviction and suppress local variation, then produce stable public judgment, and finally become counter-rules capable of revising authority."]],"WB_THN:RMD-13":[["[Terminal transformation] Ignorance and skepticism cease to be merely privative: they become permanent controls that prohibit metaphysical completion while preserving operational inquiry and conditional authority.","Ignorance and skepticism cease to be merely privative: they become permanent controls that prohibit metaphysical completion while preserving operational inquiry and conditional authority."]],"WB_THN:RMD-14":[["[Disappearance] Substance, autonomous faculties, intrinsic powers, pre-social rights, and sovereign reason disappear after their explanatory functions are redistributed across materials, relations, force, repetition, gates, and institutions.","Substance, autonomous faculties, intrinsic powers, pre-social rights, and sovereign reason disappear after their explanatory functions are redistributed across materials, relations, force, repetition, gates, and institutions."]],"WB_THN:CGD-01":[["[Local] The missing shade, exact mnemonic fidelity, perceptual minima, and the sensory specifications of extension remain local tests of the early content-genealogy.","The missing shade, exact mnemonic fidelity, perceptual minima, and the sensory specifications of extension remain local tests of the early content-genealogy."]],"WB_THN:CGD-02":[["[Local] The exact inventory of associative relations, the detailed status of empty space and time, and particular classifications of fiction remain subordinate implementations of the de-additive architecture.","The exact inventory of associative relations, the detailed status of empty space and time, and particular classifications of fiction remain subordinate implementations of the de-additive architecture."]],"WB_THN:CGD-03":[["[Local] Particular experimental rules, questions of spatial compatibility, soul-substance, and the exact gates of pride and humility remain domain-specific instruments or targets.","Particular experimental rules, questions of spatial compatibility, soul-substance, and the exact gates of pride and humility remain domain-specific instruments or targets."]],"WB_THN:CGD-04":[["[Local] Named passions, title doctrines, legal modes of acquisition, and particular political cases remain local outputs of broader relational and institutional machinery.","Named passions, title doctrines, legal modes of acquisition, and particular political cases remain local outputs of broader relational and institutional machinery."]],"WB_THN:CGD-05":[["[Domain-bound] Utility scales as motive, sanction, and functional test but does not become a universal metric of truth, title, virtue, or every institutional decision.","Utility scales as motive, sanction, and functional test but does not become a universal metric of truth, title, virtue, or every institutional decision."]],"WB_THN:CGD-06":[["[Scales upward] The prohibition on essence-first explanation governs the treatment of mind, causation, self, value, property, morality, and authority.","The prohibition on essence-first explanation governs the treatment of mind, causation, self, value, property, morality, and authority."]],"WB_THN:CGD-07":[["[Scales upward] Relation-mediated force becomes the common architecture connecting factual belief, passion, social valuation, institutional adherence, and political efficacy.","Relation-mediated force becomes the common architecture connecting factual belief, passion, social valuation, institutional adherence, and political efficacy."]],"WB_THN:CGD-08":[["[Bridge] Ideas, imagination, and represented conditions connect perceptual derivation to belief, sympathy, comparison, social object-construction, and moral classification.","Ideas, imagination, and represented conditions connect perceptual derivation to belief, sympathy, comparison, social object-construction, and moral classification."]],"WB_THN:CGD-09":[["[Bridge] Custom and repetition connect mental regularity to social expectation, reciprocal convention, institutional persistence, and normative inertia.","Custom and repetition connect mental regularity to social expectation, reciprocal convention, institutional persistence, and normative inertia."]],"WB_THN:CGD-10":[["[Catalyst] Counterfeit belief, contradictory affect, reversed social valence, and recurrent institutional failure scale upward as anomaly-mechanisms forcing restriction, differentiation, and reversal.","Counterfeit belief, contradictory affect, reversed social valence, and recurrent institutional failure scale upward as anomaly-mechanisms forcing restriction, differentiation, and reversal."]],"WB_THN:CGD-11":[["[Superseded and recoded] Passive copying, sealed faculties, linear causation, pre-social subjects, intrinsic value, and unconditional authority are replaced by recursive production, distributed routing, constituted objects, and conditional legitimacy.","Passive copying, sealed faculties, linear causation, pre-social subjects, intrinsic value, and unconditional authority are replaced by recursive production, distributed routing, constituted objects, and conditional legitimacy."]],"WB_THN:ALT-B01":[["[Surface level] The explicit field comprises perceptions, ideas, space, time, causation, belief, selfhood, passions, social esteem, justice, property, morality, allegiance, tyranny, and resistance.","The explicit field comprises perceptions, ideas, space, time, causation, belief, selfhood, passions, social esteem, justice, property, morality, allegiance, tyranny, and resistance."]],"WB_THN:ALT-B02":[["[Structural level] Copying, relation, recombination, force-transfer, repetition, comparison, gating, feedback, convention, generalization, and functional reassessment form the distributed mechanism.","Copying, relation, recombination, force-transfer, repetition, comparison, gating, feedback, convention, generalization, and functional reassessment form the distributed mechanism."]],"WB_THN:ALT-B03":[["[Metastrategic level] Inquiry and intervention proceed by auditing provenance, widening comparison, varying circumstances, rerouting force, diagnosing temporal phase, and distinguishing local failure from general anti-function.","Inquiry and intervention proceed by auditing provenance, widening comparison, varying circumstances, rerouting force, diagnosing temporal phase, and distinguishing local failure from general anti-function."]],"WB_THN:ALT-B04":[["[Ontological / Temporal level] Reality consists of historically organized events and relations whose identities arise through recurrence, efficacy, attribution, and institutional stabilization; time can preserve, intensify, constitute, or reverse them.","Reality consists of historically organized events and relations whose identities arise through recurrence, efficacy, attribution, and institutional stabilization; time can preserve, intensify, constitute, or reverse them."]],"WB_THN:ALT-B05":[["[Social / Political level] Authority, testimony, proximity, reputation, convention, law, and reflected esteem distribute the force through which judgments, rights, hierarchies, and resistance become operative.","Authority, testimony, proximity, reputation, convention, law, and reflected esteem distribute the force through which judgments, rights, hierarchies, and resistance become operative."]],"WB_THN:ALT-B06":[["[Methodological / Performative level] The system performs its thesis by decomposing apparent unities, producing controlled excess, converting anomaly into differential analysis, and recursively testing every stabilization against its effects.","The system performs its thesis by decomposing apparent unities, producing controlled excess, converting anomaly into differential analysis, and recursively testing every stabilization against its effects."]],"CL_MEMA_01:GA-01":[["[Persistent] La matière constitue un champ d’images indépendant de la perception particulière qui le centre ou le sélectionne.","La matière constitue un champ d’images indépendant de la perception particulière qui le centre ou le sélectionne."]],"CL_MEMA_01:GA-02":[["[Persistent] Le corps est simultanément une image du champ matériel et un centre d’action capable de suspendre, choisir et transmettre des mouvements.","Le corps est simultanément une image du champ matériel et un centre d’action capable de suspendre, choisir et transmettre des mouvements."]],"CL_MEMA_01:GA-03":[["[Persistent] Le cerveau distribue les conditions motrices de l’action sans produire ni contenir la totalité représentative de la conscience.","Le cerveau distribue les conditions motrices de l’action sans produire ni contenir la totalité représentative de la conscience."]],"CL_MEMA_01:GA-04":[["[Persistent] La perception est une sélection soustractive du réel matériel en fonction des actions possibles d’un corps, non une construction ajoutée au monde.","La perception est une sélection soustractive du réel matériel en fonction des actions possibles d’un corps, non une construction ajoutée au monde."]],"CL_MEMA_01:GA-05":[["[Mutating] L’action passe du statut d’orientation utilitaire des fonctions mentales à celui d’opérateur qui inhibe, contracte et actualise le passé.","L’action passe du statut d’orientation utilitaire des fonctions mentales à celui d’opérateur qui inhibe, contracte et actualise le passé."]],"CL_MEMA_01:GA-06":[["[Mutating] La mémoire passe d’un point d’intersection entre esprit et matière à une survivance virtuelle du passé qui temporalise et subjectivise la perception.","La mémoire passe d’un point d’intersection entre esprit et matière à une survivance virtuelle du passé qui temporalise et subjectivise la perception."]],"CL_MEMA_01:GA-07":[["[Persistent] Perception, affection, souvenir et habitude ne forment pas une série homogène d’intensités, mais des régimes fonctionnels ou ontologiques distincts.","Perception, affection, souvenir et habitude ne forment pas une série homogène d’intensités, mais des régimes fonctionnels ou ontologiques distincts."]],"CL_MEMA_01:GA-08":[["[Emergent] Le passé survit selon deux modalités irréductibles : dispositif moteur incorporé au corps et image-souvenir conservée indépendamment de lui.","Le passé survit selon deux modalités irréductibles : dispositif moteur incorporé au corps et image-souvenir conservée indépendamment de lui."]],"CL_MEMA_01:GA-09":[["[Emergent] La reconnaissance se distribue entre prolongement moteur automatique et reconstruction attentive par insertion de souvenirs.","La reconnaissance se distribue entre prolongement moteur automatique et reconstruction attentive par insertion de souvenirs."]],"CL_MEMA_01:GA-10":[["[Emergent] L’attention est une boucle récursive dans laquelle la mémoire projetée reconstruit la perception qui l’a sollicitée et élargit progressivement son réseau de relations.","L’attention est une boucle récursive dans laquelle la mémoire projetée reconstruit la perception qui l’a sollicitée et élargit progressivement son réseau de relations."]],"CL_MEMA_01:GA-11":[["[Terminal] Dans le modèle reconstruit, la lésion cérébrale altère la sélection, la coordination ou l’application des souvenirs sans démontrer leur destruction.","Dans le modèle reconstruit, la lésion cérébrale altère la sélection, la coordination ou l’application des souvenirs sans démontrer leur destruction."]],"CL_MEMA_01:GA-12":[["[Attractor] Le sujet est la temporalisation d’un centre d’action : la mémoire contracte le passé virtuel au point mobile où il peut infléchir l’avenir.","Le sujet est la temporalisation d’un centre d’action : la mémoire contracte le passé virtuel au point mobile où il peut infléchir l’avenir."]],"CL_MEMA_01:GA-13":[["[Terminal] Le mouvement matériel peut conditionner le passage d’une représentation à l’action, mais il ne peut engendrer par lui-même une représentation qualitative.","Le mouvement matériel peut conditionner le passage d’une représentation à l’action, mais il ne peut engendrer par lui-même une représentation qualitative."]],"CL_MEMA_01:RMD-01":[["[Stable identity] L’image demeure l’unité commune de la matière et de la perception, mais son organisation passe d’un champ acentrique d’actions réelles à un système centré d’actions virtuelles.","L’image demeure l’unité commune de la matière et de la perception, mais son organisation passe d’un champ acentrique d’actions réelles à un système centré d’actions virtuelles."]],"CL_MEMA_01:RMD-02":[["[Functional recurrence] Le cerveau conserve sa fonction de transmission motrice tout en l’étendant à l’inhibition, à la sélection et à la coordination des conditions d’actualisation.","Le cerveau conserve sa fonction de transmission motrice tout en l’étendant à l’inhibition, à la sélection et à la coordination des conditions d’actualisation."]],"CL_MEMA_01:RMD-03":[["[Mutation] L’action, d’abord principe de sélection perceptive, devient le régime temporel qui contracte le passé et décide de son efficacité présente.","L’action, d’abord principe de sélection perceptive, devient le régime temporel qui contracte le passé et décide de son efficacité présente."]],"CL_MEMA_01:RMD-04":[["[Escalation] La mémoire migre d’un terrain probatoire du dualisme vers l’opérateur de subjectivation, puis vers le mode ontologique de survivance virtuelle du passé.","La mémoire migre d’un terrain probatoire du dualisme vers l’opérateur de subjectivation, puis vers le mode ontologique de survivance virtuelle du passé."]],"CL_MEMA_01:RMD-05":[["[Absorption into a higher-order structure] La perception pure accomplit sa fonction en établissant l’extériorité de la perception, puis est absorbée dans la perception concrète comme couche limite toujours mêlée de mémoire et d’affection.","La perception pure accomplit sa fonction en établissant l’extériorité de la perception, puis est absorbée dans la perception concrète comme couche limite toujours mêlée de mémoire et d’affection."]],"CL_MEMA_01:RMD-06":[["[Displacement] La pathologie quitte le modèle de la destruction d’un contenu pour devenir une cartographie des ruptures entre perception, attitude motrice, actualisation et action.","La pathologie quitte le modèle de la destruction d’un contenu pour devenir une cartographie des ruptures entre perception, attitude motrice, actualisation et action."]],"CL_MEMA_01:RMD-07":[["[Terminal transformation] Le conflit entre matérialisme et spiritualisme est déplacé de la production de la perception vers la conservation et l’actualisation du passé.","Le conflit entre matérialisme et spiritualisme est déplacé de la production de la perception vers la conservation et l’actualisation du passé."]],"CL_MEMA_01:CGD-01":[["[Local] La perception pure, la douleur, l’éducation sensorielle et les schèmes verbaux sont des machines analytiques locales ; elles ne portent le cluster qu’en tant qu’épreuves différentielles des fonctions de passage.","La perception pure, la douleur, l’éducation sensorielle et les schèmes verbaux sont des machines analytiques locales ; elles ne portent le cluster qu’en tant qu’épreuves différentielles des fonctions de passage."]],"CL_MEMA_01:CGD-02":[["[Scale change] La matière-image cesse d’être seulement une solution au débat réaliste-idéaliste et devient le fond ontologique nécessaire à la limitation du pouvoir représentatif du cerveau.","La matière-image cesse d’être seulement une solution au débat réaliste-idéaliste et devient le fond ontologique nécessaire à la limitation du pouvoir représentatif du cerveau."]],"CL_MEMA_01:CGD-03":[["[Connector] L’orientation vers l’action relie l’ontologie des images, la sélection perceptive, l’inhibition mnésique, la reconnaissance et l’interprétation des lésions.","L’orientation vers l’action relie l’ontologie des images, la sélection perceptive, l’inhibition mnésique, la reconnaissance et l’interprétation des lésions."]],"CL_MEMA_01:CGD-04":[["[Catalyst] La mémoire catalyse le passage d’une topologie du corps parmi les images à une ontologie temporelle du passé virtuel.","La mémoire catalyse le passage d’une topologie du corps parmi les images à une ontologie temporelle du passé virtuel."]],"CL_MEMA_01:CGD-05":[["[Recoded] La corrélation psychophysiologique n’est plus l’indice d’une équivalence entre séries mentale et cérébrale, mais celui de leur coordination autour d’une même possibilité d’action.","La corrélation psychophysiologique n’est plus l’indice d’une équivalence entre séries mentale et cérébrale, mais celui de leur coordination autour d’une même possibilité d’action."]],"CL_MEMA_01:CGD-06":[["[Obsolescent] Les modèles du cerveau-magasin, de l’association linéaire et de la représentation comme copie deviennent inutilisables dès que le système adopte la sélection et l’actualisation comme opérations fondamentales.","Les modèles du cerveau-magasin, de l’association linéaire et de la représentation comme copie deviennent inutilisables dès que le système adopte la sélection et l’actualisation comme opérations fondamentales."]],"CL_MEMA_01:ALT-B01":[["[Surface level] Les objets explicites sont les images matérielles, le corps, le cerveau, la perception, les deux mémoires, les reconnaissances et leurs troubles.","Les objets explicites sont les images matérielles, le corps, le cerveau, la perception, les deux mémoires, les reconnaissances et leurs troubles."]],"CL_MEMA_01:ALT-B02":[["[Structural level] La machine active articule indétermination, circuit sensori-moteur, sélection perceptive, inhibition du passé, projection mnésique et insertion dans l’action.","La machine active articule indétermination, circuit sensori-moteur, sélection perceptive, inhibition du passé, projection mnésique et insertion dans l’action."]],"CL_MEMA_01:ALT-B03":[["[Metastrategic level] Les oppositions d’école sont remplacées par l’analyse différentielle des fonctions de production supposée, de sélection réelle, de conservation et d’actualisation.","Les oppositions d’école sont remplacées par l’analyse différentielle des fonctions de production supposée, de sélection réelle, de conservation et d’actualisation."]],"CL_MEMA_01:ALT-B04":[["[Ontological / Temporal level] Le réel combine un présent matériel actif, un passé virtuellement conservé et un avenir défini par la latitude motrice du corps.","Le réel combine un présent matériel actif, un passé virtuellement conservé et un avenir défini par la latitude motrice du corps."]],"CL_MEMA_01:ALT-B05":[["[Methodological / Performative level] La forme de l’argument accomplit sa thèse en abstrayant d’abord la mémoire pour isoler une fonction, puis en la réintroduisant afin de reconstruire récursivement l’objet à un niveau plus complexe.","La forme de l’argument accomplit sa thèse en abstrayant d’abord la mémoire pour isoler une fonction, puis en la réintroduisant afin de reconstruire récursivement l’objet à un niveau plus complexe."]],"CL_MEMA_02:GA-01":[["[Persistent] L’action constitue la norme de sélection qui organise la perception, l’actualisation mnésique et la conscience corporelle.","L’action constitue la norme de sélection qui organise la perception, l’actualisation mnésique et la conscience corporelle."]],"CL_MEMA_02:GA-02":[["[Persistent] Le corps et le cerveau relaient, sélectionnent et actualisent les représentations sans les produire ni les conserver.","Le corps et le cerveau relaient, sélectionnent et actualisent les représentations sans les produire ni les conserver."]],"CL_MEMA_02:GA-03":[["[Persistent] Le réel excède l’actuel conscient ; l’absence d’action présente ne constitue donc pas un critère d’inexistence.","Le réel excède l’actuel conscient ; l’absence d’action présente ne constitue donc pas un critère d’inexistence."]],"CL_MEMA_02:GA-04":[["[Mutating] La perception passe du statut d’état interne à celui de sélection objective et partielle d’actions virtuelles dans les choses.","La perception passe du statut d’état interne à celui de sélection objective et partielle d’actions virtuelles dans les choses."]],"CL_MEMA_02:GA-05":[["[Persistent] Le passé subsiste virtuellement dans la mémoire pure indépendamment de sa conservation cérébrale.","Le passé subsiste virtuellement dans la mémoire pure indépendamment de sa conservation cérébrale."]],"CL_MEMA_02:GA-06":[["[Mutating] Le présent et la conscience désignent l’efficacité agissante d’un état plutôt que la totalité de ce qui existe psychologiquement.","Le présent et la conscience désignent l’efficacité agissante d’un état plutôt que la totalité de ce qui existe psychologiquement."]],"CL_MEMA_02:GA-07":[["[Emergent] Toute perception concrète résulte d’une synthèse durable entre présence matérielle, affection corporelle et contraction mémorielle.","Toute perception concrète résulte d’une synthèse durable entre présence matérielle, affection corporelle et contraction mémorielle."]],"CL_MEMA_02:GA-08":[["[Persistent] La réalité doit être saisie comme continuité de devenir et de transformations, non comme assemblage d’états isolés.","La réalité doit être saisie comme continuité de devenir et de transformations, non comme assemblage d’états isolés."]],"CL_MEMA_02:GA-09":[["[Persistent] L’espace et le temps homogènes sont des instruments pratiques de division et de fixation, non les formes originaires du réel.","L’espace et le temps homogènes sont des instruments pratiques de division et de fixation, non les formes originaires du réel."]],"CL_MEMA_02:GA-10":[["[Emergent] L’extension, la tension, la contraction et le rythme convertissent les oppositions absolues en différences graduelles de durée.","L’extension, la tension, la contraction et le rythme convertissent les oppositions absolues en différences graduelles de durée."]],"CL_MEMA_02:GA-11":[["[Terminal] La matière tend à répéter des moments équivalents, tandis que l’esprit conserve le passé et l’engage dans une action capable de nouveauté.","La matière tend à répéter des moments équivalents, tandis que l’esprit conserve le passé et l’engage dans une action capable de nouveauté."]],"CL_MEMA_02:GA-12":[["[Attractor] L’union du corps et de l’esprit réside dans le passage opératoire du virtuel à l’agissant, non dans une causalité représentative ou un pont extérieur.","L’union du corps et de l’esprit réside dans le passage opératoire du virtuel à l’agissant, non dans une causalité représentative ou un pont extérieur."]],"CL_MEMA_02:GA-13":[["[Terminal] La liberté croît avec la contraction du passé et la pluralité des réponses motrices, tout en restant organisée avec la nécessité matérielle.","La liberté croît avec la contraction du passé et la pluralité des réponses motrices, tout en restant organisée avec la nécessité matérielle."]],"WB_MEMA:GA-01":[["[Persistent] L’action est la norme transversale qui sélectionne la perception, inhibe ou actualise le souvenir et organise les réponses corporelles.","L’action est la norme transversale qui sélectionne la perception, inhibe ou actualise le souvenir et organise les réponses corporelles."],["[Persistent] Action is the transversal norm that selects perception, inhibits or actualizes memory, and organizes bodily responses.","Action is the transversal norm that selects perception, inhibits or actualizes memory, and organizes bodily responses."]],"WB_MEMA:GA-02":[["[Mutating] La matière passe du champ acentrique d’images à une continuité de transformations rythmiques sans devenir une substance cachée derrière ses manifestations.","La matière passe du champ acentrique d’images à une continuité de transformations rythmiques sans devenir une substance cachée derrière ses manifestations."],["[Mutating] Matter moves from the acentric field of images to a continuity of rhythmic transformations without becoming a substance hidden behind its manifestations.","Matter moves from the acentric field of images to a continuity of rhythmic transformations without becoming a substance hidden behind its manifestations."]],"WB_MEMA:GA-03":[["[Persistent] Le corps est une image différenciée en centre d’action, capable de fermer certains accès et de retarder la conversion de l’excitation en mouvement.","Le corps est une image différenciée en centre d’action, capable de fermer certains accès et de retarder la conversion de l’excitation en mouvement."],["[Persistent] The body is an image differentiated into a center of action, capable of closing certain accesses and delaying the conversion of excitation into movement.","The body is an image differentiated into a center of action, capable of closing certain accesses and delaying the conversion of excitation into movement."]],"WB_MEMA:GA-04":[["[Persistent] Le cerveau règle les conditions motrices, sélectives et inhibitrices de l’actualisation sans produire ni conserver les représentations qu’il rend efficaces.","Le cerveau règle les conditions motrices, sélectives et inhibitrices de l’actualisation sans produire ni conserver les représentations qu’il rend efficaces."],["[Persistent] The brain regulates the motor, selective, and inhibitory conditions of actualization without producing or preserving the representations it renders effective.","The brain regulates the motor, selective, and inhibitory conditions of actualization without producing or preserving the representations it renders effective."]],"WB_MEMA:GA-05":[["[Mutating] La perception passe d’une soustraction limite du champ matériel à une synthèse concrète de présence, d’affection et de contraction mémorielle.","La perception passe d’une soustraction limite du champ matériel à une synthèse concrète de présence, d’affection et de contraction mémorielle."],["[Mutating] Perception moves from a subtractive limit of the material field to a concrete synthesis of presence, affection, and memorial contraction.","Perception moves from a subtractive limit of the material field to a concrete synthesis of presence, affection, and memorial contraction."]],"WB_MEMA:GA-06":[["[Mutating] La mémoire passe de la survivance virtuelle du passé au principe temporel de subjectivation, d’indétermination et de liberté.","La mémoire passe de la survivance virtuelle du passé au principe temporel de subjectivation, d’indétermination et de liberté."],["[Mutating] Memory moves from the virtual survival of the past to the temporal principle of subjectivation, indetermination, and freedom.","Memory moves from the virtual survival of the past to the temporal principle of subjectivation, indetermination, and freedom."]],"WB_MEMA:GA-07":[["[Persistent] Le réel excède l’actuel conscient : l’inefficacité présente ne constitue ni inexistence ni annihilation ontologique.","Le réel excède l’actuel conscient : l’inefficacité présente ne constitue ni inexistence ni annihilation ontologique."],["[Persistent] The real exceeds the conscious actual: present inefficacy constitutes neither nonexistence nor ontological annihilation.","The real exceeds the conscious actual: present inefficacy constitutes neither nonexistence nor ontological annihilation."]],"WB_MEMA:GA-08":[["[Emergent] L’union du corps et de l’esprit consiste en une continuité opératoire entre des termes distincts, le corps réglant le passage du virtuel à l’agissant.","L’union du corps et de l’esprit consiste en une continuité opératoire entre des termes distincts, le corps réglant le passage du virtuel à l’agissant."],["[Emergent] The union of body and mind consists in an operative continuity between distinct terms, the body regulating the passage from the virtual to the acting.","The union of body and mind consists in an operative continuity between distinct terms, the body regulating the passage from the virtual to the acting."]],"WB_MEMA:GA-09":[["[Emergent] La spatialisation est un produit pratique de division et de fixation dont la réification engendre les antinomies métaphysiques.","La spatialisation est un produit pratique de division et de fixation dont la réification engendre les antinomies métaphysiques."],["[Emergent] Spatialization is a practical product of division and fixation whose reification engenders metaphysical antinomies.","Spatialization is a practical product of division and fixation whose reification engenders metaphysical antinomies."]],"WB_MEMA:GA-10":[["[Terminal] La différence entre matière et esprit est finalement temporelle : répétition de moments équivalents contre conservation transformatrice du passé.","La différence entre matière et esprit est finalement temporelle : répétition de moments équivalents contre conservation transformatrice du passé."],["[Terminal] The difference between matter and mind is ultimately temporal: repetition of equivalent moments versus transformative preservation of the past.","The difference between matter and mind is ultimately temporal: repetition of equivalent moments versus transformative preservation of the past."]],"WB_MEMA:GA-11":[["[Attractor] La contraction règle conjointement la densité perceptive, la mobilisation du passé, les rythmes matériels et les degrés d’agentivité.","La contraction règle conjointement la densité perceptive, la mobilisation du passé, les rythmes matériels et les degrés d’agentivité."],["[Attractor] Contraction jointly regulates perceptual density, mobilization of the past, material rhythms, and degrees of agency.","Contraction jointly regulates perceptual density, mobilization of the past, material rhythms, and degrees of agency."]],"WB_MEMA:GA-12":[["[Terminal] La liberté est une capacité graduelle de différer la réaction et de pluraliser les réponses à l’intérieur de la nécessité matérielle.","La liberté est une capacité graduelle de différer la réaction et de pluraliser les réponses à l’intérieur de la nécessité matérielle."],["[Terminal] Freedom is a gradual capacity to defer reaction and pluralize responses within material necessity.","Freedom is a gradual capacity to defer reaction and pluralize responses within material necessity."]],"WB_MEMA:GA-13":[["[Persistent] Perception, affection, habitude et souvenir appartiennent à des régimes hétérogènes ; les degrés décrivent leurs médiations, non leur dérivation les uns des autres.","Perception, affection, habitude et souvenir appartiennent à des régimes hétérogènes ; les degrés décrivent leurs médiations, non leur dérivation les uns des autres."],["[Persistent] Perception, affection, habit, and memory belong to heterogeneous regimes; degrees describe their mediations, not their derivation from one another.","Perception, affection, habit, and memory belong to heterogeneous regimes; degrees describe their mediations, not their derivation from one another."]],"WB_MEMA:RMD-01":[["[Stable identity] L’image demeure l’unité commune du matériel et du perceptible, mais le champ acentrique d’actions devient progressivement un continuum de transformations rythmiques.","L’image demeure l’unité commune du matériel et du perceptible, mais le champ acentrique d’actions devient progressivement un continuum de transformations rythmiques."],["[Stable identity] The image remains the common unit of the material and the perceptible, but the acentric field of actions progressively becomes a continuum of rhythmic transformations.","The image remains the common unit of the material and the perceptible, but the acentric field of actions progressively becomes a continuum of rhythmic transformations."]],"WB_MEMA:RMD-02":[["[Reversal] L’action revient d’abord comme principe de sélection, puis comme origine des découpages réifiés qu’une métaphysique du continu doit renverser.","L’action revient d’abord comme principe de sélection, puis comme origine des découpages réifiés qu’une métaphysique du continu doit renverser."],["[Reversal] Action first returns as a principle of selection, then as the origin of reified divisions that a metaphysics of the continuous must reverse.","Action first returns as a principle of selection, then as the origin of reified divisions that a metaphysics of the continuous must reverse."]],"WB_MEMA:RMD-03":[["[Functional recurrence] Le cerveau conserve sa fonction de relais tout en devenant filtre, inhibiteur, commutateur et organe positif d’exclusion.","Le cerveau conserve sa fonction de relais tout en devenant filtre, inhibiteur, commutateur et organe positif d’exclusion."],["[Functional recurrence] The brain retains its function as relay while becoming filter, inhibitor, switch, and positive organ of exclusion.","The brain retains its function as relay while becoming filter, inhibitor, switch, and positive organ of exclusion."]],"WB_MEMA:RMD-04":[["[Mutation] La perception pure, d’abord limite soustractive, est absorbée dans une perception concrète où l’extraction objective est inséparable de la mémoire et de l’affection.","La perception pure, d’abord limite soustractive, est absorbée dans une perception concrète où l’extraction objective est inséparable de la mémoire et de l’affection."],["[Mutation] Pure perception, initially a subtractive limit, is absorbed into a concrete perception in which objective extraction is inseparable from memory and affection.","Pure perception, initially a subtractive limit, is absorbed into a concrete perception in which objective extraction is inseparable from memory and affection."]],"WB_MEMA:RMD-05":[["[Escalation] La mémoire s’étend de la survivance psychologique à la définition temporelle de l’esprit, puis à une réserve d’indétermination et de liberté.","La mémoire s’étend de la survivance psychologique à la définition temporelle de l’esprit, puis à une réserve d’indétermination et de liberté."],["[Escalation] Memory extends from psychological survival to the temporal definition of mind, then to a reserve of indetermination and freedom.","Memory extends from psychological survival to the temporal definition of mind, then to a reserve of indetermination and freedom."]],"WB_MEMA:RMD-06":[["[Reversal] L’espace homogène passe du statut de cadre présumé du réel à celui d’abstraction opératoire dérivée de besoins pratiques.","L’espace homogène passe du statut de cadre présumé du réel à celui d’abstraction opératoire dérivée de besoins pratiques."],["[Reversal] Homogeneous space passes from the status of presumed framework of reality to that of operative abstraction derived from practical needs.","Homogeneous space passes from the status of presumed framework of reality to that of operative abstraction derived from practical needs."]],"WB_MEMA:RMD-07":[["[Displacement] Le dualisme migre de la séparation spatiale des substances vers la différenciation temporelle entre répétition matérielle et conservation créatrice.","Le dualisme migre de la séparation spatiale des substances vers la différenciation temporelle entre répétition matérielle et conservation créatrice."],["[Displacement] Dualism migrates from the spatial separation of substances toward temporal differentiation between material repetition and creative preservation.","Dualism migrates from the spatial separation of substances toward temporal differentiation between material repetition and creative preservation."]],"WB_MEMA:RMD-08":[["[Terminal transformation] La pathologie cesse d’être une localisation de contenus et devient une cartographie des ruptures entre conservation, accès, attitude motrice et application.","La pathologie cesse d’être une localisation de contenus et devient une cartographie des ruptures entre conservation, accès, attitude motrice et application."],["[Terminal transformation] Pathology ceases to be a localization of contents and becomes a mapping of ruptures between preservation, access, motor attitude, and application.","Pathology ceases to be a localization of contents and becomes a mapping of ruptures between preservation, access, motor attitude, and application."]],"WB_MEMA:CGD-01":[["[Local] La douleur, les schèmes verbaux, la genèse des idées générales et les paradoxes du mouvement restent des dispositifs analytiques locaux servant à différencier des fonctions.","La douleur, les schèmes verbaux, la genèse des idées générales et les paradoxes du mouvement restent des dispositifs analytiques locaux servant à différencier des fonctions."],["[Local] Pain, verbal schemas, the genesis of general ideas, and the paradoxes of movement remain local analytic devices serving to differentiate functions.","Pain, verbal schemas, the genesis of general ideas, and the paradoxes of movement remain local analytic devices serving to differentiate functions."]],"WB_MEMA:CGD-02":[["[Scale change] L’ontologie des images et la restitution locale du mouvement continu changent d’échelle lorsqu’elles convergent dans une conception rythmique de la matière.","L’ontologie des images et la restitution locale du mouvement continu changent d’échelle lorsqu’elles convergent dans une conception rythmique de la matière."],["[Scale change] The ontology of images and the local restitution of continuous movement change scale when they converge in a rhythmic conception of matter.","The ontology of images and the local restitution of continuous movement change scale when they converge in a rhythmic conception of matter."]],"WB_MEMA:CGD-03":[["[Connector] L’action relie l’ontologie matérielle, la perception, la mémoire et la pathologie en fournissant le modèle général de leur articulation.","L’action relie l’ontologie matérielle, la perception, la mémoire et la pathologie en fournissant le modèle général de leur articulation."],["[Connector] Action connects material ontology, perception, memory, and pathology by supplying the general model of their articulation.","Action connects material ontology, perception, memory, and pathology by supplying the general model of their articulation."]],"WB_MEMA:CGD-04":[["[Catalyst] La mémoire convertit la topologie du corps parmi les images en ontologie temporelle, puis intègre sélection corporelle et liberté graduelle.","La mémoire convertit la topologie du corps parmi les images en ontologie temporelle, puis intègre sélection corporelle et liberté graduelle."],["[Catalyst] Memory converts the topology of the body among images into temporal ontology, then integrates bodily selection and gradual freedom.","Memory converts the topology of the body among images into temporal ontology, then integrates bodily selection and gradual freedom."]],"WB_MEMA:CGD-05":[["[Current-level emergence] L’action acquiert une double fonction indisponible localement : elle produit les découpages qui faussent la métaphysique et opère l’union du virtuel avec l’actuel.","L’action acquiert une double fonction indisponible localement : elle produit les découpages qui faussent la métaphysique et opère l’union du virtuel avec l’actuel."],["[Current-level emergence] Action acquires a double function unavailable locally: it produces the divisions that distort metaphysics and effects the union of the virtual with the actual.","Action acquires a double function unavailable locally: it produces the divisions that distort metaphysics and effects the union of the virtual with the actual."]],"WB_MEMA:CGD-06":[["[Recoded] La corrélation psychophysiologique devient coordination pragmatique : la dépendance corporelle de l’actualisation ne vaut plus comme production corporelle du contenu.","La corrélation psychophysiologique devient coordination pragmatique : la dépendance corporelle de l’actualisation ne vaut plus comme production corporelle du contenu."],["[Recoded] Psychophysiological correlation becomes pragmatic coordination: the bodily dependence of actualization no longer counts as bodily production of content.","Psychophysiological correlation becomes pragmatic coordination: the bodily dependence of actualization no longer counts as bodily production of content."]],"WB_MEMA:CGD-07":[["[Obsolescent] Les modèles du cerveau-réservoir, de l’association linéaire et du réel composé d’états immobiles sont remplacés par la sélection, l’accès et l’actualisation.","Les modèles du cerveau-réservoir, de l’association linéaire et du réel composé d’états immobiles sont remplacés par la sélection, l’accès et l’actualisation."],["[Obsolescent] The models of the brain-reservoir, linear association, and reality composed of immobile states are replaced by selection, access, and actualization.","The models of the brain-reservoir, linear association, and reality composed of immobile states are replaced by selection, access, and actualization."]],"WB_MEMA:ALT-B01":[["[Surface level] Le système traite explicitement des images, du corps, du cerveau, de la perception, des formes de mémoire, de la reconnaissance, des lésions et du mouvement matériel.","Le système traite explicitement des images, du corps, du cerveau, de la perception, des formes de mémoire, de la reconnaissance, des lésions et du mouvement matériel."],["[Surface level] The system explicitly addresses images, the body, the brain, perception, forms of memory, recognition, lesions, and material movement.","The system explicitly addresses images, the body, the brain, perception, forms of memory, recognition, lesions, and material movement."]],"WB_MEMA:ALT-B02":[["[Structural level] Ces objets sont distribués entre sélection sensori-motrice, inhibition du passé, plans de tension, projection mnésique et insertion dans l’action.","Ces objets sont distribués entre sélection sensori-motrice, inhibition du passé, plans de tension, projection mnésique et insertion dans l’action."],["[Structural level] These objects are distributed among sensorimotor selection, inhibition of the past, planes of tension, mnemonic projection, and insertion into action.","These objects are distributed among sensorimotor selection, inhibition of the past, planes of tension, mnemonic projection, and insertion into action."]],"WB_MEMA:ALT-B03":[["[Metastrategic level] L’intervention remplace les oppositions d’école et les états achevés par une analyse génétique des fonctions de sélection, de conservation et d’actualisation.","L’intervention remplace les oppositions d’école et les états achevés par une analyse génétique des fonctions de sélection, de conservation et d’actualisation."],["[Metastrategic level] The intervention replaces school oppositions and completed states with a genetic analysis of functions of selection, preservation, and actualization.","The intervention replaces school oppositions and completed states with a genetic analysis of functions of selection, preservation, and actualization."]],"WB_MEMA:ALT-B04":[["[Ontological / Temporal level] Le réel articule un présent matériel actif, un passé virtuellement conservé, une pluralité de rythmes et un avenir défini par les conduites possibles.","Le réel articule un présent matériel actif, un passé virtuellement conservé, une pluralité de rythmes et un avenir défini par les conduites possibles."],["[Ontological / Temporal level] The real articulates an active material present, a virtually preserved past, a plurality of rhythms, and a future defined by possible conduct.","The real articulates an active material present, a virtually preserved past, a plurality of rhythms, and a future defined by possible conduct."]],"WB_MEMA:ALT-B05":[["[Methodological / Performative level] La forme accomplit sa thèse en isolant des fonctions, en réintroduisant ce qu’elle avait abstrait, en revenant au continu et en reconstruisant récursivement ses différenciations.","La forme accomplit sa thèse en isolant des fonctions, en réintroduisant ce qu’elle avait abstrait, en revenant au continu et en reconstruisant récursivement ses différenciations."],["[Methodological / Performative level] The form accomplishes its thesis by isolating functions, reintroducing what it had abstracted, returning to the continuous, and recursively reconstructing its differentiations.","The form accomplishes its thesis by isolating functions, reintroducing what it had abstracted, returning to the continuous, and recursively reconstructing its differentiations."]],"XR_KPR_THN:RSN-01":[["The relation is strong, mixed, and high-pressure: both units reconstruct valid finite cognition without unmediated metaphysical possession, but WB_THN explains objecthood through empirical-relational production while WB_KPR validates it through a priori conditions of possible experience.\nRelation Type — Mixed","The relation is strong, mixed, and high-pressure: both units reconstruct valid finite cognition without unmediated metaphysical possession, but A Treatise of Human Nature explains objecthood through empirical-relational production while The Critique of Pure Reason validates it through a priori conditions of possible experience."]],"XR_KPR_THN:RSN-02":[["Scale is symmetrical because both inputs are WB units, but project scope is not: WB_THN extends one recursive machine from cognition through affect and institutions into political resistance, whereas WB_KPR concentrates on cognitive jurisdiction and reaches morality and practical orientation only through terminal reassignment.\nRelation Type — Asymmetry","Scale is symmetrical because both inputs are WB units, but project scope is not: A Treatise of Human Nature extends one recursive machine from cognition through affect and institutions into political resistance, whereas The Critique of Pure Reason concentrates on cognitive jurisdiction and reaches morality and practical orientation only through terminal reassignment."]],"XR_KPR_THN:RSN-03":[["The strongest convergence is metacritical rather than doctrinal: both systems audit source, use, error, boundary, and correction from within finite human operations and reject an external tribunal.\nRelation Type — Convergence","The strongest convergence is metacritical rather than doctrinal: both systems audit source, use, error, boundary, and correction from within finite human operations and reject an external tribunal."]],"XR_KPR_THN:RSN-04":[["The decisive opposition concerns validation: WB_THN separates natural production from warrant and withholds intrinsic necessity, while WB_KPR treats non-empirical necessity as indispensable to objective experience.\nRelation Type — Opposition","The decisive opposition concerns validation: A Treatise of Human Nature separates natural production from warrant and withholds intrinsic necessity, while The Critique of Pure Reason treats non-empirical necessity as indispensable to objective experience."]],"XR_KPR_THN:RSN-05":[["The open diagnostic is whether transcendental conditions can remain non-empirical validity conditions while entering WB_THN’s recursive histories of acquisition, stabilization, institutionalization, and correction; immunity from history privileges WB_KPR, while historical revisability mutates the Kantian a priori.\nRelation Type — Mutation","The open diagnostic is whether transcendental conditions can remain non-empirical validity conditions while entering A Treatise of Human Nature’s recursive histories of acquisition, stabilization, institutionalization, and correction; immunity from history privileges The Critique of Pure Reason, while historical revisability mutates the Kantian a priori."]],"XR_KPR_THN:RSN-06":[["The units are strongly comparable and conflictually synthesizable, narrowly integrable at the level of audit procedures, conditionally hybridizable, and not yet supportable as a historical genealogy.\nRelation Type — Mixed","The units are strongly comparable and conflictually synthesizable, narrowly integrable at the level of audit procedures, conditionally hybridizable, and not yet supportable as a historical genealogy."]],"XR_KPR_THN:DRT-01":[["Finitude is a genuine convergence: neither unit permits cognition to escape mediation, temporal limitation, self-opacity, or recurrent exposure to error.\nRelation Type — Convergence","Finitude is a genuine convergence: neither unit permits cognition to escape mediation, temporal limitation, self-opacity, or recurrent exposure to error."]],"XR_KPR_THN:DRT-02":[["Their critical directions diverge: WB_THN moves from inaccessible grounds back to experienced materials and production histories, whereas WB_KPR moves from empirical insufficiency to non-empirical conditions and then restricts those conditions to possible experience.\nRelation Type — Divergence","Their critical directions diverge: A Treatise of Human Nature moves from inaccessible grounds back to experienced materials and production histories, whereas The Critique of Pure Reason moves from empirical insufficiency to non-empirical conditions and then restricts those conditions to possible experience."]],"XR_KPR_THN:DRT-03":[["Necessity is the dominant opposition: WB_THN reconstructs causal expectation through relation, force, repetition, and custom without intrinsic connection; WB_KPR requires a priori synthesis for natural necessity and objective validity.\nRelation Type — Opposition","Necessity is the dominant opposition: A Treatise of Human Nature reconstructs causal expectation through relation, force, repetition, and custom without intrinsic connection; The Critique of Pure Reason requires a priori synthesis for natural necessity and objective validity."]],"XR_KPR_THN:DRT-04":[["Objectivity permits asymmetrical translation but not equivalence: stable relational efficacy in WB_THN concerns operational reality, while necessary validity in WB_KPR concerns law-governed appearances under universally binding finite conditions.\nRelation Type — Translation","Objectivity permits asymmetrical translation but not equivalence: stable relational efficacy in A Treatise of Human Nature concerns operational reality, while necessary validity in The Critique of Pure Reason concerns law-governed appearances under universally binding finite conditions."]],"XR_KPR_THN:DRT-05":[["The subject undergoes opposed decenterings: WB_THN removes substantial origin and retains a historically produced relay, while WB_KPR removes substantial self-knowledge but preserves a transcendental condition-site and practical self-legislation.\nRelation Type — Divergence","The subject undergoes opposed decenterings: A Treatise of Human Nature removes substantial origin and retains a historically produced relay, while The Critique of Pure Reason removes substantial self-knowledge but preserves a transcendental condition-site and practical self-legislation."]],"XR_KPR_THN:DRT-06":[["Their apophatic structures overlap around inaccessible metaphysical possession and absent external certification, but diverge because WB_KPR requires the unknowable as a positive limit-correlate while WB_THN refuses unknown substance or intrinsic power explanatory work.\nRelation Type — Mixed","Their apophatic structures overlap around inaccessible metaphysical possession and absent external certification, but diverge because The Critique of Pure Reason requires the unknowable as a positive limit-correlate while A Treatise of Human Nature refuses unknown substance or intrinsic power explanatory work."]],"XR_KPR_THN:DRT-07":[["Failure is a shared diagnostic operator: anomaly, contradiction, overextension, and proof-collapse expose unrestricted mechanisms and trigger differentiated reconstruction rather than simple abandonment.\nRelation Type — Convergence","Failure is a shared diagnostic operator: anomaly, contradiction, overextension, and proof-collapse expose unrestricted mechanisms and trigger differentiated reconstruction rather than simple abandonment."]],"XR_KPR_THN:DRT-08":[["Institutional constitution is a non-equivalent zone: WB_THN supplies detailed transitions from custom to convention, right, morality, authority, and resistance, while WB_KPR supplies architectonic and practical jurisdiction without an equivalent social-institutional genesis.\nRelation Type — Asymmetry","Institutional constitution is a non-equivalent zone: A Treatise of Human Nature supplies detailed transitions from custom to convention, right, morality, authority, and resistance, while The Critique of Pure Reason supplies architectonic and practical jurisdiction without an equivalent social-institutional genesis."]],"XR_KPR_THN:RSM-01":[["Comparative synthesis is strongly recommended as the first run, provided it compares operational roles—source, condition, production, validity, boundary, correction, and end—rather than shared vocabulary.\nRelation Type — Comparative","Comparative synthesis is strongly recommended as the first run, provided it compares operational roles—source, condition, production, validity, boundary, correction, and end—rather than shared vocabulary."]],"XR_KPR_THN:RSM-02":[["Conflictual synthesis is strongly recommended because the status of necessity, the constitution of experience, the function of the subject, and the source of normativity form explicit opposed axioms rather than merely different emphases.\nRelation Type — Conflictual","Conflictual synthesis is strongly recommended because the status of necessity, the constitution of experience, the function of the subject, and the source of normativity form explicit opposed axioms rather than merely different emphases."]],"XR_KPR_THN:RSM-03":[["Integrative synthesis is recommended only at the metastrategic level: WB_THN’s provenance–force–history audit can be coupled to WB_KPR’s condition–application–jurisdiction audit without treating either audit as a substitute for the other.\nRelation Type — Integrative","Integrative synthesis is recommended only at the metastrategic level: A Treatise of Human Nature’s provenance–force–history audit can be coupled to The Critique of Pure Reason’s condition–application–jurisdiction audit without treating either audit as a substitute for the other."]],"XR_KPR_THN:RSM-04":[["Hybridizing synthesis is conditionally recommended after comparative and conflictual runs establish non-conversion rules; its legitimate target is a dual-audit architecture, not a compromise between custom and a priori necessity.\nRelation Type — Hybridizing","Hybridizing synthesis is conditionally recommended after comparative and conflictual runs establish non-conversion rules; its legitimate target is a dual-audit architecture, not a compromise between custom and a priori necessity."]],"XR_KPR_THN:USM-01":[["A historical Genealogical run is not currently warranted: the supplied units document internal recurrence and mutation but provide no cross-lineage transmission, adoption, revision, or response chain.\nRelation Type — Non-Relation","A historical Genealogical run is not currently warranted: the supplied units document internal recurrence and mutation but provide no cross-lineage transmission, adoption, revision, or response chain."]],"XR_KPR_THN:USM-02":[["Unrestricted Integrative synthesis would be distortion-heavy because it would either naturalize the a priori into custom or elevate customary stabilization into necessary objective validity.\nRelation Type — Opposition","Unrestricted Integrative synthesis would be distortion-heavy because it would either naturalize the a priori into custom or elevate customary stabilization into necessary objective validity."]],"XR_KPR_THN:USM-03":[["A vocabulary-led synthesis around “experience,” “subject,” “time,” “objectivity,” or “critique” is unrecommended because each term occupies different generative sequences and carries different warrants.\nRelation Type — Translation","A vocabulary-led synthesis around “experience,” “subject,” “time,” “objectivity,” or “critique” is unrecommended because each term occupies different generative sequences and carries different warrants."]],"XR_KPR_THN:USM-04":[["Immediate Hybridizing or Strange-Child production without prior conflict mapping would conceal the unresolved rule governing whether historical failure may revise transcendental conditions or only their empirical applications.\nRelation Type — Strange-Child Potential","Immediate Hybridizing or Strange-Child production without prior conflict mapping would conceal the unresolved rule governing whether historical failure may revise transcendental conditions or only their empirical applications."]],"XR_KPR_THN:USM-05":[["Full normative integration is distortion-heavy because WB_THN derives transpersonal normativity through passions, conventions, institutions, and corrected standpoints, whereas WB_KPR assigns terminal authority to autonomous practical reason.\nRelation Type — Opposition","Full normative integration is distortion-heavy because A Treatise of Human Nature derives transpersonal normativity through passions, conventions, institutions, and corrected standpoints, whereas The Critique of Pure Reason assigns terminal authority to autonomous practical reason."]],"XR_KPR_THN:TLC-01":[["“Experience” must be split into empirical provenance and constituted validity-field: WB_THN uses experience as the admissible source and testing field, while WB_KPR treats possible experience as an a priori-conditioned tribunal.\nRelation Type — Translation","“Experience” must be split into empirical provenance and constituted validity-field: A Treatise of Human Nature uses experience as the admissible source and testing field, while The Critique of Pure Reason treats possible experience as an a priori-conditioned tribunal."]],"XR_KPR_THN:TLC-02":[["Custom cannot translate into a priori necessity: custom explains generated expectation and stabilized transition, whereas the a priori specifies what must condition universally valid experience.\nRelation Type — Opposition","Custom cannot translate into a priori necessity: custom explains generated expectation and stabilized transition, whereas the a priori specifies what must condition universally valid experience."]],"XR_KPR_THN:TLC-03":[["Relation and category can be compared only as routing functions: relation organizes transitions across WB_THN’s empirical-social machinery, while categories require deduction and schematism before objectively determining appearances.\nRelation Type — Comparative","Relation and category can be compared only as routing functions: relation organizes transitions across A Treatise of Human Nature’s empirical-social machinery, while categories require deduction and schematism before objectively determining appearances."]],"XR_KPR_THN:TLC-04":[["Efficacy and objective validity must remain separate coordinates: durable effects may establish practical reality in WB_THN but cannot by themselves meet WB_KPR’s condition of necessary validity for appearances.\nRelation Type — Divergence","Efficacy and objective validity must remain separate coordinates: durable effects may establish practical reality in A Treatise of Human Nature but cannot by themselves meet The Critique of Pure Reason’s condition of necessary validity for appearances."]],"XR_KPR_THN:TLC-05":[["Subject-translation requires role partition: empirical relay, socially represented identity, transcendental synthesis-condition, self-critical reason, and practical agent cannot be compressed into one subject-function.\nRelation Type — Translation","Subject-translation requires role partition: empirical relay, socially represented identity, transcendental synthesis-condition, self-critical reason, and practical agent cannot be compressed into one subject-function."]],"XR_KPR_THN:TLC-06":[["Time requires a two-register translation: WB_KPR’s pure temporal form and schema-field condition finite objectivity, whereas WB_THN’s succession, repetition, sedimentation, and thresholds produce historical transformations.\nRelation Type — Translation","Time requires a two-register translation: The Critique of Pure Reason’s pure temporal form and schema-field condition finite objectivity, whereas A Treatise of Human Nature’s succession, repetition, sedimentation, and thresholds produce historical transformations."]],"XR_KPR_THN:TLC-07":[["Correction and critique form the strongest bridge if translated as immanent restriction of overextended operations: source-audit and functional reassessment correspond structurally, but not criterially, to jurisdictional reassignment.\nRelation Type — Convergence","Correction and critique form the strongest bridge if translated as immanent restriction of overextended operations: source-audit and functional reassessment correspond structurally, but not criterially, to jurisdictional reassignment."]],"XR_KPR_THN:TLC-08":[["WB_THN’s inaccessible origin cannot be identified with WB_KPR’s thing in itself: the former withdraws explanatory authority from unknown grounds, while the latter preserves an unknowable correlate required to mark finitude.\nRelation Type — Divergence","A Treatise of Human Nature’s inaccessible origin cannot be identified with The Critique of Pure Reason’s thing in itself: the former withdraws explanatory authority from unknown grounds, while the latter preserves an unknowable correlate required to mark finitude."]],"XR_KPR_THN:TLC-09":[["Normative translation requires a genesis–authority split: WB_THN can supply histories of normative production and institutional efficacy, but these histories cannot silently become WB_KPR’s practical necessity; conversely, practical necessity cannot substitute for institutional genesis.\nRelation Type — Translation","Normative translation requires a genesis–authority split: A Treatise of Human Nature can supply histories of normative production and institutional efficacy, but these histories cannot silently become The Critique of Pure Reason’s practical necessity; conversely, practical necessity cannot substitute for institutional genesis."]],"XR_KPR_THN:TLC-10":[["The institutional asymmetry must be preserved by diagnostic insertion rather than completion: WB_KPR’s tribunal and architectonic may illuminate rule-assignment, but they do not independently generate WB_THN’s conventions, rights, political functions, or resistance thresholds.\nRelation Type — Asymmetry","The institutional asymmetry must be preserved by diagnostic insertion rather than completion: The Critique of Pure Reason’s tribunal and architectonic may illuminate rule-assignment, but they do not independently generate A Treatise of Human Nature’s conventions, rights, political functions, or resistance thresholds."]],"XR_KPR_THN:CFP-01":[["Necessity pressure is maximal: WB_THN denies intrinsic necessary connection and reconstructs expectation through custom, while WB_KPR holds empirical derivation of necessity to be system-destroying.\nRelation Type — Opposition","Necessity pressure is maximal: A Treatise of Human Nature denies intrinsic necessary connection and reconstructs expectation through custom, while The Critique of Pure Reason holds empirical derivation of necessity to be system-destroying."]],"XR_KPR_THN:CFP-02":[["Experience-constitution pressure is maximal: WB_THN begins explanation inside experienced operations, whereas WB_KPR argues that experience itself presupposes a priori forms, categories, synthesis, and schematism.\nRelation Type — Opposition","Experience-constitution pressure is maximal: A Treatise of Human Nature begins explanation inside experienced operations, whereas The Critique of Pure Reason argues that experience itself presupposes a priori forms, categories, synthesis, and schematism."]],"XR_KPR_THN:CFP-03":[["Subject pressure is high: WB_THN’s anti-sovereign relay conflicts with WB_KPR’s transcendental condition-site and autonomous practical legislator, although both reject a cognizable substantial ego.\nRelation Type — Mixed","Subject pressure is high: A Treatise of Human Nature’s anti-sovereign relay conflicts with The Critique of Pure Reason’s transcendental condition-site and autonomous practical legislator, although both reject a cognizable substantial ego."]],"XR_KPR_THN:CFP-04":[["Metaphysical-reserve pressure is high: WB_KPR requires non-objective noumenal and supersensible orientation, while WB_THN’s anti-additive naturalism treats unknown substance and transcendent authority as explanatorily idle.\nRelation Type — Opposition","Metaphysical-reserve pressure is high: The Critique of Pure Reason requires non-objective noumenal and supersensible orientation, while A Treatise of Human Nature’s anti-additive naturalism treats unknown substance and transcendent authority as explanatorily idle."]],"XR_KPR_THN:CFP-05":[["Normative-authority pressure is high: historically generated conventions and generalized sentiments cannot directly translate into autonomous practical necessity, and practical self-legislation cannot explain the social production and failure of institutions.\nRelation Type — Opposition","Normative-authority pressure is high: historically generated conventions and generalized sentiments cannot directly translate into autonomous practical necessity, and practical self-legislation cannot explain the social production and failure of institutions."]],"XR_KPR_THN:CFP-06":[["Temporal pressure is medium-high: both make time constitutive, but one makes it an a priori form and limit of cognition while the other makes recurrence and sedimentation capable of producing and reversing ontological-political status.\nRelation Type — Mutation","Temporal pressure is medium-high: both make time constitutive, but one makes it an a priori form and limit of cognition while the other makes recurrence and sedimentation capable of producing and reversing ontological-political status."]],"XR_KPR_THN:CFP-07":[["Closure pressure is medium-high: WB_KPR secures invariant jurisdictional distinctions, whereas WB_THN keeps every stabilization open to functional and historical reclassification.\nRelation Type — Divergence","Closure pressure is medium-high: The Critique of Pure Reason secures invariant jurisdictional distinctions, whereas A Treatise of Human Nature keeps every stabilization open to functional and historical reclassification."]],"XR_KPR_THN:CFP-08":[["Conflict remains productive rather than terminal because both distinguish effective production from legitimate use and convert failure into a demand for restricted reconstruction.\nRelation Type — Convergence","Conflict remains productive rather than terminal because both distinguish effective production from legitimate use and convert failure into a demand for restricted reconstruction."]],"XR_KPR_THN:SCF-01":[["Strange-Child feasibility is conditional but substantial: the parent units supply non-redundant machines of provenance, production, validity, limitation, recursion, and correction whose controlled collision could generate a dual-jurisdiction offspring.\nRelation Type — Strange-Child Potential","Strange-Child feasibility is conditional but substantial: the parent units supply non-redundant machines of provenance, production, validity, limitation, recursion, and correction whose controlled collision could generate a dual-jurisdiction offspring."]],"XR_KPR_THN:SCF-02":[["The child becomes genuine only if every claim must pass two irreducible tests—how it is generated and stabilized, and under what conditions it is valid—without allowing genealogy to prove validity or validity to erase genesis.\nRelation Type — Strange-Child Potential","The child becomes genuine only if every claim must pass two irreducible tests—how it is generated and stabilized, and under what conditions it is valid—without allowing genealogy to prove validity or validity to erase genesis."]],"XR_KPR_THN:SCF-03":[["Non-subordination is mandatory: assigning WB_KPR sole authority over warrant would reduce WB_THN to causal background, while allowing WB_THN’s historical recursion to revise all conditions without constraint would dissolve WB_KPR’s a priori function.\nRelation Type — Strange-Child Potential","Non-subordination is mandatory: assigning The Critique of Pure Reason sole authority over warrant would reduce A Treatise of Human Nature to causal background, while allowing A Treatise of Human Nature’s historical recursion to revise all conditions without constraint would dissolve The Critique of Pure Reason’s a priori function."]],"XR_KPR_THN:SCF-04":[["The required mutation rule must specify whether anomalies revise only empirical applications, revise the articulation of validity conditions, or transform the condition-set itself; without that rule the prospective child remains an unstable juxtaposition.\nRelation Type — Mutation","The required mutation rule must specify whether anomalies revise only empirical applications, revise the articulation of validity conditions, or transform the condition-set itself; without that rule the prospective child remains an unstable juxtaposition."]],"XR_KPR_THN:SCF-05":[["The strongest emergent capacity would be reciprocal audit: transcendental restriction would block the conversion of stable efficacy into warrant, while recursive genealogy would expose how supposedly lawful distinctions are acquired, circulated, institutionalized, and made practically authoritative.\nRelation Type — Strange-Child Potential","The strongest emergent capacity would be reciprocal audit: transcendental restriction would block the conversion of stable efficacy into warrant, while recursive genealogy would expose how supposedly lawful distinctions are acquired, circulated, institutionalized, and made practically authoritative."]],"XR_KPR_THN:SCF-06":[["Strange-Child generation should fail if it identifies custom with necessity, relation with category, operational reality with objective validity, inaccessible origin with noumenon, or corrected convention with autonomous moral law.\nRelation Type — Strange-Child Potential","Strange-Child generation should fail if it identifies custom with necessity, relation with category, operational reality with objective validity, inaccessible origin with noumenon, or corrected convention with autonomous moral law."]],"XR_KPR_THN:SCF-07":[["The child remains underdetermined at the political-normative boundary because WB_THN supplies institutional recursion and resistance while WB_KPR supplies practical and architectonic authorization without an equivalent institutional derivation.\nRelation Type — Asymmetry","The child remains underdetermined at the political-normative boundary because A Treatise of Human Nature supplies institutional recursion and resistance while The Critique of Pure Reason supplies practical and architectonic authorization without an equivalent institutional derivation."]],"XR_KPR_THN:RNR-01":[["Run a Comparative XS first to construct a non-equivalence matrix for experience, necessity, synthesis, objectivity, subject, time, boundary, correction, and normativity.\nRelation Type — Comparative","Run a Comparative XS first to construct a non-equivalence matrix for experience, necessity, synthesis, objectivity, subject, time, boundary, correction, and normativity."]],"XR_KPR_THN:RNR-02":[["Run a Conflictual XS immediately afterward to formalize opposed axioms concerning empirical sufficiency, a priori necessity, transcendental subjectivity, metaphysical reserve, and practical authority.\nRelation Type — Conflictual","Run a Conflictual XS immediately afterward to formalize opposed axioms concerning empirical sufficiency, a priori necessity, transcendental subjectivity, metaphysical reserve, and practical authority."]],"XR_KPR_THN:RNR-03":[["Run a restricted Integrative XS at the metastrategic level, combining provenance–production audit with condition–application audit while explicitly excluding doctrinal reconciliation.\nRelation Type — Integrative","Run a restricted Integrative XS at the metastrategic level, combining provenance–production audit with condition–application audit while explicitly excluding doctrinal reconciliation."]],"XR_KPR_THN:RNR-04":[["Run a Hybridizing XS only after the preceding runs define non-conversion, revision, and parent-parity rules for the proposed dual-jurisdiction architecture.\nRelation Type — Hybridizing","Run a Hybridizing XS only after the preceding runs define non-conversion, revision, and parent-parity rules for the proposed dual-jurisdiction architecture."]],"XR_KPR_THN:RNR-05":[["Authorize an SC run only if the Hybridizing XS produces a third machine in which genesis and validity recursively constrain one another without becoming equivalent or hierarchically subordinated.\nRelation Type — Strange-Child Potential\nCARE_NEXT_RUNS\nRECOMMENDED_XS_MODES — Comparative, Conflictual, Integrative, Hybridizing\nSTRANGE_CHILD_FEASIBILITY — Conditional\nSC_PREREQUISITES — Complete comparative and conflictual runs; preserve genesis/validity, efficacy/warrant, empirical/transcendental, and institutional/practical distinctions; specify non-subordinating revision rules before child generation.\nEND_CARE_NEXT_RUNS","Authorize an SC run only if the Hybridizing XS produces a third machine in which genesis and validity recursively constrain one another without becoming equivalent or hierarchically subordinated."]]};
export function publicReadingText(item) {
  const source = String(item?.text ?? '');
  return views[item?.id]?.find(([original]) => original === source)?.[1] ?? source;
}
